INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('silly','adj.愚蠢的；不明事理的；没头脑的n.傻瓜','/ˈsɪli/','/ˈsɪli/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('misfortune','n.不幸；灾祸，灾难','/mɪsˈfɔːtʃuːn/','/mɪsˈfɔɹtʃən/','noun',["It was my fortune, or misfortune, to be called to the office of Chief Executive without any previous political training. - Ulysses S. Grant","She had to come to terms with a number of misfortunes."]);
