INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clerk','n.职员，办事员；店员；书记；记账员；<古>牧师，教士v.当销售员，当店员；当职员','/klɐːk/','/klɝk/','noun',["The law school graduate clerked for the supreme court judge for the summer."]);
