INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('campus','n.（大学）校园；大学，大学生活；校园内的草地','/ˈkæmpəs/','/ˈkæmpəs/','noun',["The campus is sixty hectares in size.","During the late 1960s, many an American campus was in a state of turmoil."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clay','n.[土壤]粘土；泥土；肉体；似黏土的东西vt.用黏土处理','/kleɪ/','/kleɪ/','noun',["The French Open is played on clay.","We went shooting clays at the weekend.","Danzig is rightfully German clay."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ride','v.骑马；乘车；依靠；漂浮n.骑；乘坐；交通工具；可供骑行的路；（乘坐汽车等的）旅行；乘骑；（乘车或骑车的）短途旅程；供乘骑的游乐设施','/ɹaɪd/','/ɹaɪd/','noun',["Can I have a ride on your bike?","That''s a nice ride; what did it cost?","Can you give me a ride?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intention','n.意图；目的；意向；愈合','/ɪnˈtɛnʃən/','/ɪnˈtɛnʃən/','noun',["It’s easy to promise anything when you have no intention of fulfilling any of it."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alloy','v.使成合金；使减低成色n.合金','','','noun',["gold without alloy"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fix','v.使固定；修理；安装；准备n.困境；方位；贿赂','/ˈfɪks/','/ˈfɪks/','noun',["That plumber''s fix is much better than the first one''s.","It rained before we repaired the roof, and were we in a fix!","We have a fix on your position."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notify','v.通告，通知；公布','/ˈnoʊtɪfaɪ/','/ˈnoʊtɪfaɪ/','verb',["Once a decision has been reached and notified to the parties it becomes binding."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passion','n.激情；热情；酷爱；盛怒','[ˈpʰæʃən]','[ˈpʰæʃən]','noun',["We share a passion for books.","It started as a hobby, but now my motorbike collection has become my passion.","We shared a night of passion."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wheat','n.小麦；小麦色','/wiːt/','/wiːt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rice','n.稻；米饭v.把…捣成米糊状','/ɹaɪs/','/ɹaɪs/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('savage','adj.野蛮的；残酷的；狂怒的；荒凉的n.未开化的人；粗鲁的人；残暴成性的人v.乱咬；粗暴的对待','/ˈsævɪdʒ/','/ˈsævɪdʒ/','noun',["No matter how anyone might savage me, I should stay strong.","His latest film was savaged by most reviewers.","a savage wilderness"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cinema','n.电影；电影院；电影业，电影制作术','/ˈsɪn.ɪ.mɑː/','/ˈsɪn.ə.mə/','noun',["The cinema is right across the street from the restaurant.","Despite the critics, he produced excellent cinema.","In the long history of Spanish cinema."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clap','v.鼓掌，拍手；啪地关上n.鼓掌；拍手声','/klæp/','/klæp/','noun',["He summoned the waiter with a clap.","Off in the distance, he heard the clap of thunder.","His father''s affection never went further than a handshake or a clap on the shoulder."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('claw','n.爪；螯，钳；爪形器具v.用爪抓（或挖）','/klɔː/','/klɔ/','noun',[]);
