INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horn','n.喇叭，号角；角v.装角于','/hɔːn/','/hɔɹn/','noun',["an umbrella with a handle made of horn","hunting horn","The shot was after the horn and therefore did not count."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hose','n.软管；长筒袜；男性穿的紧身裤v.用软管浇水；痛打','/həʊz/','/həʊz/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('auxiliary','n.助动词；辅助者，辅助物；附属机构adj.辅助的；副的；附加的','/ɔːkˈsɪli.əɹi/','/ɔːkˈsɪli.əɹi/','noun',["auxiliary troops"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spacecraft','n.[航]宇宙飞船，航天器','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('condense','v.浓缩；凝结','/kənˈdɛns/','/kənˈdɛns/','verb',["An abridged dictionary can be further condensed to pocket size.","Water condenses on the window on cold days because of the warm air inside."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thunder','n.雷；轰隆声；恐吓v.打雷；怒喝','/ˈθʌndə/','/ˈθʌndɚ/','noun',["Thunder is preceded by lightning.","Off in the distance, he heard the thunder of hoofbeats, signalling a stampede.","Shortly after I announced my pregnancy, he stole my thunder with his news of landing his dream job."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('microphone','n.扩音器，麦克风','/ˈmaɪ.kɹəˌfəʊn/','/ˈmaɪ.kɹəˌfəʊn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('duplicate','v.复制；使加倍n.副本；复制品adj.复制的；二重的','/ˈdjuː.plɪ.kət/','/ˈdjuː.plɪ.kət/','noun',["This is a duplicate, but a very good replica.","Can you duplicate this kind of key?","You don''t need to duplicate my efforts."]);
