INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neutral','adj.中立的，中性的；中立国的；非彩色的n.中立国；中立者；非彩色；齿轮的空档','/ˈnjuːtɹəl/','/ˈnuːtɹəl/','noun',["I am neutral regarding the issue of gay marriage."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worship','n.崇拜；礼拜；尊敬v.崇拜；尊敬；爱慕','/ˈwɜːʃɪp/','/ˈwɝʃɪp/','noun',["We worship at the church down the road."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stationery','n.文具；信纸','/ˈsteɪʃ(ə)n(ə)ɹi/','/ˈsteɪʃ(ə)n(ə)ɹi/','noun',["When school finished, he threw all of his stationery away, as he no longer had any need for pencils and exercise books."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liner','n.班轮，班机；衬垫；画线者','/ˈlaɪnə/','/ˈlaɪnə/','noun',["1973, A good liner has a pretty shrewd idea of the value of the painting he is treating and usually charges accordingly. — Kyril Bonfiglioli, Don''t Point That Thing at Me (Penguin 2001, p. 41)","I threw out the trash can liner.","Does it have the lyrics in the liner notes?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('linen','n.亚麻布，亚麻线；亚麻制品adj.亚麻的；亚麻布制的','/ˈlɪnɪn/','/ˈlɪnɪn/','noun',["She put the freshly cleaned linens into the linen closet."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('queer','adj.奇怪的；同性恋的；不舒服的；心智不平衡的v.搞糟；使陷于不利地位n.同性恋者；怪人；伪造的货币','/kwɪə/','/kwɪɹ/','noun',["the queer community"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('practise','v.练习，实践；实施，实行；从事','/ˈpɹæktɪs/','/ˈpɹæktɪs/','verb',["You should practise playing piano every day.","If you want to speak French well, you need to practise.","They gather to practise religion every Saturday."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('butcher','v.屠杀n.屠夫','/ˈbʊtʃ.ə(ɹ)/','/ˈbʊt͡ʃ.ɚ/','noun',["The band at that bar really butchered \"Hotel California\"."]);
