INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jargon','n.行话，术语；黄锆石','/ˈdʒɑː.ɡən/','/ˈdʒɑɹ.ɡən/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trousers','n.裤子，长裤','/ˈtɹaʊzəz/','/ˈtɹaʊzəz/','noun',["The trousers need to be shortened."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tilt','v.倾斜；翘起；以言词或文字抨击n.倾斜','/tɪlt/','/tɪlt/','noun',["Tilt the barrel to pour out its contents.","to tilt steel in order to render it more ductile"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salvation','n.拯救；救助','/sælˈveɪʃən/','/sælˈveɪʃən/','noun',["Collective salvation is not possible without personal salvation, but the latter is achievable."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nerve','n.神经；勇气；[植]叶脉v.鼓起勇气','/nɛɾv/','/nɜɪv/','noun',["The nerves can be seen through the skin.","Some plants have ornamental value because of their contrasting nerves.","He hasn''t the nerve to tell her he likes her. What a wimp!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('edible','adj.可食用的n.食品；食物','/ˈɛdɪbl/','/ˈɛdɪbl/','noun',["edible fruit","Although stale, the bread was edible."]);
