INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tile','n.瓷砖，瓦片v.铺以瓦；铺以瓷砖','/taɪl/','/taɪl/','noun',["Each tile within Google Maps consists of 256 × 256 pixels.","The handyman tiled the kitchen."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aunt','n.阿姨；姑妈；伯母；舅妈','/ɑ(ː)nt/','/eɪnt/','noun',[]);
