INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ditch','v.在…上掘沟；把…开入沟里；丢弃n.沟渠；壕沟','/dɪtʃ/','/dɪtʃ/','noun',["Digging ditches has long been considered one of the most demanding forms of manual labor.","Once the sun came out we ditched our rain-gear and started a campfire.","When the second engine failed, the pilot was forced to ditch; their last location was just south of the Azores."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('qualify','v.限制；使具有资格；证明…合格','/ˈkwɒl.ɪ.faɪ/','/ˈkwɑl.ɪ.faɪ/','noun',["to qualify seven balls you need at least fourteen catches"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bounce','n.跳；弹力；活力v.弹跳；使弹起','/baʊns/','/baʊns/','noun',["Them pro-ballers got bounce!","The tennis ball bounced off the wall before coming to rest in the ditch.","He bounces nervously on his chair."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cock','n.公鸡；龙头；雄鸟；头目v.使竖起；使耸立；使朝上','/kɒk/','/kɑk/','noun',["All right, cock?","In the darkness, the gun cocked loudly.","He cocked his hat jauntily."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kiss','v.吻；（风等）轻拂n.吻；轻拂','/kɪs/','/kɪs/','verb',["His ball kissed the black into the corner pocket."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scramble','v.攀登；使混杂，仓促凑成；扰乱n.抢夺，争夺；混乱，混乱的一团；爬行，攀登','/ˈskɹæmbl̩/','/ˈskɹæmbl̩/','noun',["a last-minute scramble to the finish line","I scrambled some eggs with spinach and cheese.","to scramble up wealth"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('friendship','n.友谊；友爱；友善','/ˈfɹɛndʃɪp/','/ˈfɹɛndʃɪp/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bang','n.刘海；重击；突然巨响adv.直接地；砰然地；突然巨响地v.重击；发巨响','/bæŋ(ɡ)/','/bæŋ(ɡ)/','noun',["When he struck it with a hammer, there was a loud bang.","An e-mail address with an ! is called a bang path.","Load the bang into the hole."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seemingly','adv.看来似乎；表面上看来','/ˈsiːmɪŋli/','/ˈsiːmɪŋli/','adverb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('textbook','n.教科书，课本','/ˈtɛkst.bʊk/','/ˈtɛkst.bʊk/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('orbit','n.轨道；眼眶；势力范围；生活常规v.盘旋；绕轨道运行','/ˈɔː(ɹ)bɪt/','/ˈɔː(ɹ)bɪt/','noun',["The Moon''s orbit around the Earth takes nearly one month to complete.","In the post WWII era, several eastern European countries came into the orbit of the Soviet Union.","The convenience store was a heavily travelled point in her daily orbit, as she purchased both cigarettes and lottery tickets there."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tame','adj.驯服的；平淡的；乏味的；顺从的v.驯养；使变得平淡；制服n.(Tame)人名；(捷)塔梅','/teɪm/','/teɪm/','verb',["He tamed the wild horse.","to tame a rebellion","They have a tame wildcat."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emperor','n.皇帝，君主','/ˈempɘɹɘ/','/ˈɛmpəɹɚ/','noun',["The Investiture Controversy was a conflict between the Emperor and the Pope."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('powder','n.粉；粉末；[化工][军]火药；尘土v.使成粉末；撒粉；搽粉于','/ˈpaʊ.də(ɹ)/','','noun',["to powder one''s hair","Expert skiers love skiing on powder snow."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fare','v.经营；进展；遭遇；过活n.票价；费用；旅客；食物','/fɛə(ɹ)/','/feɚ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blaze','v.在树皮上刻路标；公开宣布n.火焰，烈火；光辉；情感爆发','/bleɪz/','/bleɪz/','noun',["to seek shelter from the blaze of the sun","The palomino had a white blaze on its face."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flock','n.群；棉束（等于floc）v.用棉束填满','/flɒk/','/flɑk/','noun',["People flocked to the cinema to see the new film."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lad','n.少年，小伙子；家伙','/læd/','/læd/','noun',["I think he reckons he''s a bit of a lad.","Come here, lad, and help me shift these boxes."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ally','n.同盟国；伙伴；同盟者；助手v.使联盟；使联合','','','noun',["the two countries were allies in WWI","Gruiformes — cranes and allies"]);
