INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tale','n.故事；传说；叙述；流言蜚语','/ˈteɪl/','/ˈteɪl/','noun',["Don''t tell tales!","the Canterbury Tales"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lap','n.一圈；膝盖；下摆；山坳v.使重叠；拍打；包围','/læp/','/læp/','noun',["The boy was sitting on his mother''s lap."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offset','n.抵消，补偿；平版印刷；支管v.抵消；弥补；用平版印刷术印刷','/ɒfˈsɛt/','/ɒfˈsɛt/','noun',["Today''s victory was an offset to yesterday''s defeat.","offset lithographs","An array of bytes uses its index as the offset, of words a multiple thereof."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tall','adj.高的；长的；过分的；夸大的adv.夸大地n.(Tall)人名；(马里、阿拉伯)塔勒；(芬、罗、瑞典)塔尔；(英)托尔；(土)塔勒','/tɔːl/','/tɑl/','noun',["Being tall is an advantage in basketball."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coat','n.外套v.覆盖…的表面','/kəʊt/','/koʊt/','noun',["When the dog shed its coat, it left hair all over the furniture and the carpet.","The frying pan was coated with a layer of non-stick material, making it easier to wash."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dazzle','n.耀眼的光；灿烂v.使……目眩；使……眼花','/ˈdæzəl/','/ˈdæzəl/','noun',["Dazzled by the headlights of the lorry, the deer stopped in the middle of the street.","The delegates were dazzled by the originality of his arguments."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cable','n.缆绳；电缆；海底电报v.打电报','/keɪ.bl/','/keɪ.bl/','noun',["I tried to watch the movie last night but my cable was out."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kite','n.风筝v.使用空头支票；像风筝一样飞；轻快地移动','','','',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disrupt','v.破坏；使瓦解；使分裂；使中断；使陷于混乱adj.分裂的，中断的；分散的','/dɪsˈɹʌpt/','','verb',["Hecklers disrupted the man''s speech.","Work on the tunnel was disrupted by a strike.","The internet makes it easier for leaner businesses to disrupt the larger and more unwieldy ones."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retrieve','v.[计]检索；恢复；重新得到n.[计]检索；恢复，取回','/ɹiˈtɹiv/','/ɹiˈtɹiv/','noun',["to retrieve one''s character or independence; to retrieve a thrown ball","The cook doesn''t care what''s shot, only what''s actually retrieved.","Dog breeds called ''retrievers'' were selected for retrieving."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vitamin','n.[生化]维生素；[生化]维他命','/ˈvɑet.ə.mən/','/ˈvaɪ.tə.mɪn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fruitful','adj.富有成效的；多产的；果实结得多的','/ˈfɹuːtfəl/','/ˈfɹuːtfəl/','adjective',["The extra work in the office turned out to be fruitful after all—I got promoted"]);
