INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shuttle','n.航天飞机；穿梭；梭子；穿梭班机、公共汽车等v.使穿梭般来回移动；短程穿梭般运送','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cue','n.提示，暗示；线索v.给…暗示','','','',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('historic','adj.有历史意义的；历史上著名的','/(h)ɪˈstɒɹɪk/','/(h)ɪˈstɔːɹɪk/','noun',["A historic opportunity","The historic tenses include the imperfect, the pluperfect, and the future perfect.","July 4, 1776, is a historic date. A great deal of historical research has been done on the events leading up to that day."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hatred','n.憎恨；怨恨；敌意','/ˈheɪtɹɪd/','/ˈheɪtɹɪd/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stroke','n.（游泳或划船的）划；中风；（打、击等的）一下；冲程；（成功的）举动；尝试；轻抚v.（用笔等）画；轻抚；轻挪；敲击；划尾桨；划掉；（打字时）击打键盘','/stɹəʊk/','/stɹoʊk/','noun',["She gave the cat a stroke.","a stroke on the chin","the stroke of a bird''s wing in flying, or of an oar in rowing"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('torment','v.折磨，使痛苦；纠缠，作弄n.痛苦，苦恼；痛苦的根源','','','noun',["He was bitter from the torments of the divorce system.","The child tormented the flies by pulling their wings off."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('numerous','adj.许多的，很多的','/ˈnjuːməɹəs/','/ˈnjuːməɹəs/','adjective',["There are numerous definitions of the word ''man''."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burglar','n.夜贼，窃贼','/ˈbɜːɡlə(ɹ)/','/ˈbɜːɡlə(ɹ)/','noun',["The burglar made off with a large diamond from the museum."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('strawberry','n.草莓；草莓色','/ˈstɹɔːb(ə)ɹi/','/ˈstɹɔːb(ə)ɹi/','noun',["They went to pick strawberries today.","She has the best strawberry patch I''ve ever seen.","I''d like a large strawberry shake."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('antenna','n.[电讯]天线；[动]触角，[昆]触须','/ænˈtɛn.ə/','/ænˈtɛn.ə/','noun',[]);
