INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('creep','v.爬行；蔓延；慢慢地移动；起鸡皮疙瘩n.爬行；毛骨悚然的感觉；谄媚者','/kɹiːp/','/kɹiːp/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inflation','n.膨胀；通货膨胀；夸张；自命不凡','/ɪnˈfleɪʃən/','/ɪnˈfleɪʃən/','noun',["The inflation of the balloon took five hours."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shore','v.支撑，使稳住；用支柱撑住n.海滨；支柱','/ʃɔː/','/ʃɔɹ/','noun',["lake shore;  bay shore;  gulf shore;  island shore;  mainland shore;  river shore;  estuary shore;  pond shore;  sandy shore;  rocky shore","The passengers signed up for shore tours."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('empire','n.帝国；帝王统治，君权','/ˈɛmpaɪ.ə/','/ˈɛmˌpaɪɚ/','adjective',["the Russian empire","The Empire of Vietnam was a short-lived client state of Japan governing Vietnam between March 11 and August 23, 1945.","the McDonald''s fast food empire"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ministry','n.（政府的）部门','/ˈmɪnɪstɹi/','/ˈmɪnɪstɹi/','noun',["She works for the ministry of finance.","The premier offered his last ministry''s resignation to the monarch, and is asked to form a new one in accordance with the election results.","the present ministry of the Holy Spirit"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tape','n.胶带；磁带；带子；卷尺v.录音；用带子捆扎；用胶布把…封住','/teɪ̯p/','/teɪ̯p/','noun',["Hand me some tape. I need to fix a tear in this paper.","After the party there was tape all over the place.","Jones broke the tape in 47.77 seconds, a new world record."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('holy','adj.圣洁的，神圣的；至善的n.神圣的东西','/ˈhəʊli/','/ˈhoʊli/','noun',["I''m planning to visit the holy city of Jerusalem this Christmas.","My grandmother is a very holy woman.","Holy cow, I can’t believe he actually lost the race!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fiber','n.纤维；光纤（等于fibre）','/ˈfaɪ.bə/','/ˈfaɪ.bɚ/','noun',["The microscope showed a single blue fiber stuck to the sole of the shoe.","The cloth is made from strange, somewhat rough fiber.","Please use polyester fiber for this shirt."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quiz','n.考查；恶作剧；课堂测验v.挖苦；张望；对…进行测验','/kwɪz/','/kwɪz/','noun',["We came second in the pub quiz."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('melody','n.旋律；歌曲；美妙的音乐','/ˈmel.ə.di/','/ˈmɛl.ə.di/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fertile','adj.富饶的，肥沃的；能生育的','/ˈfɝːtaɪl/','/ˈfɝːtaɪl/','adjective',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('green','adj.绿色的；青春的n.绿色；青春v.使…变绿色','/ɡɹiːn/','/ɡɹin/','adjective',["The former flag of Libya is fully green.","Sally looks pretty green — is she going to be sick?","John''s kind of green, so take it easy on him this first week."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('famine','n.饥荒；饥饿，奇缺','/ˈfæmɪn/','/ˈfæmɪn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('narrative','n.叙述；故事；讲述adj.叙事的，叙述的；叙事体的','/ˈnæɹətɪv/','/ˈnæɹətɪv/','noun',["The plot is full of holes, but the narrative is extremely compelling.","the narrative thrust of a film"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nylon','n.尼龙，[纺]聚酰胺纤维；尼龙袜','/ˈnaɪlɒn/','/ˈnaɪlɒn/','noun',["I tore a hole in my nylons while walking home through the woods."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snap','v.突然折断，拉断；猛咬；啪地关上n.猛咬；劈啪声；突然折断adj.突然的','/snæp/','/snæp/','noun',["We took a few snaps of the old church before moving on.","a ginger snap","I can fix most vacuum cleaners in a snap."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dragon','n.龙；凶暴的人，凶恶的人；严厉而有警觉性的女人','/ˈdɹæɡən/','/ˈdɹæɡən/','noun',["She’s a bit of a dragon.","Napoleon already warned of the awakening of the Dragon."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('honest','adj.诚实的，实在的；可靠的；坦率的','/ˈɒnɪst/','/ˈɑnɪst/','verb',["We’re the most honest people you will ever come across.","an honest account of events","an honest mistake"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('postage','n.邮资，邮费','/ˈpəʊstɪdʒ/','/ˈpəʊstɪdʒ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flood','v.淹没；充满；溢出n.洪水；泛滥；一大批','/flʌd/','/flʌd/','noun',["a flood of complaints","The floor was flooded with beer.","The station''s switchboard was flooded with listeners making complaints."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aircraft','n.飞机，航空器','/ɛə.kɹɑːft/','/ɛəɹ.kɹæft/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liver','n.肝脏；生活者，居民','/ˈlɪvə/','/ˈlɪvɚ/','noun',["Steve Jobs is a famous liver transplant recipient.","I''d like some goose liver pate."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('necklace','n.项链','/ˈnɛkləs/','/ˈnɛkləs/','noun',["a necklace of coral islands"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rabbit','n.兔子，野兔v.让…见鬼去吧','/ˈɹæbət/','/ˈɹæbɪt/','noun',["The pioneers survived by eating the small game they could get: rabbits, squirrels and occasionally a raccoon.","The informant seemed skittish, as if he was about to rabbit."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('defeat','v.击败，战胜；挫败；使…失败n.失败的事实；击败的行为','/dɪˈfiːt/','/dɪˈfiːt/','verb',["Wellington defeated Napoleon at Waterloo."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('giggle','v.傻笑；咯咯地笑n.吃吃的笑','/ˈɡɪɡl/','/ˈɡɪɡl/','noun',["The women thought it would be quite a giggle to have a strippergram at the bride''s hen party.","The jokes had them giggling like little girls all evening."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remnant','n.剩余adj.剩余的','/ˈɹɛmnənt/','/ˈɹɛmnənt/','noun',[]);
