INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shove','v.挤；强使；撞；猛推n.推；挤','/ʃʌv/','/ʃʌv/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reassure','v.使…安心，使消除疑虑','/ɹiəˈʃʊə(ɹ)/','/ɹiəˈʃʊə(ɹ)/','verb',["The boy''s mother reassured him that there was no monster hiding under the bed."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seal','n.密封；印章；海豹；封条；标志v.密封；盖章','/siːl/','/siːl/','noun',["The seals in the harbor looked better than they smelled.","They''re organizing a protest against sealing."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seam','n.缝；接缝v.缝合；接合；使留下伤痕','/siːm/','/siːm/','noun',["Seams can be made or sealed in a variety of ways, including adhesive bonding, hot-air welding, solvent welding, using adhesive tapes, sealant, etc."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leaflet','n.小叶；传单','/ˈliːflɪt/','/ˈliːflɪt/','noun',["The new leaflets at the end of the branch were a lighter shade of green than the mature leaves.","A leaflet had been left under the car''s windshield wiper.","A sidewalk preacher gave an impassioned sermon while an assistant leafleted those who stayed to listen."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('notwithstanding','adv.尽管，仍然prep.尽管，虽然conj.虽然','/ˌnɒtwɪðˈstændɪŋ/','/ˌnɑtwɪθˈstændɪŋ/','noun',["He, notwithstanding, persisted in his inquiries."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wife','n.妻子，已婚妇女；夫人','/waɪf/','/waɪf/','noun',["A new wife for the gander is introduced into the pen."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blueprint','v.计划；制成蓝图n.蓝图，设计图；计划','/ˈbluːˌpɹɪnt/','/ˈbluːˌpɹɪnt/','noun',["The architect blueprinted the renovation plan once the client had signed off.","They blueprinted every aspect of the first phase of the operation."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shout','v.呼喊；喊叫；大声说n.呼喊；呼叫','/ʃaʊt/','/ʃaʊt/','noun',["Next up the new single from Beyoncé, but first a shout to Barry Bloggins and his wife Belinda...","They shouted his name to get his attention.","He′s shouting us all to the opening night of the play."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dynasty','n.王朝，朝代','/ˈdɪnəsti/','/ˈdaɪnəsti/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horsepower','n.马力（功率单位）','/ˈhɔːsˌpaʊə/','/ˈhɔɹsˌpaʊɚ/','noun',["political horsepower"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garbage','n.垃圾；废物','/ˈɡɑːbɪd͡ʒ/','/ɡɑ(ɹ)ˈbɑːʒ/','noun',["Garbage is collected on Tuesdays; rubbish on Fridays","The garbage truck collects all residential municipal waste.","He threw the newspaper into the garbage."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunshine','n.阳光；愉快；晴天；快活','/ˈsʌnʃaɪn/','/ˈsʌnʃaɪn/','noun',["We were warmed by the bright sunshine.","We moved out of the shade and into the sunshine.","I enjoyed the sunshine of her smile."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fourteen','num.十四；十四个；第十四n.十四的记号；十四岁；十四点钟；十五世纪','/ˈfɔː.tiːn/','','numeral',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bureau','n.局，处；衣柜；办公桌','/ˈbjʊɹ.oʊ/','/ˈbjʊɹ.oʊ/','noun',["a news bureau; a travel bureau; a service bureau; an employment bureau; the Citizens Advice Bureau"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('static','adj.静态的；静电的；静力的n.静电；静电干扰','/ˈstæt.ɪk/','/ˈstæt.ɪk/','noun',[]);
