INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tangle','n.纠纷；混乱状态v.使纠缠；处于混乱状态','/ˈtæŋ.ɡəl/','/ˈtæŋ.ɡəl/','noun',["I tried to sort through this tangle and got nowhere.","Her hair was tangled from a day in the wind.","Don''t tangle with someone three times your size."]);
