INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blade','n.叶片；刀片，刀锋；剑','/bleɪd/','/bleɪd/','noun',["Want to go blading with me later in the park?","The gang member got bladed in a fight."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magnetic','adj.地磁的；有磁性的；有吸引力的','/mæɡˈnɛtɪk/','/mæɡˈnɛtɪk/','adjective',["a magnetic recorder","magnetic north","He has a magnetic personality."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sniff','v.嗅；嗤之以鼻n.吸，闻；嗤之以鼻；气味；以鼻吸气；吸气声','/snɪf/','/snɪf/','noun',["She gave the flowers a quick sniff to check they were real.","I sniffed the meat to see whether it had gone off.","\"He''s never coming back, is he?\" she sniffed while looking at a picture of him."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sweat','v.使出汗；流出；使干苦活；剥削；藉出汗减轻；焦急地期待n.汗；水珠；焦急；苦差使','/swɛt/','/swɛt/','noun',["Just thinking about the interview tomorrow puts me into a nervous sweat.","the sweat of hay or grain in a mow or stack"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ugly','adj.丑陋的；邪恶的；令人厌恶的','/ˈʌɡli/','/ˈʌɡli/','noun',["He played an ugly trick on us.","an ugly temper; to feel ugly","With all this competition, expect things to get ugly."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('graphic','adj.形象的；图表的；绘画似的','/ˈɡɹæfɪk/','/ˈɡɹæfɪk/','noun',["I''ve just played this new computer game: the graphics are amazing.","graphic granite"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('territory','n.领土，领域；范围；地域；版图','/ˈtɛɹɪt(ə)ɹi/','/ˈtɛɹɪt(ə)ɹi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drunk','v.喝酒（drink的过去分词）adj.喝醉了的','/dɹʌŋk/','/dɹʌŋk/','verb',["He drank the water I gave him.","Jack drank the whole bottle by himself.","Everyone who is drinking is drinking, but not everyone who is drinking is drinking."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vicinity','n.邻近，附近；近处','/vəˈsɪnəti/','/vəˈsɪnəti/','noun',["There was a crackling sound in the vicinity of my right ear.","There is a hurricane in the vicinity of the Bahamas.","I weigh in the vicinity of 80kg."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offspring','n.后代，子孙；产物','/ˈɒfspɹɪŋ/','/ˈɒfspɹɪŋ/','noun',["Artists often treasure their works as their immortal offspring."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('landlord','n.房东，老板；地主','/ˈlænd.lɔːd/','/ˈlænd.lɔːd/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stagger','v.蹒跚；使交错；使犹豫n.蹒跚；交错安排adj.交错的；错开的','/ˈstæɡə/','/ˈstæɡə/','noun',["the stagger of a drunken man","apoplectic or sleepy staggers"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nineteen','num.十九','/naɪnˈtiːn/','/ˈnaɪnˌtin/','numeral',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('seed','n.种子；根据；精液；萌芽；子孙；原由v.播种；结实；成熟；去…籽','/siːd/','/siːd/','noun',["If you plant a seed in the spring, you may have a pleasant surprise in the autumn.","The entire field was covered with geese eating the freshly sown seed.","A man must use his seed to start and raise a family."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cosmic','adj.宇宙的（等于cosmical）','/ˈkɒz.mɪk/','/ˈkɒz.mɪk/','adjective',["cosmic speed"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plentiful','adj.丰富的；许多的；丰饶的；众多的','/ˈplɛntɪfl̩/','/ˈplɛntɪfl̩/','adjective',["She accumulated a plentiful collection of books.","Some years, the tree is a plentiful source of apples."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comb','n.梳子；蜂巢；鸡冠v.梳头发；梳毛','/kəʊm/','/koʊm/','noun',["I need to comb my hair before we leave the house","Police combed the field for evidence after the assault"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('singular','adj.单数的；单一的；非凡的；异常的n.单数','/ˈsɪŋɡjʊlə/','/ˈsɪŋɡjəlɚ/','noun',["A singular experiment cannot be regarded as scientific proof of the existence of a phenomenon.","She has a singular personality.","a man of singular gravity or attainments"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('handful','n.少数；一把；棘手事','/ˈhæn(d)fəl/','/ˈhæn(d)fəl/','noun',["Those twins are a real handful to look after."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oxide','n.[化学]氧化物','/ˈɒksaɪd/','/ˈɒksaɪd/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kindergarten','n.幼儿园；幼稚园','/ˈkɪndəɹˌɡɑːɹd(ə)n/','/ˈkɪndəɹˌɡɑːɹd(ə)n/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adore','v.崇拜；爱慕；喜爱；极喜欢n.(Adore)人名；(法)阿多尔','/əˈdɔː/','/əˈdɔɹ/','verb',["It is obvious to everyone that Gerry adores Heather."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turbine','n.[动力]涡轮；[动力]涡轮机','/ˈtɜ(ɹ)baɪn/','/ˈtɜ(ɹ)baɪn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cop','v.抓住n.巡警，警官','/kɒp/','/kɒp/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cow','n.奶牛，母牛；母兽v.威胁，恐吓','/kaʊ/','/kaʊ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('meantime','n.其时，其间adv.同时；其间','/ˈmiːntaɪm/','/ˈmiːntaɪm/','noun',["I''ll get started tomorrow but, in the meantime, let''s see if we can get a few more opinions."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frontier','n.前沿；边界；国境adj.边界的；开拓的','/fɹʌnˈtɪə/','/fɹʌnˈtɪɹ/','noun',["the frontier of civilization"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cylinder','n.圆筒；汽缸；[数]柱面；圆柱状物','/ˈsɪlɪndə(ɹ)/','/ˈsɪləndɚ/','noun',["When the two-dimensional curve is a circle, the cylinder is called a circular cylinder. When the axis is perpendicular to the plane of the curve, the cylinder is called a right cylinder. In non-mathematical usage, both right and circular are usually implied."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sweep','v.扫除；猛拉；掸去n.打扫，扫除；范围；全胜','/swiːp/','/swiːp/','noun',["Give the front steps a quick sweep to get rid of those fallen leaves.","Bradman attempted a sweep, but in fact top edged the ball to the wicket keeper","Jim will win fifty dollars in the office sweep if Japan wins the World Cup."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('december','n.十二月','','','',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cosy','adj.舒适的；惬意的n.保温罩','/ˈkəʊzi/','/ˈkoʊzi/','noun',["He spent all day cosying up to the new boss, hoping for a plum assignment."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hound','v.追猎；烦扰；激励n.猎犬；卑劣的人','/haʊnd/','/haʊnd/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurricane','n.飓风，暴风','/ˈhʌɹɪkən/','/ˈhɝɪˌkeɪn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corn','n.（美）玉米；（英）谷物；[皮肤]鸡眼v.腌；使成颗粒','/kɔɹn/','/kɔɹn/','noun',["He paid her the nominal fee of two corns of barley.","to corn gunpowder","Corn the horses."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('traitor','n.叛徒；卖国贼；背信弃义的人','/ˈtɹeɪtə(ɹ)/','/ˈtɹeɪtɚ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('federation','n.联合；联邦；联盟；联邦政府','/ˌfɛdəˈɹeɪʃn̩/','/ˌfɛdəˈɹeɪʃn̩/','noun',["It is 106 years since federation.","We live in a federation house."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pirate','n.海盗；盗版；侵犯专利权者v.掠夺；翻印；剽窃','/ˈpaɪ̯(ə)ɹət/','/ˈpaɪ̯(ə)ɹət/','noun',["You should be cautious due to the Somali pirates.","They pirated the tanker and sailed to a port where they could sell the ship and cargo.","Not willing to pay full price for the computer game, Heidi pirated a copy."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('profile','n.侧面；轮廓；外形；剖面；简况v.描…的轮廓；扼要描述','/ˈpɹəʊfaɪl/','/ˈpɹəʊfaɪl/','noun',["His fingers traced the profile of the handle.","The brooch showed the profile of a Victorian woman.","Law enforcement assembled a profile of the suspect."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thrust','n.[力]推力；刺v.插；插入；推挤','/θɹʌst/','/θɹʌst/','noun',["Pierre was a master swordsman, and could parry the thrusts of lesser men with barely a thought.","The cutpurse tried to knock her satchel from her hands, but she avoided his thrust and yelled, \"Thief!\"","Spacecraft are engineering marvels, designed to resist the thrust of liftoff, as well as the reverse pressure of the void."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('camera','n.照相机；摄影机','/ˈkæməɹə/','/ˈkæməɹə/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fluent','adj.流畅的，流利的；液态的；畅流的','/ˈfluːənt/','/ˈfluənt/','noun',["fluent handwriting","She''s fluent in French."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cabinet','n.内阁；橱柜；展览艺术品的小陈列室adj.内阁的；私下的，秘密的','/ˈkæ.bɪ.nɪt/','/ˈkæ.bɪ.nɪt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harassment','n.骚扰；烦恼','/həˈɹæsmənt/','/həˈɹæsmənt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sacred','adj.神的；神圣的；宗教的；庄严的','/ˈseɪkɹɪd/','/ˈseɪkɹɪd/','adjective',["a sacred day"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('threshold','n.入口；门槛；开始；极限；临界值','/ˈθɹeʃ(h)əʊld/','/ˈθɹɛʃ(h)oʊld/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('owing','adj.未付的；欠着的v.欠；把…归功于（owe的ing形式）','/ˈəʊ.ɪŋ/','/ˈoʊ.ɪŋ/','verb',["These seven subscriptions remain owing."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unit','n.单位，单元；装置；[军]部队；部件','/ˈjuː.nɪt/','/ˈjuː.nɪt/','noun',["The centimetre is a unit of length.","He was a member of a special police unit.","The fifth tank brigade moved in with 20 units. (i.e., 20 tanks)"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nationality','n.国籍，国家；民族；部落','/-ˈnæl.ti/','/-ˈnæl.ti/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('usage','n.使用；用法；惯例','/ˈjuːsɪd͡ʒ/','/ˈjuːsɪd͡ʒ/','noun',[]);
