INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cord','n.绳索；束缚v.用绳子捆绑','/kɔːd/','/kɔɹd/','noun',["He looped some cord around his fingers.","spermatic cord; spinal cord; umbilical cord; vocal cords"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('downward','adj.向下的，下降的adv.向下','/ˈdaʊnwəd/','/ˈdaʊnwəd/','adjective',["He spoke with a downward glance.","His position in society moved ever downward."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tidy','adj.整齐的；相当大的v.整理；收拾；弄整齐n.椅子的背罩','/ˈtaɪdi/','/ˈtaɪdi/','noun',["a desk tidy","Keep Britain tidy.","The scheme made a tidy profit."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('goat','n.山羊；替罪羊（美俚）；色鬼（美俚）','/ɡɐ̟ʉt/','/ɡoʊt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('greedy','adj.贪婪的；贪吃的；渴望的','/ˈɡɹiːdi/','/ˈɡɹiːdi/','adjective',["This regular expression performs a greedy match."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slender','adj.细长的；苗条的；微薄的','/ˈslɛndə/','/ˈslɛndɚ/','adjective',["A rod is a long slender pole used for angling.","Being a person of slender means, he was unable to afford any luxuries."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('migrate','v.移动；随季节而移居；移往','/maɪ.ˈɡɹeɪt/','/maɪ.ˈɡɹeɪt/','verb',["Twice a year the Minnesotans migrate from their state to the Gulf of Mexico.","Many groups had migrated to western Europe from the plains of eastern Europe.","To escape persecution, they migrated to a neutral country."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cushion','n.垫子；起缓解作用之物；（猪等的）臀肉；银行储蓄v.给…安上垫子；把…安置在垫子上；缓和…的冲击','/ˈkʊʃən/','/ˈkʊʃən/','noun',["to cushion a sofa","to cushion a blow"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scrap','n.碎片；残余物；打架；少量v.废弃；使解体；拆毁adj.废弃的；零碎的','/skɹæp/','/skɹæp/','noun',["I found a scrap of cloth to patch the hole.","Give the scraps to the dogs and watch them fight.","pork scraps"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('operational','adj.操作的；运作的','','','adjective',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wretched','adj.可怜的；卑鄙的；令人苦恼或难受的','/ˈɹɛtʃɪd/','/ˈɹɛtʃɪd/','adjective',["I felt wretched after my wife died.","The street was full of wretched beggars dressed in rags.","Will you please stop playing that wretched trombone!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('funeral','n.葬礼；麻烦事adj.丧葬的，出殡的','/ˈfjuːnəɹəl/','/ˈfjunəɹəl/','noun',["Many mourners turned up at the local artist''s funeral to pay homage."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jolly','adj.愉快的；欢乐的；宜人的adv.很；非常v.（口）用好话劝某人做…；（口）用好话使高兴n.(Jolly)人名；(法)若利；(英、印)乔利；(德)约利','/ˈdʒɒli/','/ˈdʒɒli/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glove','n.手套vt.给…戴手套','/ɡlʌv/','/ɡlʌv/','noun',["I wore gloves to keep my hands warm.","Frederico had a great glove, but he couldn''t hit a curveball, so he never broke into the pros.","to throw down the glove, i.e. to offer a challenge; to take up the glove, to accept it"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('utilize','v.利用','/ˈjuːtɨlaɪz/','/ˈjuːtɨlaɪz/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bake','v.烤，烘焙n.烤；烘烤食品','/beɪk/','/beɪk/','noun',["I baked a delicious cherry pie.","The cake baked at 350°F.","The clay baked in the sun."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surroundings','n.环境；周围的事物','/səˈɹaʊndɪŋz/','/səˈɹaʊndɪŋz/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tide','n.趋势，潮流；潮汐v.随潮漂流','/taɪd/','/taɪd/','noun',["The doctor''s no good this tide.","Eventide, noontide, morrowtide, nighttide, moon-tide, harvest-tide, wintertide, summertide, springtide, autumn-tide etc.,.","The ocean tided most impressively."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lunar','adj.月亮的，月球的；阴历的；银的；微亮的n.(Lunar)人名；(西)卢纳尔','/ˈl(j)uːnə/','/ˈlunɚ/','noun',["lunar observations  a lunar eclipse"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roundabout','adj.迂回的，绕道的；圆滚滚的n.迂回路线；环状交叉路口','/ˈɹaʊndəˌbaʊt/','/ˈɹaʊndəˌbaʊt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aloud','adv.大声地；出声地','/əˈlaʊd/','/əˈlaʊd/','adjective',["Try speaking aloud rather than whispering.","speaking aloud rather than thinking thoughts privately"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('badminton','n.羽毛球','/ˈbæd.mɪn.tən/','/ˈbæd.mɪn.tən/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bald','adj.秃顶的；光秃的；单调的；无装饰的v.变秃n.(Bald)人名；(英)鲍尔德；(德、法、波)巴尔德','/bɔːld/','','noun',["The bald cypress is a tree that loses its leaves in winter."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('framework','n.框架，骨架；结构，构架','/ˈfɹeɪm.wɜːk/','/ˈfɹeɪm.wɜːk/','noun',["These ‘three principles of connexion’ compose the framework of principles in Hume''s account of the association of ideas."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tick','v.标记号于；滴答地记录n.滴答声；扁虱；记号；赊欠','/tɪk/','/tɪk/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leg','n.腿；支柱','/lɛɡ/','/lɛɡ/','noun',["{{ux|en|Insects have six legs.}","Dan won''t be able to come to the party, since he broke his leg last week and is now on crutches.","The left leg of these jeans has a tear."]);
