INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('radar','n.[雷达]雷达，无线电探测器','/ˈɹeɪdɑː(ɹ)/','/ˈɹeɪdɚ/','noun',["His sensitive radar for hidden alliances keeps him out of trouble."]);
