INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explode','v.爆炸，爆发；激增','/ɪkˈspləʊd/','/ɪkˈsploʊd/','verb',["The assassin exploded the car by means of a car bomb.","They sought to explode the myth.","Explode the assembly drawing so that all the fasteners are visible."]);
