INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swell','v.膨胀；肿胀；隆起n.肿胀；隆起adj.漂亮的；一流的','/swɛl/','/swɛl/','verb',["Rains and dissolving snow swell the rivers in spring.","The organ music swelled.","to be swelled with pride or haughtiness"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nurse','v.看护，护理；照顾；培养；给…喂奶n.护士；奶妈，保姆','/nɜːs/','/nɝs/','noun',["They hired a nurse to care for their young boy.","The nurse made her rounds through the hospital ward.","Eton College has been called \"the chief nurse of England''s statesmen\"."]);
