INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plunge','n.投入；跳进v.突然地下降；投入；陷入；跳进','/plʌndʒ/','/plʌndʒ/','noun',["A plunge into the sea","to plunge the body into water","to plunge a dagger into the breast;   to plunge a nation into war"]);
