INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blast','n.爆炸；冲击波；一阵v.猛攻','/blɑːst/','/blɑːst/','noun',["many tons of iron were melted at a blast","We had a blast at the party last night.","an e-mail blast; a fax blast"]);
