INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coin','v.铸造（货币）；杜撰，创造n.硬币，钱币','/kɔɪn/','/kɔɪn/','noun',["She spent some serious coin on that car!","What''s the best coin to buy right now?","to coin a medal"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aerial','adj.空中的，航空的；空气的；空想的n.[电讯]天线','/ˈɛː.ɹi.əl/','/ˈɛː.ɹi.əl/','noun',["The seabirds put on an astonishing aerial display.","The aerial photographs clearly showed the damage caused by the storm."]);
