INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('militant','adj.好战的n.富有战斗性的人；好斗者；激进分子','/ˈmɪlɪtənt/','/ˈmɪlɪtənt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thread','n.线；螺纹；思路；衣服；线状物；玻璃纤维；路线v.穿过；穿线于；使交织','[θɾ̪̊ɛd]','[θɾ̪̊ɛd]','noun',["All of these essays have a common thread.","thread a needle","I think I can thread my way through here, but it’s going to be tight."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spider','n.蜘蛛；设圈套者；三脚架','[ˈspʌɪ̯ɾə(ɹ)]','/ˈspaɪ̯dɚ/','noun',["2002, Katharine Gasparini, Cranberry and vanilla ice cream spider, recipe in Cool Food, page 339.","The online dictionary is regularly spidered by search engines."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('torch','n.火把，火炬；手电筒；启发之物v.像火炬一样燃烧','/tɔːtʃ/','/tɔɹtʃ/','noun',["The mob of angry villagers carried torches and pitchforks to the vampire''s castle.","Ernst slipped and dropped his torch on the flagstones, shattering the bulb and plunging us into darkness.","Some hoodlums had torched a derelict automobile, which emitted a ghastly pall of thick, black smoke that filled the street."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('choke','v.呛；使窒息；阻塞；抑制；扑灭n.窒息；噎；[动力]阻气门','/t͡ʃəʊk/','/t͡ʃəʊk/','noun',["Ever since he choked on a bone, he has refused to eat fish.","The collar of this shirt is too tight; it’s choking me.","to choke a cave passage with boulders and mud"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('refreshment','n.点心；起提神作用的东西；精力恢复','/ɹɪˈfɹeʃ.mənt/','/ɹɪˈfɹeʃ.mənt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overwhelm','v.淹没；压倒；受打击；覆盖；压垮','/ˌovɚˈʍɛlm/','/ˌovɚˈʍɛlm/','noun',["The dinghy was overwhelmed by the great wave.","In December 1939 the Soviet Union attacked Finland with overwhelming force.","He was overwhelmed with guilt."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ear','n.耳朵；穗；听觉；倾听vi.（美俚）听见；抽穗','/ɪə̯/','/iɹ/','noun',["a good ear for music","the ears of a tub, skillet, or dish;   The ears of a boat are outside kneepieces near the bow."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ratio','n.比率，比例','/ˈɹeɪ.ʃi.əʊ/','/ˈɹeɪ.ʃiˌoʊ/','noun',["The schoolchildren ganged up to ratio the school catering over its shamefully undemocratic inclusion of vegetables in meals."]);
