INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mat','n.垫；垫子；衬边v.缠结；铺席于……上adj.无光泽的','/mæt/','/mæt/','noun',["Wipe your feet on the mat before coming in.","They put mats on the table during mealtimes.","The high jumper cleared the bar and landed safely on the mat."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('unanimous','adj.全体一致的；意见一致的；无异议的','/juːˈnanɪməs/','/juːˈnanɪməs/','adjective',["The debate went on for hours, but in the end the decision was unanimous.","We were unanimous: the President had to go."]);
