INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hostess','n.女主人，女老板；女服务员；舞女；女房东','/ˈhəʊstəs/','/ˈhoʊstəs/','noun',["The host and hostess greeted their guests at the door."]);
