INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cement','v.巩固，加强；用水泥涂；接合n.水泥；接合剂','/səˈmɛnt/','/səˈmɛnt/','noun',["the cement of our love","to cement a cellar floor"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slum','v.（为猎奇或救济等）去贫民窟n.贫民窟；陋巷；脏乱的地方','/slʌm/','/slʌm/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outlook','n.展望；观点；景色vt.比……好看；用目光压倒vi.朝外看','/ˈaʊtˌlʊk/','/ˈaʊtˌlʊk/','noun',["Perched on the edge of the cliff was a hidden outlook.","He has a positive outlook on life.","The outlook for temperature rises is worrying."]);
