INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('umbrella','n.雨伞；保护伞；庇护；伞形结构','/ʌmˈbɹɛlə/','/ʌmˈbɹɛlə/','noun',["Quick, grab that umbrella before you get rained on!","The fighters provide a defensive air umbrella over the battle group.","The test facility was established under the umbrella of the company''s quality program."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burst','v.爆发，突发；爆炸n.爆发，突发；爆炸','/bɜːst/','/bɝst/','noun',["The bursts of the bombs could be heard miles away.","I blew the balloon up too much, and it burst.","I burst the balloon when I blew it up too much."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breakdown','n.故障；崩溃；分解；分类；衰弱；跺脚曳步舞','/ˈbɹeɪkdaʊn/','/ˈbɹeɪkdaʊn/','noun',["We saw a breakdown by the side of the road.","After so much stress, he suffered a breakdown and simply gave up.","Looking at the breakdown of the budget, I see a few items we could cut."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zigzag','adj.曲折的；锯齿形的；之字形的v.使成之字形；使曲折行进n.之字形；Z字形adv.曲折地；之字形地；Z字形地','','','noun',[]);
