INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dread','n.恐惧；可怕的人（或物）v.惧怕；担心adj.可怕的','/dɹɛd/','/dɹɛd/','noun',["my visit to the doctor is filling me with dread","I''m dreading getting the results of the test, as it could decide my whole life."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('youngster','n.年轻人；少年','/ˈjʌŋstə/','/ˈjʌŋstə/','noun',[]);
