INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swim','v.游泳；漂浮；浸；眩晕n.游泳；漂浮；眩晕adj.游泳时穿戴的','/swɪm/','/swɪm/','noun',["I''m going for a swim.","a bare few bits of meat swimming in watery sauce","For exercise, we like to swim laps around the pool."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lofty','adj.高的；崇高的；高级的；高傲的n.(Lofty)人名；(英)洛夫蒂','/ˈlɑfti/','/ˈlɔːfti/','adjective',["a lofty goal"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trip','v.绊倒；远足；犯错误；轻快地走n.旅行；绊倒；差错','/tɹɪp/','/tɹɪp/','noun',["We made a trip to the beach.","He was injured due to a trip down the stairs.","He had a strange trip after taking LSD."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trim','v.修剪；整理；装点n.修剪；整齐；情形adj.整齐的','/tɹɪm/','/tɹɪm/','noun',["Paint the house white with blue trim.","I went to the hairdresser for a trim but came back nearly bald.","The car comes in three different trims."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sketch','n.素描；略图；梗概v.画素描或速写','/skɛtʃ/','/skɛtʃ/','noun',["to keep sketch","I usually sketch with a pen rather than a pencil.","He sketched the accident, sticking to the facts as they had happened."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glory','n.光荣，荣誉；赞颂v.自豪，骄傲；狂喜','/ˈɡlo(ː)ɹi/','/ˈɡlo(ː)ɹi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ounce','n.盎司；少量；雪豹','/aʊns/','/aʊns/','noun',["He didn''t feel even an ounce of regret for his actions."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elbow','n.肘部；弯头；扶手v.推挤；用手肘推开','/ˈɛl.bəʊ/','/ˈɛl.boʊ/','noun',["the sides of windows, where the jamb makes an elbow with the window back","He elbowed his way through the crowd."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dye','n.染料；染色v.染；把…染上颜色','/daɪ/','/daɪ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('socialism','n.社会主义','/ˈsəʊʃəlɪzəm/','/ˈsəʊʃəlɪzəm/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('repay','v.偿还；报答；报复','/ɹiˈpeɪ/','/ɹiˈpeɪ/','verb',["I finally repaid my student loans, just before sending my kids to college."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laser','n.激光','/ˈleɪz.ə(ɹ)/','/ˈleɪz.ə(ɹ)/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pleasant','adj.令人愉快的，舒适的；讨人喜欢的，和蔼可亲的n.(Pleasant)人名；(英)普莱曾特','/ˈplɛzənt/','/ˈplɛzənt/','noun',["It wasn''t so hot outside, but pleasant enough to have lunch in the garden."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('whip','v.抽打；煽动；搅打（蛋，奶油）；彻底击败n.鞭子；抽打；车夫；[机]搅拌器','/wɪp/','/wɪp/','noun',["I had to use the whip to get the sheep''s attention.","I was going to vote against the bill, but the party whip came to see me and made it clear I needed to vote for it.","Did you want to add some whip to your coffee, ma''am?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enroll','v.登记；使加入；把记入名册；使入伍','/ɪnˈɹəʊl/','/ɪnˈɹəʊl/','verb',["They were eager to enroll new recruits.","Have you enrolled in classes yet for this term?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flee','v.逃走；消失，消散','/fliː/','/fliː/','verb',["The prisoner tried to flee, but was caught by the guards.","Many people fled the country as war loomed.","Ethereal products flee once freely exposed to air."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('porcelain','n.瓷；瓷器adj.瓷制的；精美的','/ˈpoːslɘn/','/ˈpoːslɘn/','noun',["He set the table with china, cloth napkins, and crystal stemware.","John and I have been friends ever since we were roommates at college.   Trust is important between friends.   I used to find it hard to make friends when I was shy.","The Automobile Association is every motorist''s friend.   The police is every law-abiding citizen''s friend."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('semester','n.学期；半年','/sɪˈmɛstə/','/sɪˈmɛstə/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breeze','n.微风；轻而易举的事；煤屑；焦炭渣；小风波v.吹微风；逃走','/bɹiːz/','/bɹiːz/','noun',["The breeze rustled the papers on her desk.","After studying Latin, Spanish was a breeze.","The discovery produced a breeze."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hardware','n.计算机硬件；五金器具','/ˈhɑːdˌwɛə/','/ˈhɑɹdˌwɛɹ/','noun',["military hardware"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('numb','v.使麻木；使发愣；使失去感觉adj.麻木的；发愣的','/nʌm/','/nʌm/','verb',["The dentist gave me novocaine to numb my tooth before drilling, thank goodness.","He turned to alcohol to numb his pain.","fingers numb with cold"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wound','n.创伤，伤口v.使受伤','/wuːnd/','/wund/','noun',["It took a long time to get over the wound of that insult.","The police officer wounded the suspect during the fight that ensued.","The actor''s pride was wounded when the leading role went to his rival."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chicken','n.鸡肉；小鸡；胆小鬼，懦夫adj.鸡肉的；胆怯的；幼小的','/ˈt͡ʃɪkɪn/','/ˈt͡ʃɪkɪn/','noun',["Why do you refuse to fight? Huh, I guess you''re just too chicken."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('streamline','v.把…做成流线型；使现代化；组织；使合理化；使简单化n.流线；流线型adj.流线型的','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('henceforth','adv.今后；自此以后','/hɛnsˈfɔɹθ/','/hɛnsˈfɔɹθ/','adverb',["I will try to do a better job, henceforth, now that I know the proper technique!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lion','n.狮子；名人；勇猛的人；社交场合的名流','/ˈlaɪən/','/ˈlaɪən/','noun',["Tigers and lions share a common ancestor from a few million years ago."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('champagne','n.香槟酒；香槟酒色','/ʃæmˈpeɪn/','/ʃæmˈpeɪn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insert','v.插入；嵌入n.插入物；管芯；镶块；[机械]刀片','/ɪnˈsɜːt/','/ɪnˈsɜːt/','noun',["This software can print compact disc inserts if you have the right size of paper.","a threaded insert","In order to withdraw money from a cash machine, you have to insert your debit card."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terror','n.恐怖；恐怖行动；恐怖时期；可怕的人','/ˈtɛɹə/','/ˈtɛɚ/','noun',["a terror attack; the War on Terror"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('despatch','v.派遣；发送；匆匆吃下n.派遣；发送（等于dispatch）','/dəˈspætʃ/','/dəˈspætʃ/','noun',["We must act with dispatch in this matter."]);
