INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fever','n.发烧，发热；狂热vt.使发烧；使狂热；使患热病vi.发烧；狂热；患热病','/ˈfiːvə/','/ˈfivɚ/','noun',["\"I have a fever. I think I''ve the flu.\"","a fevered lip"]);
