INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lash','v.鞭打；冲击；摆动；扎捆；煽动；讽刺n.鞭打；睫毛；鞭子；责骂；讽刺','/læʃ/','/læʃ/','noun',["The culprit received thirty-nine lashes."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pavement','n.人行道','/ˈpeɪvmənt/','/ˈpeɪvmənt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('germ','n.[植]胚芽，萌芽；细菌vi.萌芽','/d͡ʒɜːm/','/d͡ʒɝm/','noun',["the germ of civil liberty"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flat','adj.平的；单调的；不景气的；干脆的；平坦的；扁平的；浅的adv.（尤指贴着另一表面）平直地；断然地；水平地；直接地，完全地n.平地；公寓；平面vt.使变平；[音乐]使（音调）下降，尤指降半音vi.逐渐变平；[音乐]以降调唱（或奏）','/flæt/','/flæt/','noun',["She liked to walk in her flats more than in her high heels.","a flat of strawberries","The land around here is flat."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spill','v.使溢出，使流出；使摔下n.溢出，溅出；溢出量；摔下；小塞子','/spɪl/','/spɪl/','noun',["The bruise is from a bad spill he had last week.","I spilled some sticky juice on the kitchen floor.","Some sticky juice spilled onto the kitchen floor."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flap','n.拍打，拍打声；神经紧张；[航]襟翼v.拍动；神经紧张；鼓翼而飞；（帽边等）垂下','','','',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('balloon','v.激增；膨胀如气球n.气球adj.像气球般鼓起的','/bəˈluːn/','/bəˈlun/','noun',["the balloon of St. Paul''s Cathedral in London","His stomach ballooned from eating such a large meal."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flag','v.标记；衰退；枯萎n.标志；旗子','/flæɡ/','/flæɡ/','noun',["Please flag down a taxi for me.","to flag an order to troops or vessels at a distance","I''ve flagged up the need for further investigation into this."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liquid','adj.液体的；清澈的；明亮的；易变的n.液体，流体；流音','/ˈlɪkwɪd/','/ˈlɪkwɪd/','noun',["A liquid can freeze to become a solid or evaporate into a gas.","liquid nitrogen","a liquid melody"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tub','n.浴盆；桶vt.把…装入桶；为…洗盆浴vi.洗盆浴；（衣服等）被放在桶里洗','/tʌb/','/tʌb/','noun',["He bought a tub of lard to roast the potatoes in.","She added a tub of margarine to the stew.","a tub of gin"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eastern','adj.东方的；朝东的；东洋的n.东方人；（美国）东部地区的人','/ˈiːstən/','','adjective',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('virtue','n.美德；优点；贞操；功效','/-tjuː/','/ˈvɝtʃu/','noun',["Without virtue, there is no freedom."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tug','n.拖船；拖曳；苦干v.用力拉；竞争；努力做','/tʌɡ/','/tʌɡ/','noun',["He had a quick tug to calm himself down before his date.","The police officers tugged the drunkard out of the pub.","He lost his patience trying to undo his shoe-lace, but tugging it made the knot even tighter."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('highway','n.公路，大路；捷径','/ˈhaɪweɪ/','/ˈhaɪweɪ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('copper','n.铜；铜币；警察adj.铜制的v.镀铜','/ˈkɔp.ə/','/ˈkɑ.pɚ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elephant','n.象；大号图画纸','/ˈɛləfənt/','/ˈɛləfənt/','noun',["Let''s play hide and seek. I''ll count. One elephant, two elephant, three elephant..."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beauty','n.美；美丽；美人；美好的东西','/ˈbuːti/','/ˈbjuɾi/','noun',["1988, \"… beauty and recollection, like danger, glamour, greed, hunger- everything but disappointment and desire- were concepts belonging to other people.” -Second Son, Robert Ferro","Brigitte Bardot was a renowned beauty.","What a goal! That was a real beauty!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eccentric','adj.古怪的，反常的n.古怪的人','/ɪkˈsɛntɹɪk/','/ɛkˈsɛntɹɪk/','noun',["As of 2008, Margaret had the most eccentric orbit of any moon in the solar system, though Nereid''s mean eccentricity is greater."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mineral','n.矿物；（英）矿泉水；无机物；苏打水（常用复数表示）adj.矿物的；矿质的','/ˈmɪ.nəɹ.əl/','/ˈmɪ.nəɹ.əl/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illness','n.病；疾病','/ˈɪl.nəs/','/ˈɪl.nəs/','noun',["Her grandmother had passed away after a long illness.","Many working days this year have been lost through illness."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('peel','v.剥，剥落；削n.皮','/piːl/','/piːl/','noun',["I sat by my sister''s bed, peeling oranges for her.","I peeled (the skin from) a banana and ate it hungrily.","I had been out in the sun too long, and my nose was starting to peel."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fright','n.惊吓；惊骇v.使惊恐','','/fɹaɪt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spine','n.脊柱，脊椎；刺；书脊','/spaɪn/','/spaɪn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('peep','n.偷看；隐约看见，瞥见v.窥视；慢慢露出，出现；吱吱叫','/piːp/','/pip/','noun',["I don''t want to hear a peep out of you!"]);
