INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eighteen','n.十八，十八个adj.十八个的，十八的num.十八','/ˈeɪ.tiːn/','','numeral',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humor','n.幽默，诙谐；心情v.迎合，迁就；顺应','/hjuː.mə(ɹ)/','/ˈhjuːmɚ/','noun',["She has a great sense of humour, and I always laugh a lot whenever we get together.","He was in a particularly vile humour that afternoon.","I know you don''t believe my story, but humour me for a minute and imagine it to be true."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cordial','adj.热忱的，诚恳的；兴奋的n.补品；兴奋剂；甜香酒，甘露酒','/ˈkɔː.dɪ.əl/','/ˈkɔɹ.djəl/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pedal','v.踩踏板；骑车n.踏板；脚蹬子adj.脚的；脚踏的','','','noun',["A piano usually has two or three pedals.","A small organ commonly has only one or two ranks on the pedal.","to pedal one''s loom"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chorus','n.合唱队；齐声；歌舞队v.合唱；异口同声地说','/ˈkɔːɹəs/','/ˈkɔːɹəs/','noun',["The performance of the chorus was awe-inspiring and exhilarating.","The catchiest part of most songs is the chorus.","a chorus of crickets"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brilliant','adj.灿烂的，闪耀的；杰出的；有才气的；精彩的，绝妙的','/ˈbɹɪljənt/','/ˈbɹɪljənt/','noun',["the brilliant lights along the promenade","butterflies with brilliant blue wings","The actor''s performance in the play was simply brilliant."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elastic','adj.有弹性的；灵活的；易伸缩的n.松紧带；橡皮圈','/iˈlæstɪk/','/iˈlæstɪk/','noun',["running shorts use elastic to eliminate the need for a belt","The rope is somewhat elastic, so expect it to give when you pull on it.","elastic band"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shrewd','adj.精明的；狡猾的；机灵的n.精明（的人）；机灵（的人）','/ʃɹuːd/','/ʃɹuːd/','adjective',["a shrewd guess","a shrewd blow, or assault","a shrewd wind"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assurance','n.保证，担保；（人寿）保险；确信；断言；厚脸皮，无耻','/əˈʃɔːɹəns/','/əˈʃɝəns/','noun',["his assurance is intolerable"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('footstep','n.脚步；脚步声；足迹','/ˈfʊtstɛp/','/ˈfʊtstɛp/','noun',["The child watched as his footsteps in the sand were washed away by the waves.","To walk the footsteps of greatness requires that you start at the bottom of a long stair.","The footsteps of the students echoed in the empty hall."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('widow','v.使成寡妇n.寡妇；孀妇','/ˈwɪ.dəʊ/','/ˈwɪ.doʊ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shady','adj.成荫的；阴暗的；名声不好的n.(Shady)人名；(阿拉伯)沙迪','/ˈʃeɪdi/','/ˈʃeɪdi/','adjective',["He is a shady character.","Don''t be shady, give us a go."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intersection','n.交叉；十字路口；交集；交叉点','/ˈɪntəɹˌsɛkʃən/','/ˈɪntəɹˌsɛkʃən/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grocer','n.杂货店；食品商','/ˈɡɹəʊ.sə/','/ˈɡɹəʊ.sə/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shaft','n.拍杆；[机]轴；箭杆；杆状物v.利用；在……上装杆','/ʃɑːft/','/ʃɑːft/','noun',["Her hand slipped off the javelin''s shaft towards the spearpoint and that''s why her score was lowered.","Isn''t that shaft of light from that opening in the cave beautiful?","I had no idea that they removed the feathers'' shafts to make the pillows softer!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slap','v.拍击；侮辱；掌击；掴…的耳光n.掴；侮辱；掌击；拍打声adv.直接地；猛然地；恰好','','','noun',["She slapped him in response to the insult.","He slapped the reins against the horse''s back.","The rain slapped against the window-panes."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dash','n.破折号；冲撞v.使…破灭；猛撞；泼溅','/dæʃ/','/dæʃ/','noun',["Add a dash of vinegar.","There is a dash of craziness in his personality.","Aren''t we full of dash this morning?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trench','n.沟，沟渠；战壕；堑壕v.掘沟','/tɹɛntʃ/','/tɹɛntʃ/','noun',["to trench land for the purpose of draining it","to trench a garden for certain crops"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slam','v.砰地关上；猛力抨击n.猛击；砰然声','/slæm/','/slæm/','noun',["I don''t mean this as a slam, but you can be really impatient sometimes.","Don''t slam the door!","Don''t slam that trunk down on the pavement!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kick','v.踢；反冲，朝后座n.踢；反冲，后座力','/kɪk/','/kɪk/','noun',["A kick to the knee.","The ballerina did a high kick and a leap.","I finally saw the show. What a kick!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plantation','n.栽植；殖民；大农场adj.适用于种植园或热带、亚热带国家的','/plænˈteɪʃən/','/plænˈteɪʃən/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mug','n.杯子；脸；苦读者v.扮鬼脸，做怪相','/mʌɡ/','/mʌɡ/','noun',["What an ugly mug.","He''s a gullible mug – he believed her again.","The children weren''t interested in sitting still for a serious photo; they mugged for the camera."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('questionnaire','n.问卷；调查表','/ˌk(w)estjəˈnɛə/','/ˌk(w)estjəˈnɛə/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mud','v.弄脏；用泥涂n.泥；诽谤的话；无价值的东西','/mʌd/','/mʌd/','noun',["The campaign issues got lost in all the mud from both parties."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shorthand','n.速记；速记法adj.速记法的','/ˈʃɔːthænd/','/ˈʃɔːthænd/','noun',["The jargon becomes a shorthand for these advanced concepts."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('browse','v.浏览；吃草n.浏览；吃草','/bɹaʊz/','/bɹaʊz/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inlet','n.入口，进口；插入物；水湾v.引进;嵌入;插入;','','','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cocaine','n.[药]可卡因','/koʊˈkeɪn/','/koʊˈkeɪn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('width','n.宽度；广度','/ˈwɪdθ/','/ˈwɪdθ/','noun',["Manchester United like to play with width."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lake','n.湖；深红色颜料；胭脂红vt.（使）血球溶解vi.（使）血球溶解','/leɪk/','/leɪk/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plumber','n.水管工；堵漏人员','/ˈplʌmə/','/ˈplʌmə/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clumsy','adj.笨拙的','/ˈklʌmzi/','/ˈklʌmzi/','noun',["He''s very clumsy. I wouldn''t trust him with carrying the dishes.","It is a clumsy solution, but it might work for now."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('liquor','n.酒，含酒精饮料；溶液；液体；烈酒vi.喝酒，灌酒vt.使喝醉','/ˈlɪk.ə(ɹ)/','/ˈlɪk.ə(ɹ)/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paddle','n.划桨；明轮翼v.拌；搅；用桨划','/ˈpæ.dəl/','/ˈpæ.dəl/','noun',["We had a nice paddle this morning.","The paddle practically ousted the British cane for spankings in the independent US.","A sea turtle''s paddles make it swim almost as fast as land tortoises are slow."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toe','n.脚趾；足尖v.用脚尖走；以趾踏触','/təʊ/','/toʊ/','noun',["to toe the mark","The framers toed the irregular pieces into the sill."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weight','n.重量，重力；负担；砝码；重要性v.加重量于，使变重','/weɪt/','/weɪt/','noun',["He''s working out with weights.","the weight of care or business","He was pushing weight."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('density','n.密度','/ˈdɛn.sə.ti/','/ˈdɛn.sə.ti/','noun',["The number of particles per unit volume of a specified volume can be considered to be the particle density for the specified volume."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('withhold','v.保留，不给；隐瞒；抑制','/wɪðˈhəʊld/','/wɪðˈhoʊld/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lane','n.小巷；[航][水运]航线；车道；罚球区','/leɪn/','/leɪn/','noun',["And it''s Uncle Mo in front by two as they come to the top of the lane."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('toy','n.玩具；小装饰品；不值钱的东西v.玩弄；调情；随随便便地对待adj.作为玩具的；玩物似的','/tɔɪ/','/tɔɪ/','noun',["A grown man does not play with a child’s toy.","Figo is toying with the English defence.","I have been toying with the idea of starting my own business."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pedestrian','adj.徒步的；缺乏想像力的n.行人；步行者','/pəˈdɛst.ɹi.ən/','/pəˈdɛst.ɹi.ən/','noun',["pedestrian crossing","His manner of dress was pedestrian but tidy.","The choreographer prefers pedestrian movements."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tow','n.拖；麻的粗纤维；拖曳所用之绳v.拖；牵引；曳','','','',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compatible','adj.兼容的；能共处的；可并立的','/kəmˈpætəbəl/','/kəmˈpætəbəl/','noun',["a computer company that sells IBM compatibles","This printer isn''t compatible with my computer.","My neighbours and I are not very compatible: they''re loud and I''m an introvert."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lamb','n.羔羊，小羊；羔羊肉v.生小羊，产羔羊','/læm/','/læm/','noun',["The shepherd was up all night, lambing her young ewes."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lame','adj.跛足的；僵痛的；不完全的；无说服力的；差劲的，蹩脚的v.变跛','/leɪm/','/leɪm/','noun',["1877, Anna Sewell, Black Beauty: And if you don''t want to lame your horse you must look sharp and get them stones stuck in hooves out quickly.","a lame leg, arm or muscle","He had a really lame excuse for missing the birthday party."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snatch','n.抢夺；抓举；小量v.夺得；抽空做；及时救助','/snætʃ/','/snætʃ/','noun',["The leftfielder makes a nice snatch to end the inning.","I heard a snatch of Mozart as I passed the open window.","He snatched up the phone."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flour','n.面粉；粉状物质v.撒粉于；把…磨成粉','/ˈflaʊə/','/ˈflaʊɚ/','noun',["mustard flour","We transplanted the flowers to a larger pot.","The dogwoods are in flower this week."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lamp','n.灯；照射器vt.照亮vi.发亮','/læmp/','/læmp/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('serial','adj.连续的；连载的；分期偿还的n.电视连续剧；[图情]期刊；连载小说','/ˈsɪəɹiːəɫ/','/ˈsɪəɹiːəɫ/','noun',["Go to these sites for serials, cracks and keygens.","He was a serial entrepreneur, always coming up with a new way to make cash."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garlic','n.大蒜；蒜头','/ˈɡɑːlɪk/','/ˈɡɑːlɪk/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('poultry','n.家禽','/ˈpɒltɹi/','/ˈpoʊltɹi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shake','v.动摇；摇动；震动；握手n.摇动；哆嗦','/ˈʃeɪk/','/ˈʃeɪk/','noun',["She replied in the negative, with a shake of her head.","He shook the can of soda for thirty seconds before delivering it to me, so that, when I popped it open, soda went everywhere.","Shaking his head, he kept repeating \"No, no, no\"."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shine','v.发出光；反射光，闪耀；出类拔萃，表现突出；露出；照耀；显露；出众n.光亮，光泽；好天气；擦亮；晴天；擦皮鞋；鬼把戏或诡计','/ʃaɪn/','/ʃaɪn/','noun',["She''s certainly taken a shine to you.","My nephew tried other sports before deciding on football, which he shone at right away, quickly becoming the star of his school team.","I shone my light into the darkness to see what was making the noise."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obstruct','v.妨碍；阻塞；遮断','/əbˈstɹʌkt/','/əbˈstɹʌkt/','verb',["They obstructed my progress."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('chancellor','n.总理（德、奥等的）；（英）大臣；校长（美国某些大学的）；（英）大法官；（美）首席法官','/ˈtʃɑːnslə/','/ˈtʃɑːnslə/','noun',["Chancellor of the Duchy of Lancaster  Lord Chancellor","the Austrian Chancellor"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slim','adj.苗条的；修长的；微小的；差的v.使…体重减轻；使…苗条n.(Slim)人名；(阿拉伯)萨利姆；(英、西)斯利姆','/slɪm/','/slɪm/','noun',["I only smoke slims.","I''m afraid your chances are quite slim.","A slimly-shod lad;"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('damp','v.使潮湿；使阻尼；使沮丧，抑制n.潮湿，湿气adj.潮湿的','/dæmp/','/dæmp/','noun',["to damp cloth","The lawn was still damp so we decided not to sit down."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('burden','n.负担；责任；船的载货量v.使负担；烦扰；装货于','/ˈbɜːdn/','/ˈbɝdn/','noun',["a ship of a hundred tons burden","A burden of gad steel is 120 pounds.","to burden a nation with taxes"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undergo','v.经历，经受；忍受','/ˌʌndəˈɡəʊ/','/ˌʌndəˈɡəʊ/','verb',["The project is undergoing great changes.","She had to undergo surgery because of her broken leg."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('experimental','adj.实验的；根据实验的；试验性的','/ɨkspɛɹəˈmɛntəl/','/ɨkspɛɹəˈmɛntəl/','noun',["Chemistry is an experimental science.","an experimental engine","experimental knowledge"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imaginative','adj.富于想象的；有创造力的','/-ənətɪv/','/-ənətɪv/','adjective',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ambitious','adj.野心勃勃的；有雄心的；热望的；炫耀的','/æmˈbɪʃ.əs/','/æmˈbɪʃ.əs/','adjective',["an ambitious person","an ambitious attempt to take power"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fence','n.栅栏；围墙；剑术v.防护；用篱笆围住；练习剑术','/fɛns/','/fɛns/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obedient','adj.顺从的，服从的；孝顺的','/əʊˈbiːdɪənt/','/oʊˈbidiənt/','noun',["Jessica was so intensely obedient of her parents that her brother sometimes thought she was a robot."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overwhelming','adj.压倒性的；势不可挡的v.压倒；淹没（overwhelm的ing形式）；制服','/ˌəʊvəˈwɛlmɪŋ/','/ˌoʊvɚˈ(h)wɛlmɪŋ/','verb',["The dinghy was overwhelmed by the great wave.","In December 1939 the Soviet Union attacked Finland with overwhelming force.","He was overwhelmed with guilt."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ascend','v.上升；登高；追溯','/əˈsɛnd/','/əˈsɛnd/','verb',["He ascended to heaven upon a cloud.","You ascend the stairs and take a right.","She ascended the throne when her mother abdicated."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diary','n.日志，日记；日记簿','/ˈdaɪəɹi/','/ˈdaɪəɹi/','noun',["They kept separate diaries. His was on paper and her diary was on her computer''s hard drive."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hospitality','n.好客；殷勤','/hɒs.pɪˈtæl.ɪ.ti/','/hɑs.pɪˈtæl.ɪ.ti/','noun',["Please thank our hosts for their hospitality during the week that we stayed.","After graduating from college, she found a job in hospitality."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dew','n.珠，滴；露水；清新vt.（露水等）弄湿vi.结露水','/djuː/','/du/','noun',["There was a heavy dew this morning."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('king','n.国王；最有势力者；王棋vi.统治；做国王vt.立…为王adj.主要的，最重要的，最大的','/kɪŋ/','/kiŋ/','noun',["Henry VIII was the king of England from 1509 to 1547.","Howard Stern styled himself as the \"king of all media\".","In times of financial panic, cash is king."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('downtown','adv.往闹市区；在市区adj.市中心的n.市中心区；三分线以外','','','noun',["John walked every day to his downtown job.","You need to go downtown four blocks.","That shot came from way downtown!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expire','v.期满；终止；死亡；呼气','/ɛkˈspaɪ.ə(ɹ)/','/ɛkˈspaɪ.ə(ɹ)/','verb',["The patient expired in hospital.","My library card will expire next week."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spray','n.喷雾；喷雾器；水沫v.喷射','/spɹeɪ/','/spɹeɪ/','noun',["The sailor could feel the spray from the waves.","The firemen sprayed the house.","Spray some ointment on that scratch."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brim','n.边；边缘v.满溢；溢出','/bɹɪm/','/bɹɪm/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reconcile','v.使一致；使和解；调停，调解；使顺从','/ˈɹɛkənsaɪl/','/ˈɹɛkənsaɪl/','verb',["to reconcile people who have quarrelled","to reconcile differences"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slit','v.撕裂；使有狭缝n.裂缝；投币口','/ˈslɪt/','/ˈslɪt/','noun',["He slit the bag open and the rice began pouring out."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('charity','n.慈善；施舍；慈善团体；宽容；施舍物','/ˈtʃæɹɪti/','/ˈtʃæɹɪti/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tea','n.茶叶；茶树；茶点vt.给…沏茶vi.喝茶；进茶点','/tiː/','/ti/','noun',["After smoking a bowl of that fine marijuana, they ate some brownies.","a fish supper; a pizza supper","Darjeeling tea is grown in India."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cannon','n.大炮；加农炮；榴弹炮；机关炮v.炮轰；开炮','/ˈkæn.ən/','/ˈkæn.ən/','noun',["In English billiards, a cannon is when one''s cue ball strikes the other player''s cue ball and the red ball on the same shot; and it is worth two points.","He''s got a cannon out in right.","The white cannoned off the red onto the pink."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gear','n.齿轮；装置，工具；传动装置v.适合；搭上齿轮；开始工作adj.好极了','/ɡɪə(ɹ)/','/ɡɪə(ɹ)/','noun',["They have geared the hotel mainly at tourists."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('layoff','n.活动停止期间；临时解雇；操作停止；失业期','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shirt','n.衬衫；汗衫，内衣','/ʃɜːt/','/ʃɝt/','noun',["It can take a while to learn how to iron a shirt properly."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lace','n.花边；鞋带；饰带；少量烈酒v.饰以花边；结带子','/leɪs/','/leɪs/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breathe','v.呼吸；低语；松口气；（风）轻拂','/bɹiːð/','/bɹið/','verb',["Fish have gills so they can breathe underwater.","While life as we know it depends on oxygen, scientists have speculated that alien life forms might breathe chlorine or methane.","I will not allow it, as long as I still breathe."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symbol','n.象征；符号；标志','/ˈsɪmbəl/','/ˈsɪmbəl/','noun',["$ is the symbol for dollars in the US and some other countries.","The lion is the symbol of courage; the lamb is the symbol of meekness or patience.","The Apostles, Nicene Creed and the confessional books of Protestantism, such as the Augsburg Confession of Lutheranism are considered symbols."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eyebrow','n.眉毛v.为…描眉；用皱眉蹙额迫使','/ˈaɪˌbɹaʊ/','/ˈaɪˌbɹaʊ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obedience','n.顺从；服从；遵守','/ə(ʊ)ˈbiːdɪəns/','','noun',["Obedience is essential in any army."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('await','v.等候，等待；期待','/əˈwɛɪt/','','noun',["I await your reply to my letter.","Glorious rewards await the good in heaven; eternal suffering awaits mortal sinners in hell."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kilo','n.千克','/ˈkiːləʊ/','/ˈkiːləʊ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pest','n.害虫；有害之物；讨厌的人','/pɛst/','/pɛst/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miniature','adj.微型的，小规模的n.缩图；微型画；微型图画绘画术vt.是…的缩影','/ˈmɪn(ɪ)ətʃə(ɹ)/','/ˈmɪn(ɪ)ətʃə(ɹ)/','noun',["There was a miniature of a whaling ship in a glass bottle over the mantlepiece.","Sacha composed a miniature for strings as a final project at the conservatory.","Jack had dozens of miniatures of Napoleonic footsoldiers painted in detailed period regalia for his wargames."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dip','v.浸，泡，蘸；舀取；把伸入n.下沉，下降；倾斜；浸渍，蘸湿','/dɪp/','/dɪp/','noun',["There is a dip in the road ahead.","I''m going for a dip before breakfast.","This onion dip is just scrumptious."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weekday','n.平日，普通日；工作日','/ˈwiːkdeɪ/','/ˈwiːkdeɪ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dig','v.挖，掘；探究n.戳，刺；挖苦','/dɪɡ/','/dɪɡ/','noun',["He guffawed and gave me a dig in the ribs after telling his latest joke.","a £1 charity shop dig","If the plane can''t pull out of the dive it is in, it''ll dig a hole in the ground."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('balcony','n.阳台；包厢；戏院楼厅','/ˈbælkəni/','/ˈbælkəni/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enemy','n.敌人，仇敌；敌军adj.敌人的，敌方的','/ˈɛnəmi/','/ˈɛnəmi/','noun',["Crush the enemy!","Rally together against a common enemy."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tumour','n.[肿瘤]瘤；肿瘤；肿块','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('descendant','adj.下降的；祖传的n.后裔；子孙','/dɪˈsɛndənt/','/dɪˈsɛndənt/','noun',["The patriarch survived many descendants: five children, a dozen grandchildren, even a great grandchild.","This famous medieval manuscript has many descendants.","Dogs evolved as descendants of early wolves."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('epoch','n.[地质]世；新纪元；新时代；时间上的一点','/ˈiːˌpɒk/','/ˈeɪˌpɑk/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gymnasium','n.体育馆；健身房','/dʒɪmˈneɪ.zi.əm/','/dʒɪmˈneɪ.zi.əm/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bronze','n.青铜；古铜色；青铜制品adj.青铜色的；青铜制的v.镀青铜于','/bɹɒnz/','/bɹɑnz/','noun',["She wanted to win the tournament, but had to settle for the bronze after being beaten in the semi-finals.","My mother bronzed my first pair of baby shoes."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('classroom','n.教室','/ˈklɑːsɹʊm/','/ˈklɑːsɹʊm/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sway','v.影响；统治；使摇动n.影响；摇摆；统治','/sweɪ/','/sweɪ/','noun',["The old song caused a little sway in everyone in the room.","I doubt I''ll hold much sway with someone so powerful.","sway to the music;  The trees swayed in the breeze."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('petrol','n.（英）汽油','/ˈpɛt.ɹəl/','/ˈpɛt.ɹəl/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('swan','n.天鹅；天鹅星座v.游荡，闲荡','/swɒn/','/swɑn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cluster','n.群；簇；丛；串v.群聚；丛生','/ˈklʌstə/','/ˈklʌstə/','noun',["A cluster of flowers grew in the pot.","The Pleiades cluster contains seven bright stars.","examples of clusters would include \"in accordance with\", \"the results of\" and \"so far\""]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lady','n.女士，夫人；小姐；妻子','/ˈleɪdi/','/ˈleɪdi/','noun',["Sir John Smith and Lady Smith.","\"I would like the dining room to be fully set by tonight; would you do so?\" \"Yes, my lady\".","Please direct this lady to the soft furnishings department."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cancel','vi.相互抵消vt.取消；删去，划掉；把…作废','/ˈkænsl̩/','/ˈkænsl̩/','noun',["He cancelled his order on their website.","This machine cancels the letters that have a valid zip code.","The corrective feedback mechanism cancels out the noise."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explosive','adj.爆炸的，爆发的；使人冲动的；导致猛烈爆发的n.爆炸物，炸药','','','noun',["an explosive device","an explosive fire","an explosive accusation"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('surgeon','n.外科医生','/ˈsɜːdʒən/','/ˈsɜːdʒən/','noun',["The surgeon refused to operate because the patient was her son."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abrupt','adj.突然的，意外的；唐突的，鲁莽的','/aˈbɹʌpt/','/aˈbɹʌpt/','noun',["The party came to an abrupt end when the parents of our host arrived."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discourage','vt.使泄气，使失去信心；阻碍','/dɪsˈkʌɹɪd͡ʒ/','/dɪsˈkɝɪd͡ʒ/','noun',["Don''t be discouraged by the amount of work left to do: you''ll finish it in good time."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spontaneous','adj.自发的，自然产生的','/spɒnˈteɪ.ni.əs/','/spɑnˈteɪ.ni.əs/','adjective',["He made a spontaneous offer of help."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wreck','n.失事的船，残骸；失事vt.失事，遇难；破坏，毁坏<','/ˈɹɛk/','/ˈɹɛk/','noun',["He was an emotional wreck after the death of his wife.","He wrecked the car in a collision."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rabbit','n.兔子','/ˈɹæbət/','/ˈɹæbɪt/','noun',["The pioneers survived by eating the small game they could get: rabbits, squirrels and occasionally a raccoon.","The informant seemed skittish, as if he was about to rabbit."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gloomy','adj.阴沉的，阴暗的；令人沮丧的，抑郁的','/ˈɡlumi/','/ˈɡlumi/','adjective',["The cavern was gloomy.","a gloomy temper or countenance"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reproach','n.责备,耻辱','/ɹɪˈpɹəʊtʃ/','/ɹɪˈpɹoʊtʃ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('warrant','n.正当理由；许可证；委任状vt.保证，担保','/ˈwɒɹənt/','/ˈwɑɹənt/','noun',["a warrant of authenticity; a warrant for success","an arrest warrant issued by the court","That tree is going to fall, I’ll warrant."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sake','n.缘故','/seɪk/','/seɪk/','noun',["For the sake of argument","For old times'' sake"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conceal','vt.隐藏，隐瞒，隐蔽','/kənˈsiːl/','/kənˈsiːl/','verb',["He tried to conceal the truth about his health."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sniff','vi.以鼻吸气，用力吸入vt.嗅，闻n.吸气；嗅，闻','/snɪf/','/snɪf/','noun',["She gave the flowers a quick sniff to check they were real.","I sniffed the meat to see whether it had gone off.","\"He''s never coming back, is he?\" she sniffed while looking at a picture of him."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('narrative','adj.叙述的；有故事性的n.叙述；记叙文','/ˈnæɹətɪv/','/ˈnæɹətɪv/','noun',["The plot is full of holes, but the narrative is extremely compelling.","the narrative thrust of a film"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scratch','v.抓，搔，扒n.抓，搔；抓痕；起跑线','/skɹætʃ/','/skɹætʃ/','noun',["Her skin was covered with tiny scratches.","The dog sat up and had a good scratch.","There were two scratches in race 8, which reduced the field from 9 horses to 7."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cooperative','adj.合作的，协作的n.合作社','','','noun',["The patient was rarely cooperative, and tended to refuse treatment.","a cooperative business enterprise"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('triple','adj.三部分的；三方的；三倍的，三重的v.增至三倍','/ˈtɹɪpl/','','noun',["I''ve had a hard day; make that a triple.","I''d like a triple with cheese.","The shortstop hit a triple to lead off the ninth."]);
