INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rational','adj.理性的；合理的','/ˈɹæʃ(ə)nəl/','/ˈɹæʃ(ə)nəl/','noun',["The quotient of two rationals is again a rational.","Man is a rational creature.","His statements were quite rational."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('halt','v.止步，停止n.止步，停步，停止前进','/hɔːlt/','/hɔːlt/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sunset','n.日落','/ˈsʌnˌsɛt/','/ˈsʌnˌsɛt/','noun',["one''s sunset years","The tax increase legislation included a sunset clause requiring renewal to prevent the tax increase from expiring.","We''ll be sunsetting version 1.9 of the software shortly after releasing version 2.0 next quarter."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violent','adj.猛烈的，激烈的；暴力引起的，强暴的<','/ˈvaɪ(ə)lənt/','/ˈvaɪ(ə)lənt/','noun',["A violent wind ripped the branch from the tree.","We would rather negotiate, but we will use violent means if necessary.","The escaped prisoners are considered extremely violent."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('faithful','adj.守信的，忠实的；如实的','/ˈfeɪθ.fəl/','/ˈfeɪθ.fəl/','noun',["The faithful pray five times a day.","My dog is a very faithful dog: he doesn''t like to be petted by anybody else.","My servant is very faithful."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('huddle','v.聚集在一起，挤作一团n.挤在一起的人，一堆杂乱的东西','/ˈhʌdəl/','/ˈhʌdəl/','noun',["The sheep huddled together seeking warmth."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('skeleton','n.骨骼；骨架；框架；梗概，提要','/ˈskɛlətən/','/ˈskɛlətən/','noun',["She dressed up as a skeleton for Halloween.","She lost so much weight while she was ill that she became a skeleton.","The skeleton of the organisation is essentially the same as it was ten years ago, but many new faces have come and gone."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('illiterate','adj.文盲的，未受教育的','/ɪˈlɪtəɹət/','/ɪˈlɪtəɹət/','noun',["The government is run by business illiterates.","economically illiterate, emotionally illiterate"]);
