INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scholarship','n.奖学金A；学问，学识','/ˈskɒləʃɪp/','/ˈskɒləʃɪp/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('implement','vt.使生效；实施；执行，贯彻<n.工具，器具','/ˈɪmpləmənt/','/ˈɪmpləmənt/','noun',["They carried an assortment of gardening implements in the truck."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fantasy','n.想象，幻想；幻想的产物','/ˈfæntəsi/','/ˈfæntəsi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gorgeous','adj.华丽的，绚丽的；令人十分愉快的，极好的','/ˈɡɔːdʒəs/','/ˈɡɔɹdʒəs/','adjective',["All the contest judges agreed that Brigitt was absolutely gorgeous.","Hummus is absolutely gorgeous."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('erosion','n.腐蚀，磨损；削弱，减少','/əˈɹəʊʒən/','/əˈɹəʊʒən/','noun',["the erosion of a person''s trust"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ascend','v.上升','/əˈsɛnd/','/əˈsɛnd/','verb',["He ascended to heaven upon a cloud.","You ascend the stairs and take a right.","She ascended the throne when her mother abdicated."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harm','n.伤害，损害，危害vt.伤害，损害，危害','/hɑːm/','/hɑɹm/','noun',["No harm came to my possessions.","Although not physically injured in the car accident, she received some psychological harm.","I wish him no harm."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lens','n.透镜；镜头','/lɛnz/','/lɛnz/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('embody','vt.体现，使具体化','/ɪmˈbɒdi/','/ɪmˈbɒdi/','verb',["As the car salesman approached, wearing a plaid suit and slicked-back hair, he seemed to embody sleaze.","The US Constitution aimed to embody the ideals of diverse groups of people, from Puritans to Deists."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nowhere','adv.任何地方都不，没有地方<','/ˈnəʊ.wɛə/','/ˈnoʊ.(h)wɛɹ/','noun',["They went on a cruise to nowhere.","Nowhere did the rules say anything about popcorn.","We sat in traffic, going nowhere."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spoil','vt.损坏，破坏；宠坏，溺爱','/spɔɪl/','/spɔɪl/','noun',["Make sure you put the milk back in the fridge, otherwise it will spoil."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('multiply','v.乘，使相乘；繁殖；倍增，增加','/ˈmʌltɪplaɪ/','/ˈmʌltɪplaɪ/','noun',["when you multiply 3 by 7, you get 21;  he multiplied several numbers","He had been multiplying, but it occurred to him he needed to resolve the exponents, first."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pasture','n.牧草地；牧场','/ˈpɑːstjə/','/ˈpæstʃɚ/','noun',["The farmer pastures fifty oxen; the land will pasture forty cows."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('multiple','adj.多样的，多重的<n.倍数','/ˈmʌltɪpl̩/','/ˈmʌltɪpl̩/','noun',["14, 21 and 70 are multiples of 7","My Swiss Army knife has multiple blades.","It was a multiple pregnancy: the woman had triplets."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('magnet','n.磁体；磁铁','/ˈmæɡnət/','/ˈmæɡnət/','noun',["He always had a girl on his arm – he''s a bit of a babe magnet."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('explosion','n.爆炸；爆发；激增','/ɪkˈspləʊ.ʒən/','/ɛkˈsploʊ.ʒən/','noun',[]);
