INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('up-to-date','adj.最新的，新式的','/ˌʌp tə ˈdeɪt/','/ˌʌp tə ˈdeɪt/','adjective',["Use an up-to-date text for your source.","I like to stay up-to-date about current affairs."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('permit','v.许可，允许n.许可证，执照','','','noun',["A construction permit can be obtained from the town offices.","The Building Department permitted that project last week.","We''ve been busy permitting the State Street development."]);
