INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stagger','vi.蹒跚，摇晃vt.使吃惊；使错开，使交错n.蹒跚，踉跄','/ˈstæɡə/','/ˈstæɡə/','noun',["the stagger of a drunken man","apoplectic or sleepy staggers"]);
