INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sensitive','adj.敏感的，灵敏的；易受伤害的','/ˈsɛnsɪtɪv/','/ˈsɛnsɪtɪv/','noun',["Max is very sensitive; he cried today because of the bad news.","Religion is often a sensitive topic of discussion and should be avoided when dealing with foreign business associates.","These are highly sensitive documents."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('protest','v.抗议，反对n.抗议，反对','/ˈpɹəʊ.tɛst/','/ˈpɹoʊ.tɛst/','noun',["They lodged a protest with the authorities.","We held a protest in front of City Hall.","How dare you, I protest!"]);
