INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obsession','n.牵挂，惦念；迷住，入迷；困扰；萦绕于心的事物或人；固执的念头<','/əbˈsɛʃən/','/əbˈsɛʃən/','noun',[]);
