INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('immune','adj.免疫的，有免疫力的A；不受影响的；免除的，豁免的','','/ɪˈmjuːn/','noun',["As a diplomat, you are immune from prosecution.","I am immune to chicken pox.","Alas, he was immune to my charms."]);
