INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('annoy','vt.使恼怒，使生气；打搅','/əˈnɔɪ/','/əˈnɔɪ/','noun',["Marc loved his sister, but when she annoyed him he wanted to switch her off.","to annoy an army by impeding its march, or by a cannonade"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glue','n.胶，胶水vt.胶合，粘贴','/ɡluː/','/ɡluː/','noun',["I need to glue the chair-leg back into place.","His eyes were glued to the screen."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reflect','vi.反省，细想；考虑vt.反映；表现','/ɹɪˈflɛkt/','/ɹɪˈflɛkt/','verb',["A mirror reflects the light that shines on it.","The moonlight reflected from the surface of water.","The shop window reflected his image as he walked past."]);
