INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ignorant','adj.无知的，愚昧的；不知道的','/ˈɪɡnəɹənt/','/ˈɪɡnəɹənt/','noun',["His manner was at best off-hand, at worst totally ignorant."]);
