INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('setback','n.挫折；倒退；失败','/ˈsɛtbæk/','/ˈsɛtbæk/','noun',["After some initial setbacks, the expedition went safely on its way.","Setbacks were initially used for structural reasons, but now are often mandated by land use codes."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spray','n.喷雾，飞沫；浪花，水花<vt.喷洒，喷射','/spɹeɪ/','/spɹeɪ/','noun',["The sailor could feel the spray from the waves.","The firemen sprayed the house.","Spray some ointment on that scratch."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distinguish','vt.区别，辨别；辨认出；使杰出；使著名','/dɪsˈtɪŋɡwɪʃ/','/dɪsˈtɪŋɡwɪʃ/','verb',["The soldier distinguished himself in combat and received a medal."]);
