INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intention','n.意图，意向，目的','/ɪnˈtɛnʃən/','/ɪnˈtɛnʃən/','noun',["It’s easy to promise anything when you have no intention of fulfilling any of it."]);
