INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('funeral','n.丧葬，葬礼','/ˈfjuːnəɹəl/','/ˈfjunəɹəl/','noun',["Many mourners turned up at the local artist''s funeral to pay homage."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impulse','n.推动；冲动；刺激','/ˈɪmpʌls/','/ˈɪmpʌls/','noun',["The impulse to learn drove me to study night and day.","The total impulse from the impact will depend on the kinetic energy of the bullet."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('infectious','adj.传染的，传染性的；有感染力的','','','adjective',["Cancer is not infectious.","Despite feeling better, the patient is still infectious.","Her enthusiasm for work can be really infectious."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('religious','adj.宗教的；信教的；虔诚的','/ɹɪ.ˈlɪ.d͡ʒəs/','','noun',["It is the job of this court to rule on legal matters. We do not consider religious issues.","I was much more religious as a teenager than I am now.","I''m a religious fan of college basketball."]);
