INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fundamental','adj.基础的，基本的','/ˌfʌndəˈmɛntəl/','/ˌfʌndəˈmɛntəl/','noun',["one of the fundamentals of linear algebra","A need for belonging seems fundamental to humans."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('global','adj.全球的，世界的','/ˈɡləʊbəl/','/ˈɡləʊbəl/','noun',["Pollution is a global problem.","In the center was a small, global mass."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('entitle','vt.给以权利；给…以称号；给…题名','/ənˈtaɪtəl/','/ənˈtaɪtəl/','verb',["A passport entitles the bearer to travel to other countries."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('outline','n.轮廓，略图；大纲，梗概vt.概述，略述','/ˈaʊtlaɪn/','/ˈaʊtlaɪn/','noun',["the outline of a speech","Wikipedia items featuring books usually outline them after giving their background."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fade','v.褪色；衰减，消失','/feɪd/','/feɪd/','noun',["The milkman''s whistling faded into the distance."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nominal','adj.名义上的；微不足道的','/ˈnɑm.ɪnl̩/','/ˈnɑm.ɪnl̩/','noun',["This sentence contains two nominals.","Numeric codes of characters used in programming are nominals.","a nominal difference"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excess','adj.过量的，额外的n.过量，过剩','/əkˈsɛs/','/əkˈsɛs/','noun',["The excess of heavy water was given away to the neighbouring country.","The difference between two numbers is the excess of one over the other."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('thrift','n.节约，节俭','/θɹɪft/','/θɹɪft/','noun',["His thrift can be seen in how little the trashman takes from his house.","Usually, home mortgages are obtained from thrifts."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perspective','n.透视画法；透视图；远景，前途；观点，看法','/pɚˈspɛktɪv/','/pɚˈspɛktɪv/','noun',["a perspective drawing"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('galaxy','n.星系；银河A<；一群A<','/ˈɡaləksi/','/ˈɡæləksi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equality','n.同等，平等','/ɪˈkwɒl.ɪ.ti/','/ɪˈkwɒl.ɪ.ti/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dictation','n.听写，口述；命令','/dɪkˈteɪʃən/','/dɪkˈteɪʃən/','noun',["Since I learned shorthand, I can take dictation at eighty words a minute.","1908: Lucy Maud Montgomery, Anne of Green Gables - We had reading and geography and Canadian history and dictation today.","1852: Lysander Spooner, An Essay on the Trial by Jury - ...jurors in England have formerly understood it to be their right and duty to judge only according to their consciences, and not to submit to any dictation from the court, either as to law or fact."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rebellion','n.叛乱，反抗，起义','/ɹɪˈbɛl.i.ən/','/ɹɪˈbɛl.i.ən/','noun',["The government is doing its best to stop rebellion in the country.","Having a tattoo was Mathilda''s personal rebellion against her parents.","The army general led a successful rebellion and became president of the country."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('invade','v.侵入，侵略，侵害','/ɪnˈveɪd/','/ɪnˈveɪd/','verb',["Under some circumstances police are allowed to invade a person''s privacy.","Argentinian troops invaded the Falkland Islands in 1982.","The picnic was invaded by ants."]);
