INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cradle','n.摇篮A；发源地','/ˈkɹeɪdəl/','/ˈkɹeɪdəl/','noun',["a cradle of crime","from the cradle to the grave","The cradle was ill-made. One victim fell into the sea and was lost and the ensuing delay cost three more lives."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('collection','n.收藏，收集','/kəˈlɛkʃən/','/kəˈlɛkʃən/','noun',["The asteroid belt consists of a collection of dust, rubble, and minor planets.","He has a superb coin collection.","Collection of trash will occur every Thursday."]);
