INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vital','adj.生死攸关的，重大的；生命的，生机的','/ˈvaɪt̬əl/','/ˈvaɪt̬əl/','adjective',["vital energies; vital functions; vital actions","The brain is a vital organ.","The transition to farming was vital for the creation of civilisation."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conflict','vi.抵触，冲突An.战斗，斗争；矛盾，冲突','/kənˈflɪkt/','/kənˈflɪkt/','noun',["The conflict between the government and the rebels began three years ago.","I wanted to attend the meeting but there''s a conflict in my schedule that day.","It appears that our schedules conflict."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('update','vt.更新；使现代化','','','noun',["He gave me an update on the situation in New York.","I just made an update to the Wikipedia article on guerillas.","I just made an update to my blog about my trip to Rome."]);
