INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compatible','adj.能和睦相处的，合得来的；兼容的','/kəmˈpætəbəl/','/kəmˈpætəbəl/','noun',["a computer company that sells IBM compatibles","This printer isn''t compatible with my computer.","My neighbours and I are not very compatible: they''re loud and I''m an introvert."]);
