INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('profession','n.职业，自由职业；公开表示','/pɹəˈfɛʃən/','/pɹəˈfɛʃən/','noun',["Despite his continued professions of innocence, the court eventually sentenced him to five years.","My father was a barrister by profession.","His conduct is against the established practices of the legal profession."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deplore','vt.悲悼，哀叹；谴责','/dɪˈplɔː/','/dɪˈplɔː/','verb',["I deplore my neighbour for having lost his job.","I deplore how you treated him at the party."]);
