INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imagination','n.想象，空想；想象力','/ɪˌmædʒəˈneɪʃən/','/ɪˌmædʒəˈneɪʃən/','noun',["Imagination is one of the most advanced human faculties.","You think someone''s been following you? That''s just your imagination.","His imagination makes him a valuable team member."]);
