INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('steep','adj.陡峭的，险峻的','/stiːp/','/stiːp/','noun',["a steep hill or mountain; a steep roof; a steep ascent; a steep barometric gradient","Twenty quid for a shave? That''s a bit steep.","The steep rake of the windshield enhances the fast lines of the exterior. http//legacy.sandiegouniontribune.com/uniontrib/20070303/news_lz1dd3maynard.html"]);
