INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('privilege','n.特权，优惠，特许vt.给予优惠，给予特权','/ˈpɹɪv(ɪ)lɪdʒ/','/ˈpɹɪv(ɪ)lɪdʒ/','noun',["All first-year professors here must teach four courses a term, yet you''re only teaching one! What entitled you to such a privilege?","Your honor, my client is not required to answer that; her response is protected by attorney-client privilege.","to privilege representatives from arrest"]);
