INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attendant','adj.伴随的，随之而生的n.服务员，值班员；护理人员','/əˈtɛndənt/','/əˈtɛndənt/','noun',["Give your keys to the parking attendants and they will park your car for you.","They promoted him to supervisor, with all the attendant responsibilities and privileges.","the widow attendant to the heir"]);
