INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monetary','adj.金融的，货币的','/ˈmʌnɪtəɹi/','/ˈmɑnɪteɹi/','adjective',[]);
