INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('performance','n.履行，执行；表演，演出；性能，特性','[pə.ˈfɔː.məns]','[pɚ.ˈfɔɹ.məns]','noun',["the performance of an undertaking or a duty","Better performance means more work accomplished in shorter time and/or using fewer resources."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('serial','adj.连续的，按顺序排列的n.连续剧；连载故事','/ˈsɪəɹiːəɫ/','/ˈsɪəɹiːəɫ/','noun',["Go to these sites for serials, cracks and keygens.","He was a serial entrepreneur, always coming up with a new way to make cash."]);
