INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blush','n./','/blʌʃ/','/blʌʃ/','noun',["He wasn''t used to this much attention, so he blushed as he saw dozens of pairs of eyes watching him.","I wasn''t surprised, but it was embarrassing enough that I blushed a little pink.","Looking at me with a knowing glare, she blushed her discomfort with the situation."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tiresome','adj.使人厌倦的；讨厌的','/ˈtaɪəsəm/','/ˈtaɪəsəm/','adjective',["Eventually his long stories became tiresome."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dubious','adj.有问题的，靠不住的；半信半疑的，可疑的；结果未定的，不能确定的','/ˈdjuːbi.əs/','/ˈdu.bi.əs/','adjective',["After he made some dubious claims about the company, fewer people trusted him.","She was dubious about my plan at first, but later I managed to persuade her to cooperate."]);
