INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('finite','adj.有限的','/ˈfaɪnaɪt/','/ˈfaɪnaɪt/','adjective',["The \"goes\" in \"he goes\" is a finite form of a verb"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amend','vt.修改，修正','/əˈmɛnd/','/əˈmɛnd/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('erupt','vi.爆发','/ɪˈɹʌpt/','/ɪˈɹʌpt/','verb',["The volcano erupted, spewing lava across a wide area.","The third molar tooth erupts late in most people, and sometimes does not appear at all.","The crowd erupted in anger."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('remedy','n.药品；治疗措施，补救办法vt.治疗，医治A；纠正，补救<','/ˈɹɛmədi/','/ˈɹɛmədi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consent','vi.同意；赞成，答应n.同意；赞成，答应','/kənˈsɛnt/','/kənˈsɛnt/','noun',["After reflecting a little bit, I''ve consented."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retreat','vi.撤退，退却n.撤退，退却','/ɹəˈtɹiːt/','/ɹəˈtɹiːt/','noun',["a retreating forehead"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parachute','v.跳伞n.降落伞A','/ˈpæɹəʃuːt/','/ˈpæɹəʃuːt/','noun',["The soldiers were parachuted behind enemy lines."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mutual','adj.相互的，彼此的；共有的<','/ˈmjuːt͡ʃuəl/','','noun',["They were mutual enemies.","Mutual insurance.","They had mutual fear of each other."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shell','n.壳，贝壳A；炮弹；弹壳A','/ʃɛl/','/ʃɛl/','noun',["The restaurant served caramelized onion shells.","The first lyre may have been made by drawing strings over the underside of a tortoise shell.","The setback left him a mere shell; he was never the same again."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pharmacy','n.药剂学，制药；药店','/ˈfɑːməsi/','/ˈfɑɹməsi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('therefore','adv.因此，从而conj.所以','/ˈðɛəfɔː/','/ˈðɛəɹfɔɹ/','adverb',["Traditional values will always have a place, therefore they will never lose relevance."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exchange','vt.交换，互换；调换，更换n.交换，调换；兑换；交流，交易；交换台，交易所','/ɛksˈtʃeɪndʒ/','/ɛksˈtʃeɪndʒ/','noun',["All in all, it was an even exchange.","The stock exchange is open for trading.","NPA-NXX-1234 is standard format, where NPA is the area code and NXX is the exchange."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hesitate','vi.犹豫，踌躇；含糊，支吾','/ˈhɛzɪteɪt/','/ˈhɛzɪteɪt/','verb',["He hesitated whether to accept the offer or not; men often hesitate in forming a judgment."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rifle','n.步枪','/ˈɹaɪfəl/','/ˈɹaɪfəl/','noun',["She made a mess when she rifled through the stack of papers, looking for the title document."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('paste','n.糊，糨糊vt.粘，贴','/peɪst/','/peɪst/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overtake','v.追上，赶上；超过；袭击；压倒','/ˈəʊvə(ɹ).teɪk/','/oʊvɚˈteɪk/','verb',["The car was so slow we were overtaken by a bus.","Our plans were overtaken by events."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('directory','n.人名地址录；号码簿<','/daɪˈɹɛktəɹi/','/daɪˈɹɛktəɹi/','noun',[]);
