INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overnight','adv.一夜间；一下子；突然adj.一夜间的；一下子的；突然的','','','noun',["Have you looked at the overnights yet?","We can overnight you the documents for signature.","The overnight ferry docked at 10AM."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behave','vi.举止，举动，表现；运转，开动','/bəˈheɪv/','/bəˈheɪv/','verb',["You need to behave yourself, young lady.","He behaves like a child whenever she''s around.","His mother threatened to spank him if he didn''t behave."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('undo','vt.松开，解开','/ʌnˈduː/','/ʌnˈduː/','noun',["How many undos does this program support?","Fortunately, we can undo most of the damage to the system by the war.","Could you undo my buckle for me?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('laser','n.激光<','/ˈleɪz.ə(ɹ)/','/ˈleɪz.ə(ɹ)/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mixture','n.混合；混合物；混合剂','/ˈmɪkstʃə/','/ˈmɪkstʃɚ/','noun',["A teaspoonful of the mixture to be taken three times daily after meals"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scope','n.范围；机会；余地','/ˈskoʊp/','/ˈskoʊp/','noun',["the scope of an adverb","The surgeon will scope the football player''s knee to repair damage to a ligament.","If we locally scope the user''s login name, it won''t be accessible from outside this function."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('archaeology','n.考古学','/ˌɑː.kiˈɒ.lə.dʒi/','/ˌɑɹ.kiˈɑ.lə.dʒi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('democratic','adj.民主的','/dɛməˈkɹætɪk/','/dɛməˈkɹætɪk/','adjective',["The United States is a democratic country, as the citizens are allowed to choose leaders to represent their interests.","Mount Vernon is run by a strong democratic party organization."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('colonel','n.上校','/ˈkɜːnəl/','/ˈkɝnəl/','noun',[]);
