INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('identify','vt.确认；识别；鉴定；把…和…看成一样，打成一片','/aɪˈdɛn.tɪ.faɪ/','/aɪˈdɛn.tɪ.faɪ/','verb',["The Associated Press will not identify the suspect of the crime because he is a juvenile."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nitrogen','n.氮<','/ˈnaɪ.tɹə.dʒən/','/ˈnaɪ.tɹə.dʒən/','noun',["The two nitrogens are located next to one another on the ring."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('label','n.标签，标记；称号，外号vt.贴标签于…；把…称为<','/ˈleɪbəl/','/ˈleɪbəl/','noun',["Although the label priced this poster at three pounds, I got it for two.","Ever since he started going to the rock club, he''s been given the label \"waster\".","The label signed the band after hearing a demo tape."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('message','n.消息，信息，通讯；启示，要旨','/ˈmɛsɪd͡ʒ/','/ˈmɛsɪd͡ʒ/','noun',["We''ve just received an urgent message from the President.","The main message of the novel is that time heals all wounds.","I messaged her about the concert."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('modify','vt.更改，修改；改造<；缓和；减轻；降低','/ˈmɒdɪfaɪ/','/ˈmɑdɪfaɪ/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clone','v.克隆n.无性繁殖系，克隆；复制品，翻版','/kləʊn/','/kloʊn/','noun',["The scientists were able to clone a sheep."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pledge','n.誓约；保证vt.发誓；保证','/plɛdʒ/','/plɛdʒ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exempt','adj.被免除的，被豁免的vt.使…免除','/ɛɡˈzɛm(p)t/','/ɛɡˈzɛm(p)t/','noun',["Citizens over 45 years of age were exempted from military service.","His income is so small that it is exempt from tax."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reservoir','n.水库，蓄水池','/ˈɹɛz.ə.vwɑː(ɹ)/','/ˈɹɛz.ə(ɹ).vwɑɹ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crab','n.螃蟹；蟹肉','/kɹæb/','/kɹæb/','noun',["Although crabs themselves are an easily treated inconvenience, the patient and his partner(s) clearly run major STD risks."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aesthetic','adj.美学的，艺术的；审美的','/iːs.ˈθe.tɪk/','/ɛs.ˈθɛ.tɪk/','noun',["Her most recent works have this quirky, half-serious 90''s teen culture-inspired aesthetic.","It works well enough, but the shabby exterior offends his aesthetic sensibilities."]);
