INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drastic','adj.激烈的；严厉的','/ˈdɹɑːs.tɪk/','/ˈdɹæs.tɪk/','noun',["If our third attempt fails, we may need drastic ideas."]);
