INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retail','n.零售','/ˈɹiˌteɪl/','/ˈɹiˌteɪl/','noun',["She works in retail.","I never pay retail for clothes.","We''ve shut shown our reseller unit. We''re only selling retail now."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('local','adj.地方的，当地的；局部的','/ˈləʊkl̩/','/ˈloʊkl̩/','noun',["It''s easy to tell the locals from the tourists.","I''m in the TWU, too. Local 6.","The expresses skipped my station, so I had to take a local."]);
