INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accommodate','vt.留宿，收容；供应，供给；调和；适应','/əˈkɒməˌdeɪt/','/əˈkɑməˌdeɪt/','verb',["to accommodate ourselves to circumstances","to accommodate differences","to accommodate an old friend for a week"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bubble','vi.冒泡，起泡；沸腾n.泡，水泡，气泡；泡沫；幻想的计划<','/ˈbʌb.əl/','/ˈbʌb.əl/','noun',["bubbles in window glass, or in a lens","dot-com bubble","Are you having a bubble?!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yield','vi.屈服，服从vt.出产，生长n.产量，收获','/jiːld/','/jiːld/','verb',["Yield the right of way to pedestrians.","They refuse to yield to the enemy.","Historically, that security yields a high return."]);
