INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moan','vi.呻吟；抱怨，发牢骚n.呻吟声，呜咽声Avt.以呻吟声说出','/məʊn/','/moʊn/','noun',["‘Please don''t leave me,’ he moaned."]);
