INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glove','n.手套','/ɡlʌv/','/ɡlʌv/','noun',["I wore gloves to keep my hands warm.","Frederico had a great glove, but he couldn''t hit a curveball, so he never broke into the pros.","to throw down the glove, i.e. to offer a challenge; to take up the glove, to accept it"]);
