INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spur','n.靴刺，马刺；刺激，刺激物Avt.刺激，激励<','/spɜː/','/spɝ/','noun',["to spur boots"]);
