INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insect','n.昆虫<','/ˈɪnsɛkt/','/ˈɪnsɛkt/','noun',["Our shed has several insect infestions, including ants, yellowjackets, and wasps.","The swamp is swarming with every sort of insect.","The manager’s assistant was the worst sort of insect."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('buffet','n.自助餐','/ˈbʊfeɪ/','/bəˈfeɪ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('presume','vt.假定，假设；认为；揣测','/pɹɪˈzjuːm/','/pɹiˈz(j)um/','verb',["I wouldn''t presume to tell him how to do his job.","Don''t make the decision yourself and presume too much.","Dr. Livingstone, I presume?"]);
