INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('border','n.边界，国界；边vt.交界，与…接壤；接近<','/ˈbɔːdə/','/ˈbɔɹdɚ/','noun',["the borders of the garden","There''s a nice frilly border around the picture frame.","The border between Canada and USA is the longest in the world."]);
