INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('admission','n.允许进入；接纳，收容<；入场费，入场券；承认','/ædˈmɪʃ.ən/','/ædˈmɪʃ.ən/','noun',["I request admission for two adults","There is no way he has seen that show, the admission is more than he makes in a week."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adhere','vi.黏附，胶着；坚持','/ædˈhiɹ/','/ædˈhiɹ/','verb',["wax adhered to his finger"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expense','n.花费，消费；消耗','/ɪkˈspɛns/','/ɪkˈspɛns/','noun',["Buying the car was a big expense, but will be worth it in the long run.","Jones reached the final at the expense of Smith, who couldn''t beat him.","It should be acceptable to expense a business lunch with a client."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('April','n.四月','','','',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rumour','n.传闻，谣言','/ˈɹuːmə(ɹ)/','/ˈɹuːmə(ɹ)/','noun',["There''s a rumor going round that he''s going to get married.","They say he used to be a thief, but that''s just rumor.","John is rumored to be next in line for a promotion."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('panorama','n.概观，全景；综述','/ˌpæ.nəˈɹæ.mə/','/ˌpæ.nəˈɹæ.mə/','noun',[]);
