INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mock','v.嘲笑，讥笑adj.仿制的，假装的；模拟的，演习的n.模拟考试','/mɒk/','/mɑk/','noun',["He got a B in his History mock, but improved to an A in the exam.","What''s the best way to mock a database layer?","mock leather"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amplifier','n.放大器；扩音机','/ˈæm.plə.faɪ.ə/','/ˈæm.plə.faɪ.ə/','noun',[]);
