INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dumb','adj.哑的，无言的','/dʌm/','/dʌm/','adjective',["His younger brother was born dumb, and communicated with sign language.","dumb show","You are so dumb! You don''t even know how to make toast!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quiver','v.颤抖，抖动n.颤抖，抖动','/ˈkwɪvəɹ/','/ˈkwɪvəɹ/','noun',["He''s got lots of sales pitches in his quiver."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('telegraph','v.打电报传达，电告n.电报机；电报','/ˈtɛl.ə.ɡɹæf/','','noun',["Her frown telegraphed her displeasure."]);
