INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('attract','v.吸引，引诱；引起','/əˈtɹækt/','/əˈtɹækt/','verb',["A magnet attracts iron filings.","Advertising is designed to attract customers.","to attract admirers;   His big smile and brown eyes instantly attracted me."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('description','n.描写，形容；种类','/dɪˈskɹɪpʃən/','','noun',["The zoo had no lions, tigers, or cats of any description.","The type description of the fungus was written by a botanist."]);
