INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negative','adj.否定的；消极的；反面的；【数】负的；【电】阴性的n.负数；底片','/ˈnɛ(e)ɡəˌɾɪv/','/-ɾɪv/','noun',["Customers didn’t like it: feedback was mostly negative.","I don’t like to hang around him very much because he can be so negative about his petty problems.","The nitro group is negative."]);
