INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('boot','n.靴','/buːt/','/but/','noun',["I booted the ball toward my teammate.","We need to boot those troublemakers as soon as possible","Sorry, I didn’t mean to boot all over your couch."]);
