INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('target','n.目标，对象，靶子vt.把…作为目标','/tɑːɡɪt/','/ˈtɑɹɡɪt/','noun',["Take careful aim at the target.","They have a target to finish the project by November.","He made a good target."]);
