INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rent','vt.租，租赁n.租金','/ɹɛnt/','/ɹɛnt/','noun',["A New York city taxicab license earns more than $10,000 a year in rent.","I rented a house from my friend''s parents for a year.","We rented our house to our son''s friend for a year."]);
