INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('axe','n.斧','/æks/','/æks/','noun',["His girlfriend/boss/schoolmaster gave him the axe.","A financial dealer has an axe in a stock that his buyers don''t know about, giving him an advantage in making the most profit.","He got axed in the last round of firings."]);
