INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slice','n.薄片，切片A；一份，部分','/slaɪs/','/slaɪs/','noun',["Jim was munching on a slice of toast.","I bought a ham and cheese slice at the service station.","Slice the cheese thinly."]);
