INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('incline','v.倾斜，偏向；倾向于；赞同n.斜坡，斜面','','','noun',["To reach the building, we had to climb a steep incline.","He had to incline his body against the gusts to avoid being blown down in the storm.","Over the centuries the wind made the walls of the farmhouse incline."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cash','n.现金，现款vt.兑现，付现款','/kæʃ/','/kæʃ/','noun',["After you bounced those checks last time, they want to be paid in cash."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elevate','vt.抬起，升高','/ˈɛləveɪt/','/ˈɛləveɪt/','verb',["The doctor told me elevating my legs would help reduce the swelling.","The traditional worldview elevates man as the pinnacle of creation.","A talented chef can elevate everyday ingredients into gourmet delights."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('designate','vt.指明；指定','/ˈdɛzɪɡ.neɪt/','/ˈdɛzɪɡ.neɪt/','verb',["to designate the boundaries of a country"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humiliate','vt.使蒙羞，使丢脸','/hjuːˈmɪliˌeɪt/','/hjuːˈmɪliˌeɪt/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('canvas','n.帆布；油画布；油画','/ˈkæn.vəs/','/ˈkæn.vəs/','noun',["The author takes rural midwestern life as a canvas for a series of tightly woven character studies.","He spent the night under canvas."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('item','n.条，条款，项目','[ˈaɪ̯ɾm̩]','[ˈaɪ̯ɾm̩]','noun',["Tweezers are great for manipulating small items.","In response to the first item, we deny all wrongdoing.","The exam has 100 items, each of which includes a correct response and three distractors."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gene','n.基因A','/dʒiːn/','/dʒiːn/','noun',["A change in a gene is reflected in the protein or RNA molecule that it codes for."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violet','n.紫罗兰；紫罗兰色；紫色','/ˈvaɪlət/','/ˈvaɪlət/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hollow','vi.挖空，凿空adj.空的，中空的；空洞的，空虚的','/ˈhɒl.əʊ/','/hɑlɚ/','noun',["He built himself a cabin in a hollow high up in the Rockies.","the hollow of the hand or of a tree","a hollow in the pit of one''s stomach"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trunk','n.大衣箱，皮箱；行李箱；树干；躯干','/tɹʌŋk/','/tɹʌŋk/','noun',["the trunk of a vein or of an artery, as distinct from the branches"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('saving','adj.节约的n.储蓄；储蓄金，存款','/ˈseɪvɪŋ/','/ˈseɪvɪŋ/','verb',["The shift of the supplier gave us a saving of 10 percent.","I invested all my savings in gold.","a saving cook"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rely','vi.依赖，依靠；信赖，信任','/ɹɪˈlaɪ/','/ɹɪˈlaɪ/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slide','v.滑动，滑行，下滑n.滑动；降低；滑坡，滑道；幻灯片','/slaɪd/','/slaɪd/','noun',["The long, red slide was great fun for the kids.","The slide closed the highway.","a slide on the ice"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('style','n.风格；文体；式样，类型','/staɪl/','/staɪl/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excessive','adj.过多的，过分的','/ɪkˈsɛsɪv/','/ɪkˈsɛsɪv/','adjective',["Putting a wide vibrato on a single 16th triplet note at 160 beats per minute seems rather excessive."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flesh','n.肉','/flɛʃ/','/flɛʃ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jungle','n.丛林，密林；乱七八糟的一堆A<','/ˈdʒʌŋ.ɡ(ə)l/','/ˈdʒʌŋ.ɡ(ə)l/','noun',["It’s a jungle out there."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assault','n./','/əˈsɔːlt/','/əˈsɔːlt/','noun',["to make assault upon a man, a house, or a town","to make an assault on the prerogatives of a prince, or on the constitution of a government","Loud music assaulted our ears as we entered the building."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cherry','n.樱桃','/ˈt͡ʃɛɹi/','/ˈt͡ʃɛɹi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feminine','adj.女性的；娇柔的A','/ˈfɛmənɪn/','/ˈfɛmənɪn/','noun',["Mary, Elizabeth, and Edith are feminine names."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pattern','v.仿制，模仿n.图案，图样；式样','/ˈpat(ə)n/','/ˈpat(ə)n/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heighten','v.提高，升高；加强A','/ˈhaɪtən/','/ˈhaɪtən/','verb',["to heighten a flavor or a tint"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('harsh','adj.严厉的，刻薄的；粗糙的，毛糙的；严酷的，恶劣的；刺耳的；刺目的','/hɑːʃ/','/hɑːʃ/','verb',["Quit harshing me already, I said that I was sorry!","Dude, you''re harshing my buzz."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fireplace','n.壁炉','/ˈfaɪəpleɪs/','/ˈfaɪɹpleɪs/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vehicle','n.车辆，交通工具；媒介，载体','/ˈvɪː(ə).kəl/','/ˈvi.ə.kəl/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scrape','v.刮，擦去；擦过；勉强通过n.刮削，刮削声；擦伤，擦痕','/skɹeɪp/','/skɹeɪp/','noun',["He fell on the sidewalk and got a scrape on his knee.","He got in a scrape with the school bully.","I''m in a bit of a scrape — I''ve no money to buy my wife a birthday present."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bleak','adj.荒凉的；没有希望的，冷酷的','/bliːk/','/bliːk/','adjective',["A bleak and bare rock.","A bleak future is in store for you."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cushion','n.垫子，坐垫','/ˈkʊʃən/','/ˈkʊʃən/','noun',["to cushion a sofa","to cushion a blow"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glorious','adj.壮丽的，辉煌的；光荣的','/ˈɡlɔː.ɹi.əs/','/ˈɡlɔɹ.i.əs/','adjective',["glorious deeds"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plateau','n.高原','/ˈplætəʊ/','/plæˈtoʊ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('civilize','vt.使文明，教化','','','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('architecture','n.建筑；建筑学','/ˈɑː.kɪ.ˌtɛk.tʃə/','/ˈɑɹkɪtɛktʃɚ/','noun',["Architecture is the visual public expression of a culture’s achievements, values, and outlook. ― Max Roscoe, \"How Your City Is Killing You With Ugliness\"","The Intel architectures have more software written for them.","The architecture of the company''s billing system is designed to support its business goals."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stress','n.压力；重音；【物】应力；强调，重点，着重vt.强调，着重','/stɹɛs/','/stɹɛs/','noun',["Go easy on him, he''s been under a lot of stress lately.","Some people put the stress on the first syllable of “controversy”; others put it on the second.","“Emphasis” is stressed on the first syllable, but “emphatic” is stressed on the second."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mischief','n.损害，伤害，危害；恶作剧，捣蛋，胡闹','/ˈmɪstʃɪf/','/ˈmɪstʃɪf/','noun',["Drink led to mischief.","John''s mischief, tying his shoelaces together, irked George at first."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reliance','n.信赖，依靠','/ɹɪˈlaɪəns/','/ɹɪˈlaɪəns/','noun',["Your reliance on his expertise may be misplaced.","The industry is working to phase out its reliance on fossil fuels.","The boat was a poor reliance."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('display','vt.陈列，展览；显示n.陈列；展览；展示','/dɪsˈpleɪ/','/dɪsˈpleɪ/','noun',["The trapeze artist put on an amazing acrobatic display.","Pupils are expected to produce a wall display about a country of their choice."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('superfluous','adj.过剩的，多余的','/sjʊˈpɜːflu.əs/','/sjʊˈpɜːflu.əs/','adjective',["With a full rain suit, carrying an umbrella may be superfluous."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conductor','n.领队，指挥；售票员，列车员；导体，导线','/kənˈdʌktɚ/','/kənˈdʌktɚ/','noun',["train conductor; tram conductor"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bore','v.钻，挖，打眼，钻探；烦扰，使厌烦n.讨厌的人；麻烦事','/bɔː/','/bɔɹ/','noun',["the bore of a cannon","An insect bores into a tree.","to bore a steam cylinder or a gun barrel; to bore a hole"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acrobat','n.特技演员，杂技演员','/ˈæk.ɹə.bæt/','/ˈæk.ɹə.bæt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('disorder','n.混乱，杂乱；骚乱；【医】失调；疾病','/dɪsˈɔːdə(ɹ)/','/dɪsˈɔːɹdɚ/','noun',["After playing the children left the room in disorder.","The army tried to prevent disorder when claims the elections had been rigged grew stronger.","Bulimia is an eating disorder."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aggravate','vt.使恶化，加重，加剧<','/ˈæɡ.ɹə.veɪ̯t/','/ˈæɡ.ɹə.veɪ̯t/','verb',["He aggravated the story."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dairy','n.牛奶场；奶店<','/ˈdɛəɹi/','/ˈdɛəɹi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transistor','n.晶体管；晶体管收音机','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('giggle','n./','/ˈɡɪɡl/','/ˈɡɪɡl/','noun',["The women thought it would be quite a giggle to have a strippergram at the bride''s hen party.","The jokes had them giggling like little girls all evening."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('persevere','vi.坚持','','','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mature','adj.成熟的；熟的；成年人的Av.成熟','/məˈtjʊə/','/məˈtjʊə/','adjective',["She is quite mature for her age.","a mature plan","The headmaster decided to expel the boy after a mature consideration."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('navy','n.海军','/ˈneɪvi/','/ˈneɪvi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alleviate','vt.减轻，缓解；缓和','/əˈli.vi.eɪt/','/əˈli.vi.eɪt/','verb',["Alcohol is often a cheap tool to alleviate the stress of a hard day."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('influence','n.影响；作用；势力，权势vt.影响，感化','/ˈɪn.flu.əns/','/ˈɪn.flu.əns/','noun',["I have absolutely no influence over him.","I''m not able to exercise influence over him.","He has been a great influence on the voters during the elections."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('talent','n.才能，天资；人才','/ˈtalənt/','/ˈtælənt/','noun',["He has a real talent for drawing.","The director searched their talent pool to fill the new opening.","Not much talent in this bar tonight—let''s hit the clubs."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('percentage','n.百分数，百分率，百分比','/pəˈsɛntɪd͡ʒ/','/pɚˈsɛntɪd͡ʒ/','noun',["A high percentage of secondary school leavers take a gap year.","She gets a percentage for every vacuum cleaner sold.","There was no percentage in staying at home."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('negotiate','vi.谈判，交涉，商议','/nəˈɡəʊ.ʃi.eɪt/','/nəˈɡoʊ.ʃi.eɪt/','verb',["The client and server computers must first negotiate a network protocol to be used.","Although the car was quite rickety, he could negotiate the curves very well."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('violin','n.小提琴','/ˌvɑe.ɘˈlɘn/','/ˌvaɪəˈlɪn/','noun',["The first violin often plays the lead melody lines in a string quartet."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('package','n.包装，包裹，箱','/ˈpækɪdʒ/','/ˈpækɪdʒ/','noun',["Did you test the software package to ensure completeness?","For third and short, they''re going to bring in their jumbo package."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crisis','n.危机；紧要关头','/ˈkɹaɪsɪs/','/ˈkɹaɪsɪs/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('germ','n.微生物；细菌','/d͡ʒɜːm/','/d͡ʒɝm/','noun',["the germ of civil liberty"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shatter','vt.使…粉碎；使散开；使破灭；使震惊','/ˈʃæt.ə(ɹ)/','/ˈʃæt.ɚ/','noun',["to break a glass into shatters","The miners used dynamite to shatter rocks.","to be shattered in intellect; to have shattered hopes, or a shattered constitution"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glamour','n.魅力，诱惑力','/ˈɡlæmə/','/ˈɡlæmə/','noun',["glamour magazines; a glamour model","The idea or being a movie star has lost its glamour for me."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('persuasion','n.说服，说服力','/pəˈsweɪʒ(ə)n/','/pəˈsweɪʒ(ə)n/','noun',["It is his persuasion that abortion should never be condoned."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('moss','n.苔藓，地衣','/mɑs/','/mɔs/','noun',["Irish moss","the mosses of the Scottish border","An oak whose boughs were mossed with age."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glimpse','n./','/ɡlɪmps/','/ɡlɪmps/','noun',["I only got a glimpse of the car, so I can tell you the colour but not the registration number.","I have only begun to glimpse the magnitude of the problem."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('detective','n.侦探','/dɪˈtɛktɪv/','/dɪˈtɛktɪv/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transfer','vi.换车；转业，转学；调动，转职vt.转移；转让，过户<n.转变','/tɹænzˈfɜː/','/ˈtɹænsfɝ/','noun',["to transfer the laws of one country to another; to transfer suspicion","to transfer drawings or engravings to a lithographic stone","The title to land is transferred by deed."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('footstep','n.脚步；足迹','/ˈfʊtstɛp/','/ˈfʊtstɛp/','noun',["The child watched as his footsteps in the sand were washed away by the waves.","To walk the footsteps of greatness requires that you start at the bottom of a long stair.","The footsteps of the students echoed in the empty hall."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('veteran','adj.经验丰富的n.老手；老兵','[ˈvɛ.t̬ə.ɹən]','[ˈvɛ.t̬ə.ɹən]','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('phrase','n.短语，词语，习语','/fɹeɪz/','/fɹeɪz/','noun',["I wasn''t sure how to phrase my condolences without sounding patronising."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affection','n.爱，慈爱；感情；影响','/əˈfɛkʃən/','/əˈfɛkʃən/','noun',["I have a lot of affection for my little sister."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nerve','n.神经；勇气，胆量','/nɛɾv/','/nɜɪv/','noun',["The nerves can be seen through the skin.","Some plants have ornamental value because of their contrasting nerves.","He hasn''t the nerve to tell her he likes her. What a wimp!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diversion','n.转向，转移A','/daɪˈvɜːʃən/','/daɪˈvɝʒən/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('omit','vt.省略，删去；遗漏，忽略<','/oʊˈmɪt/','/oʊˈmɪt/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('centimeter','n.厘米','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('erroneous','adj.错误的，不正确的','/ɛɹˈəʊ.nɪ.əs/','/ɛɹˈəʊ.nɪ.əs/','adjective',["His answer to the sum was erroneous.","His conclusion was erroneous, since it was based on a false assumption.","Her choice at the line-up proved to be erroneous, as she had only seen the mugger for an instant."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sponsor','n.发起人；主办者；保证人vt.发起，主办','/ˈspɒn.sə/','/ˈspɒn.sə/','noun',["He was my sponsor when I applied to join the club.","And now a word from our sponsor."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('limitation','n.限制，局限性','/lɪmɪˈteɪʃən/','/lɪmɪˈteɪʃən/','noun',["Getting into his wheelchair after his amputation, it felt like a limitation you could roll in.","The lawyer obtained impunity by dragging his obviously guilty client''s case beyond the ten-year limitation."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('terrify','vt.使害怕，使惊恐','/ˈtɛɹɪfaɪ/','/ˈtɛɹɪfaɪ/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jog','n.慢跑A','/dʒɒɡ/','/dʒɑɡ/','noun',["jog one''s elbow","I tried desperately to jog my memory.","to jog a horse"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ascertain','vt.查明，弄清，确定','/ˌæsəˈteɪn/','/ˌæsɚˈteɪn/','verb',["As soon as we ascertain what the situation is, we can plan how to proceed."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trolly','n.手推车，小车；〈英〉无轨电车；〈美〉有轨电车','','','',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insert','vt.插入，嵌入','/ɪnˈsɜːt/','/ɪnˈsɜːt/','noun',["This software can print compact disc inserts if you have the right size of paper.","a threaded insert","In order to withdraw money from a cash machine, you have to insert your debit card."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('forbid','vt.禁止，不许','/fəˈbɪd/','/fɚˈbɪd/','verb',["Smoking in the restaurant is forbidden.","An impassable river forbids the approach of the army.","What part of \"no\" do you forbid to understand?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inspiration','n.灵感；鼓舞，激励','/ɪnspɨˈɹeɪʃən/','/ɪnspɨˈɹeɪʃən/','noun',["She was waiting for inspiration to write a book.","The trip was an inspiration to her for writing a book."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('highlight','vt.使显著，使突出；强调n.最精彩的部分；最重要的事件','/ˈhaɪ.ˌlaɪt/','/ˈhaɪ.ˌlaɪt/','noun',["Meeting my future wife was the highlight of my trip to Spain."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('database','n.数据库','/ˈdeɪtəˌbeɪs/','/ˈdeɪtəˌbeɪs/','noun',["I have a database of all my contacts in my personal organizer.","The \"books\" database will have three tables, and the \"customers\" database will have two tables.","Which database do you use: MySQL or Oracle?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reject','vt.拒绝；抵制；驳回；丢弃；排斥；退掉','','','noun',["She even rejected my improved offer.","I''ve been rejected three times this week."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sheer','adj.纯粹的；十足的，全然的；陡峭的，险峻的','/ˈʃɪə/','/ʃɪɹ/','noun',["Use sheers to maximize natural light.","Her light, sheer dress caught everyone’s attention.","I think it is sheer genius to invent such a thing."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miracle','n.奇迹，令人惊奇的人','/ˈmiɹəkəl/','/ˈmiɹəkəl/','noun',["An example of a miracle associated with Muhammad is the splitting of the moon."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compliment','n.称赞；恭维vt.称赞，恭维','/ˈkɒmplɪmənt/','/ˈkɑmpləmənt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('imitation','n.模仿，仿效；仿制；仿造品','/ɪmɪˈteɪʃən/','/ɪmɪˈteɪʃən/','noun',["imitation leather"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('profit','v.得利，获益；利用；有利于n.利润，收益；益处','/ˈpɹɒfɪt/','/ˈpɹɑfɪt/','noun',["Reading such an enlightening book on the subject was of much profit to his studies."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amount','vi.合计，总共达；等于n.数量，总额','/əˈmaʊnt/','/əˈmaʊnt/','noun',["The amount of atmospheric pollution threatens a health crisis.","Pour a small amount of water into the dish.","It amounts to three dollars and change."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comply','vi.照做，遵照，应允','/kəmˈplaɪ/','/kəmˈplaɪ/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('original','adj.最初的，原始的；原文的<；新颖的，有独创性的n.原物；原作；原文','/əˈɹɪdʒnəl/','/əˈɹɪdʒnəl/','noun',["This manuscript is the original.","You’re a real original.","the original state of mankind;  the original laws of a country;  the original inventor of a process"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('nylon','n.尼龙','/ˈnaɪlɒn/','/ˈnaɪlɒn/','noun',["I tore a hole in my nylons while walking home through the woods."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deviate','vi.背离，偏离','/ˈdiːvi.ət/','/ˈdiːvi.ət/','noun',["His exhibition of nude paintings deviated from the norm."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('album','n.粘贴簿；集邮簿；相册','/ˈælbəm/','/ˈælbəm/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assignment','n.分配，委派；任务；作业','','','noun',["This flow chart represents the assignment of tasks in our committee.","We should not condone the assignment of asylum seekers to that of people smugglers.","The assignment the department gave him proved to be quite challenging."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('yawn','vi.打呵欠n.呵欠','/jɔːn/','/jɔːn/','noun',["The slideshow we sat through was such a yawn. I was glad when it finished.","I could see my students yawning, so I knew the lesson was boring them.","Death yawned before us, and I hit the brakes."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('saw','v.锯，锯开n.锯子；锯床','/sɔː/','/sɔ/','noun',["They were stoned, they were sawn asunder, were tempted, were slain with the sword: they wandered about in sheepskins and goatskins; being destitute, afflicted, tormented;","The fiddler sawed away at his instrument.","The timber saws smoothly."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feudal','adj.封建的','[ˈfju.ɾɫ̩]','[ˈfju.ɾɫ̩]','adjective',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kingdom','n.王国；领域','/ˈkɪŋdəm/','/ˈkɪŋdəm/','noun',["the kingdom of the dead"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('differ','vi.与…不同；与…意见不同','/ˈdɪfə/','/ˈdɪfɚ/','verb',["These shoes only differ from those ones in having slightly longer laces.","The numbers 3 and 21 differ by 18."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('puppet','n.木偶；傀儡','/ˈpʌpɪt/','/ˈpʌpɪt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('latter','pron.后者adj.后面的；末尾的','/ˈlæt̬.əɹ/','/ˈlæt̬.əɹ/','adjective',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affiliate','v.隶属于n.附属机构，分公司','/əˈfɪl.i.et/','/əˈfɪl.i.et/','noun',["Our local TV channel is an affiliate of NBC.","to affiliate the child to (or on or upon) one man rather than another"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('equivalent','adj.相等的，等价的，等值的<n.相等物，等价物，等值物；对应词','/ɪˈkwɪvələnt/','/ɪˈkwɪvələnt/','noun',["To burn calories, a thirty-minute jog is equivalent to a couple of hamburgers.","A square may be equivalent to a triangle."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('canoe','n.独木舟，小游艇','/kəˈnuː/','/kəˈnuː/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wedge','n.楔，楔形vt.楔牢，楔入；挤进','/wɛdʒ/','/wɛdʒ/','noun',["Stick a wedge under the door, will you? It keeps blowing shut.","Can you cut me a wedge of cheese?","I made a big fat wedge from that job."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alienate','vt.使疏远，使格格不入；使不友好；离间A','/ˈeɪ.li.ə.neɪt/','/ˈeɪ.li.ə.neɪt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plague','n.瘟疫；祸患，灾害','/pleɪɡ/','/pleɪɡ/','noun',["Ten Biblical plagues over Egypt, ranging from locusts to the death of the crown prince, finally forced Pharaoh to let Moses''s people go.","Bart is an utter plague; his pranks never cease.","Natural catastrophes plagued the colonists till they abandoned the pestilent marshland."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('perpetual','adj.永久的，永恒的；长期的A','/pəˈpɛtjʊəl/','/pɚˈpɛtʃuəl/','adjective',["By means of artificial hybridization, practised for a series of years, he has succeeded in producing a race of carnations which are perpetual bloomers."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retrospect','n.回顾，回想','/ˈɹɛtɹoˌspɛkt/','/ˈɹɛtɹoˌspɛkt/','noun',["1800: Alexander Hamilton, Letter from Alexander Hamilton, Concerning the Public Conduct and Character of John Adams, Esq. President of the United States - To give a correct idea of the circumstances.., it may be useful to retrospect to an early period."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ban','vt.取缔，查禁；禁止n.禁止，禁令','/bæn/','/bæn/','noun',["Bans is common and ordinary amongst the Feudists, and signifies a proclamation, or any public notice.","France was at such a Pinch..that they call''d their Ban and Arriere Ban, the assembling whereof had been long discussed, and in a manner antiquated.","Bare feet are banned in this establishment."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fascinate','vt.迷住，强烈吸引','/ˈfæsɪneɪt/','/ˈfæsɪneɪt/','verb',["The flickering TV fascinated the cat.","We were fascinated by the potter''s skill.","Her gait fascinates all men."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diplomatic','adj.外交的，从事外交的；有策略的，有手腕的','/ˌdɪpləˈmætɪk/','/ˌdɪpləˈmætɪk/','noun',["Albania immediately severed diplomatic relations with Zimbabwe.","Thoughtful corrections can be diplomatic as well as instructional.","Whereas a diplomatic edition uses as its base text a single, \"best\" manuscript, to which other textual evidence is collated and organized into an apparatus, a critical text of the LXX/OG may be described as a collection of the oldest recoverable texts, carefully restored book by book (or section by section), aiming at achieving the closest approximation to the original translations (from Hebrew or Aramaic) or compositions (in Greek), systematically reconstructed from the widest array of relevant textual data (including controlled conjecture).  The International Organization for Septuagint and Cognate Studies, Critical Editions of Septuagint/Old Greek Texts."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suffer','vi.受痛苦；患病vt.遭受；忍受，忍耐<','/ˈsʌfə/','/ˈsʌfɚ/','verb',["Is anyone here afraid of suffering hardship?","At least he didn''t suffer when he died in the car crash.","If you keep partying like this, your school-work will suffer."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bar','n.条，杆，棒，棍，闩；酒吧；吧台；栅，栏，障碍vt.闩上；阻拦，拦住；妨碍','/bɑː/','/bɑɹ/','noun',["The window was protected by steel bars.","Ancient Sparta used iron bars instead of handy coins in more valuable alloy, to physically discourage the use of money.","bar of chocolate"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bat','n.球拍，球棒；短棒；蝙蝠','/bæt/','/bæt/','noun',[]);
