INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('neighbourhood','n.邻居；四邻；街道，住宅区','','','noun',["Our neighborhood was our only reason to exchange hollow greetings.","He lives in my neighborhood.","The fire alarmed the neighborhood."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('draft','n.草稿，草案，草图vt.起草，草拟','/dɹæft/','/dɹæft/','noun',["She took a deep draft from the bottle of water.","His first drafts were better than most authors'' final products.","He left the country to avoid the draft."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complex','adj.复杂的；合成的，综合的n.综合体','','','noun',["Jim has a real complex about working for a woman boss."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('humidity','n.湿气；湿度','/hjuːˈmɪdɪti/','/hjuːˈmɪdɪti/','noun',[]);
