INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('abuse','vt.滥用；虐待；谩骂n.滥用；虐待','/əˈbjuːs/','/əˈbjus/','noun',["All abuse, whether physical, verbal, psychological or sexual, is bad."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('insulate','v.隔离，孤立；使绝缘，使绝热','','','verb',["Ceramic can be used to insulate power lines."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scheme','v.计划，策划；阴谋n.计划，方案；阴谋；配置；安排','/skiːm/','/skiːm/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('affect','vt.影响；感动，感染','/əˈfɛkt/','/əˈfɛkt/','verb',["The experience affected me deeply.","He was deeply affected by the tragic ending of the play.","Hepatitis affects the liver."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deaf','adj.聋的；不愿听的','/diːf/','/diːf/','noun',["Those people are deaf to reason.","a deaf nut; deaf corn"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drain','v.排去，放干n.排水沟，阴沟；流出；消耗','/dɹeɪn/','/dɹeɪn/','noun',["The drain in the kitchen sink is clogged.","That rental property is a drain on our finances.","The clogged sink drained slowly."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amuse','vt.逗…笑；给…以娱乐','/əˈmjuːz/','/əˈmjuːz/','verb',["I watch these movies because they amuse me.","His jokes rarely fail to amuse."]);
