INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inward','adv.向内，在内adj.在内的，里面的；内心的<','/ˈɪnwəd/','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('responsibility','n.责任，责任心；职责，任务','/ɹɪˌspɑnsəˈbɪlɪɾi/','/ɹɪˌspɑnsəˈbɪlɪɾi/','noun',["Responsibility is a heavy burden.","Why didn''t you clean the house? That was your responsibility!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enquire','v.询问；打听；问好，问候','/ɪŋˈkwaɪə/','/ɪŋˈkwaɪə/','verb',["He enquired about the availability of rental bicycles in the town."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('civil','adj.公民的，市民的；国内的，民间的；民用的；有礼貌的，文明的','/ˈsɪv.əl/','/ˈsɪv.əl/','adjective',["She went into civil service because she wanted to help the people.","It was very civil of him to stop the argument.","a civil case"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subsequent','adj.随后的，后来的A','/ˈsʌbsəkwənt/','/ˈsʌbsəkwənt/','adjective',["Growth was dampened by a softening of the global economy in 2001, but picked up in the subsequent years due to strong growth in China."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('indicate','vt.指出；指示A；表明或暗示…的可能性A','/ˈɪndɪkeɪt/','/ˈɪndɪkeɪt/','verb',["The guard blew his whistle to indicate imminent departure.","Great prostration of strength indicates the use of stimulants."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contain','v.包含；容纳，装有；等于，相当于A','/kənˈteɪn/','/kənˈteɪn/','verb',["I''m so excited, I can hardly contain myself!","A group contains a unique inverse for each of its elements."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('litter','v.产n.垃圾；一窝vt.乱扔','/ˈlɪtə(ɹ)/','/ˈlɪtɚ/','noun',["sleep in the litter","drop litter","the cat''s litter"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sew','vi.缝，缝纫','/səʊ/','/soʊ/','verb',["Balls were first made of grass or leaves held together by strings, and later of pieces of animal skin sewn together and stuffed with feathers or hay.","to sew money into a bag"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oval','adj.椭圆形的n.椭圆形','/ˈəʊvəl/','/ˈəʊvəl/','noun',["oval conceptions"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('column','n.圆柱，柱状物；列；专栏','/ˈkɑljəm/','/ˈkɑljəm/','noun',["It was too hard to read the text across the whole page, so I split it into two columns.","Each column inch costs $300 a week; this ad is four columns by three inches, so will run $3600 a week.","His initial foray into print media was as the author of a weekly column in his elementary-school newspaper."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('biography','n.传记','/baɪˈɒɡɹəfi/','/baɪˈɑːɡɹəfi/','noun',["There are many biographies of Benjamin Franklin."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('procedure','n.程序，手续，步骤','/pɹəˈsiːdʒə/','/pɹəˈsidʒɚ/','noun',["Ensure that you follow procedure when accessing customers'' personal information."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sample','n.样品，标本vt.抽样试验；抽样调查','/sæːm.pəl/','/sæːm.pəl/','noun',["a blood sample"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('integrate','v.成为一体，结合在一起，合并<','/ˈɪntəɡɹeɪt/','/ˈɪntəɡɹeɪt/','verb',["They were keen to integrate their new skills into the performance.","The refugees were well integrated into the community."]);
