INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('petition','n.请愿书，申请书A<；诉状vt.请愿，正式请求','/pəˈtɪ.ʃən/','/pəˈtɪ.ʃən/','noun',["The villagers petitioned the council to demolish the dangerous building."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('somewhat','adv.稍微，有点','/ˈsʌmwɒt/','/ˈsʌmwʌt/','noun',["The crowd was somewhat larger than expected, perhaps due to the good weather."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vicinity','n.邻近，附近','/vəˈsɪnəti/','/vəˈsɪnəti/','noun',["There was a crackling sound in the vicinity of my right ear.","There is a hurricane in the vicinity of the Bahamas.","I weigh in the vicinity of 80kg."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('earnest','adj.热心的；诚挚的','/ˈɜːnɪst/','/ˈɝnɪst/','noun',["earnest prayers","earnest attention.","an earnest disposition"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('jug','n.大罐，壶；一大罐的容量vt.关押','/d͡ʒʌɡ/','/d͡ʒʌɡ/','noun',["jugged hare"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spider','n.蜘蛛','[ˈspʌɪ̯ɾə(ɹ)]','/ˈspaɪ̯dɚ/','noun',["2002, Katharine Gasparini, Cranberry and vanilla ice cream spider, recipe in Cool Food, page 339.","The online dictionary is regularly spidered by search engines."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('precede','v.领先，在…之前；优先，先于A','/pɹiːˈsiːd/','/pɹiːˈsiːd/','noun',["Cultural genocide precedes physical genocide."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deck','n.甲板','/dɛk/','/dɛk/','noun',["to swab the deck","We hit the deck as bullets began to fly.","Wow, did you see her deck that guy who pinched her?"]);
