INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('differentiate','vi.区分，区别vt.不同','/dɪf.əˈɹɛn.ʃi.eɪt/','/ˌdɪ.fəˈɹɛnt.ʃi.eɪt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contact','vt.接触，联系，交往n.接触，联系，交往','','','noun',["I haven''t been in contact with her for years.","Touch the contact to ground and read the number again.","The salesperson had a whole binder full of contacts for potential clients."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discharge','vi.发射；排出，流出；放vt.卸货；释放；遣散，解雇；解除<','','','noun',["to discharge a prisoner","to discharge a cargo","A pipe discharges water."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prospective','adj.未来的，预期的；可能的','/pɹəˈspɛktɪv/','/pɹəˈspɛktɪv/','noun',["I''m meeting the prospectives at 3.","Prospective students are those who have already applied to the university, but have yet to be admitted.","What some other languages convey with prospective aspect, English conveys with expressions like going to drive the car home."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plaster','n.灰泥；熟石膏；膏药<','/ˈplastə/','/ˈplæstɚ/','noun',["to plaster a wall","to plaster a wound","Her face was plastered with mud."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('grown-up','adj.成长的；成熟的；成人的n.成年人','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('metropolitan','adj.首都的；大都市的','/mɛtɹəˈpɒlɪtən/','/mɛtɹəˈpɒlɪtən/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('garbage','n.垃圾','/ˈɡɑːbɪd͡ʒ/','/ɡɑ(ɹ)ˈbɑːʒ/','noun',["Garbage is collected on Tuesdays; rubbish on Fridays","The garbage truck collects all residential municipal waste.","He threw the newspaper into the garbage."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('suspicious','adj.可疑的；多疑的，疑心的','/səˈspɪ.ʃəs/','/səˈspɪ.ʃəs/','adjective',["His suspicious behaviour brought him to the attention of the police.","I have a suspicious attitude to get-rich-quick schemes.","She gave me a suspicious look."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('complain','v.抱怨；申诉','/kəmˈpleɪn/','/kəmˈpleɪn/','verb',["Joe was always complaining about the noise made by his neighbours.","They''ve complained about me to the police again.","the complaining bed-springs"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zeal','n.热情，热忱','/ziːl/','/zil/','noun',["She extols the virtues of veganism with missionary zeal."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('anxiety','n.挂念；焦虑，忧虑A；渴望，热望','/ˌæŋ(ɡ)ˈzaɪ.ə.ti/','/ˌæŋ(ɡ)ˈzaɪ.ə.ti/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('renovate','vt.更新，修复','/ˈɹenəʊveɪt/','/ˈɹenəʊveɪt/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adjust','vi.调整，适应vt.调节，调整<；校正，校准<','/əˈdʒʌst/','/əˈdʒʌst/','verb',["Morimoto''s recipes are adjusted to suit the American palate.","He adjusted his initial conclusion to reflect the new data.","Most immigrants adjust quickly to a new community.   She waited for her eyes to adjust to the darkness."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vigorous','adj.有力的；朝气蓬勃的，精力旺盛的','/ˈvɪɡəɹəs/','/ˈvɪɡəɹəs/','adjective',["a vigorous shrub"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('debt','n.债，债务','/dɛt/','/dɛt/','noun',["I am in your debt."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deem','vt.认为，相信','/diːm/','/diːm/','noun',["She deemed his efforts insufficient."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compel','vt.强迫，迫使','/kəmˈpɛl/','/kəmˈpɛl/','verb',["Logic compels the wise, while fools feel compelled by emotions."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('capable','adj.有能力的，能…的','/ˈkeɪpəbl̩/','/ˈkeɪpəbl̩/','adjective',["As everyone knew, he was capable of violence when roused."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('depress','vt.压抑；降低；削弱；使沮丧，使抑郁','/dɪˈpɹɛs/','/dɪˈpɹɛs/','verb',["Depress the upper lever to start the machine.","Winter depresses me.","Lower productivity will eventually depress wages."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('parade','vi.列队行进，游行n.游行；检阅','/pəˈɹeɪd/','/pəˈɹeɪd/','noun',["The floats and horses in the parade were impressive, but the marching bands were really amazing.","The dinner was a parade of courses, each featuring foods more elaborate than the last.","He was parked on Chester Parade."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('riddle','n.谜，谜语','/ˈɹɪdəl/','/ˈɹɪdəl/','noun',["Here''s a riddle: It''s black, and white, and red all over. What is it?","Riddle me this."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('salute','v.敬礼；向…致敬；问候n.敬礼；鸣礼炮；迎接，欢迎','/səˈl(j)uːt/','/səˈlut/','noun',["The soldiers greeted the dignitaries with a crisp salute.","They saluted the flag as it passed in the parade.","I would like to salute the many dedicated volunteers that make this project possible."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symposium','n.讨论会，专题报告会；专题论文集','/sɪm.ˈpoʊ.zi.əm/','/sɪm.ˈpoʊ.zi.əm/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lemon','n.柠檬','/ˈlɛmən/','/ˈlɛmən/','noun',["He didn’t realise until he’d paid for it that the car was a lemon.","A thousand quid for that motor? Do me a lemon, I could get it for half that.","You can start the vegetables cooking while you are lemoning the fish."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('await','vt.等候；期待','/əˈwɛɪt/','','noun',["I await your reply to my letter.","Glorious rewards await the good in heaven; eternal suffering awaits mortal sinners in hell."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('client','n.顾客；委托人，当事人','/ˈklʌɪənt/','/ˈklaɪ.ənt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sin','vi.犯罪n.罪，罪恶','/sɪn/','/sɪn/','noun',["As a Christian, I think this is a sin against God.","No movie is without sin."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sip','v.啜饮，抿，呷An.小口喝，一小口的量','/sɪp/','/sɪp/','verb',["The water steadily seeped in through the thirl.","Fear began to seep into the local community over the contamination of their fishpond.","The resistance movement against the invaders had slowly  seeped away."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lump','vi.结块，起小疙瘩n.团，块vt.把…归并在一起','/lʌmp/','/lʌmp/','noun',["Stir the gravy until there are no more lumps.","The money arrived all at once as one big lump sum payment.","Do you want one lump or two with your coffee?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conversion','n.变换，转化','/-ʒ(ə)n/','/kənˈvɝʒən/','noun',["His conversion to Christianity","the conversion of a horse","the conversion of equations; the conversion of proportions"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ballot','v.投票选举，无记名投票n.投票表决；无记名投票；选票','/ˈbalət/','/ˈbalət/','noun',["to ballot for a candidate"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brilliant','adj.光辉的，灿烂的；卓越的，有才华的','/ˈbɹɪljənt/','/ˈbɹɪljənt/','noun',["the brilliant lights along the promenade","butterflies with brilliant blue wings","The actor''s performance in the play was simply brilliant."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('historic','adj.有历史意义的；历史的','/(h)ɪˈstɒɹɪk/','/(h)ɪˈstɔːɹɪk/','noun',["A historic opportunity","The historic tenses include the imperfect, the pluperfect, and the future perfect.","July 4, 1776, is a historic date. A great deal of historical research has been done on the events leading up to that day."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('oven','n.炉，灶，烤箱','/ˈʌ.vn̩/','/ˈʌ.vn̩/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eyebrow','n.眉毛','/ˈaɪˌbɹaʊ/','/ˈaɪˌbɹaʊ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bound','vi.跳adj.受约束的；有义务的；注定的，肯定的；准备到…去的，开往…的n.跳','/ˈbaʊnd/','/ˈbaʊnd/','verb',["Just to make the cheese more binding","I wish I knew why the sewing machine binds up after I use it for a while.","These are the ties that bind."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('wreath','n.花环，花圈','/ɹiːθ/','/ɹiːθ/','noun',["a wreath of smoke;  a wreath of clouds","At the funeral, a circle of comrades wreathed the grave of the honored deceased."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stroke','n.击，敲；报时的钟声A；一击，一划，一笔；一次努力；中风vt.抚摸A','/stɹəʊk/','/stɹoʊk/','noun',["She gave the cat a stroke.","a stroke on the chin","the stroke of a bird''s wing in flying, or of an oar in rowing"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('breed','vi.繁殖，生殖vt.造成，引起；教养，抚养；饲养n.品种，种类A','/bɹiːd/','/bɹiːd/','noun',["a breed of animal","People who were taught classical Greek and Latin at school are a dying breed.","a pond breeds fish; a northern country breeds stout men"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pyramid','n.金字塔','/ˈpɪɹəmɪd/','/ˈpɪɹəmɪd/','noun',["Build your pyramid with all cards face down, except the cards in the bottom row."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('realm','n.王国，国土；领域','/ɹɛlm/','/ɹɛlm/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('avoid','vt.避免；回避，逃避A','/əˈvɔɪd/','/əˈvɔɪd/','verb',["I try to avoid the company of gamblers."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bid','vi.报价，投标vt.祝愿；命令，吩咐n.出价，投标','/bɪd/','/bɪd/','verb',["He bade me come in.","She was bidden to the wedding.","Have you ever bid in an auction?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astonish','vt.使惊讶，使吃惊','/əˈstɒnɪʃ/','/əˈstɑnɪʃ/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prompt','adj.敏捷的；迅速的；即刻的vt.激起；促进，推动','/pɹɒmpt/','/pɹɒmpt/','noun',["I filled in my name where the prompt appeared on the computer screen but my account wasn''t recognized.","I prompted him to get a new job.","If he forgets his words I will prompt him."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comprehensive','adj.全面的，综合的','/ˌkɒm.pɹɪˈhɛn.sɪv/','/ˌkɑːm.pɹəˈhɛn.sɪv/','noun',["When there are diametrically opposing views on a big issue that concerns millions of people, doing comprehensive research just makes sense."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tunnel','n.隧道；山洞','/ˈtʌn(ə)l/','/ˈtʌn(ə)l/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elaborate','vi.详细说明adj.精心制作的；详尽的；复杂的vt.详细制定','/ɪˈlæbəɹeɪt/','/ɪˈlæbəɹeɪt/','verb',["Could you elaborate on the plot for your novel for me?","After reading a long, elaborate description, I was impressed but no wiser.","I stared for hours at the elaborate pattern in the rug."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corridor','n.走廊；狭长通道','/ˈkɒɹɪˌdɔː(ɹ)/','/ˈkɔɹəˌdɔɹ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expert','adj.熟练的，有经验的；专门的n.专家，能手<','/ˈɛkspəːt/','/ˈɛkspɚt/','noun',["We called in several experts on the subject, but they couldn''t reach an agreement.","I am expert at making a simple situation complex.","This problem requires expert knowledge."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('select','adj.精选的，选择的A<vt.选择，挑选','/sɪˈlɛkt/','/sɪˈlɛkt/','verb',["He looked over the menu, and selected the roast beef.","Only a select few were allowed into the premiere.","This is a select cut of beef."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fulfill','vt.完成；实现，履行；符合','/fəˈfɪl/','/fəˈfɪl/','verb',["You made a promise, son, and now you must fulfill it.","This is the most fulfilling work I''ve ever done.","Unfortunately, you don''t fulfill the criteria for extra grants at the present time."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advanced','adj.高级的，先进的；前进的<','/ədˈvɑːnst/','/ədˈvænst/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bin','n.大箱子','/bɪn/','/bin/','noun',["a corn bin; a wine bin; a coal bin","a rubbish bin; a wastepaper bin; an ashes bin","to bin wine"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mechanical','adj.机械的；机械制的；机械的；呆板的','/mɪˈkanɪk(ə)l/','/mɪˈkanɪk(ə)l/','noun',["mechanical engineering","mechanical dictionary","mechanical task"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slaughter','vt.屠杀，杀戮，屠宰n.屠杀，杀戮；屠宰','/ˈslɔːtə/','/ˈslɔːtə/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ski','vi.滑雪n.雪橇','/ʃiː/','/ʃiː/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('output','n.产量，输出','/ˈaʊtpʊt/','/ˈaʊtpʊt/','noun',["The factory increased its output this year.","a six-page output; six pages of output","We output 1400 units last year."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('maiden','adj.首次的，初次的n.少女，未婚女子','/ˈmeɪdən/','/ˈmeɪdən/','noun',["She''s unmarried and still a maiden.","After Edmund Burke''s maiden speech, William Pitt the Elder said Burke had \"spoken in such a manner as to stop the mouths of all Europe\" and that the Commons should congratulate itself on acquiring such a member."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fatigue','n.疲劳','/fəˈtiːɡ/','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('striking','adj.显著的，惊人的','/ˈstɹaɪkɪŋ/','/ˈstɹaɪkɪŋ/','verb',["Please strike the last sentence.","A tree strikes its roots deep.","They struck off along the river."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recognise','vt.认出，识别；承认','/ˈɹɛkənaɪz/','/ˈɹɛkənaɪz/','verb',["I recognised his face immediately.","The US and a number of EU countries are expected to recognize Kosovo on Monday.","I recognize that my behaviour has been unacceptable."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('majority','n.多数，大多数；【律】成年','/məˈd͡ʒɒɹɪti/','/məˈd͡ʒɑɹɪti/','noun',["The majority agreed that the new proposal was the best.","The winner with 53% had a 6% majority over the loser with 47%.","By the time I reached my majority, I had already been around the world twice."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('costume','n.戏装；成套服装；服饰','/ˈkɒs.tjuːm/','','noun',["The dancer was wearing Highland costume.","We wore gorilla costumes to the party.","The bride wore a grey going-away costume."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('crown','n.王冠，冕；君权；君王vt.为…加冕','/kɹaʊn/','/kɹaʊn/','noun',["the martyr''s crown","Treasure recovered from shipwrecks automatically becomes property of the Crown.","The mother was in the second stage of labor and the fetus had just crowned, prompting a round of encouragement from the midwives."]);
