INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cycle','vi.骑自行车；循环，轮转n.自行车；周期；循环','/ˈsaɪkəl/','/ˈsaɪkəl/','noun',["the cycle of the seasons, or of the year","electoral cycle","The interval cycle C4 consists of the pitch classes 0, 4 and 8; when starting on E, it is realised as the pitches E, G# and C."]);
