INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dissolve','vi.解散；取消vt.使溶解，使融化','/dɪˈzɒlv/','/dɪˈzɒlv/','noun',["The ruling party or coalition sometimes dissolves parliament early when the polls are favorable, hoping to reconvene with a larger majority.","to dissolve an injunction"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prejudice','v.使抱偏见；影响；损害n.偏见，成见；损害，侵害','/ˈpɹɛd͡ʒədɪs/','/ˈpɹɛd͡ʒədɪs/','noun',["I am free of all prejudices. I hate everyone equally."]);
