INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clergy','n.牧师，圣职者，神职人员','/ˈklɜːdʒi/','/ˈklɝdʒi/','noun',["Today we brought together clergy from the Wiccan, Christian, New Age and Islamic traditions for an interfaith dialogue."]);
