INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scramble','vi.攀登，爬；争夺，抢夺vt.扰乱，搞乱n.攀登，爬行；争夺，抢夺','/ˈskɹæmbl̩/','/ˈskɹæmbl̩/','noun',["a last-minute scramble to the finish line","I scrambled some eggs with spinach and cheese.","to scramble up wealth"]);
