INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tense','adj.拉紧的；紧张的n.时态','/tɛns/','/tɛns/','noun',["English only has a present tense and a past tense; it has no future tense.","Dyirbal verbs are not inflected for tense.","tensing a verb"]);
