INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('clockwise','adj.顺时针方向的','/ˈklɒkwaɪz/','/ˈklɒkwaɪz/','adjective',["In the southern hemisphere the flow of air around a low-pressure system is clockwise."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lobby','n.门廊，门厅；休息厅','/lɒbi/','/lɒbi/','noun',["I had to wait in the lobby for hours before seeing the doctor.","The influence of the tobacco lobby has decreased considerably in the US.","For years, pro-life groups have continued to lobby hard for restrictions on abortion."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('acknowledge','vt.承认；致谢，报偿','/əkˈnɒ.lɪdʒ/','/ækˈnɑː.lɪdʒ/','verb',["to acknowledge the being of a god","to acknowledge a favor","This is to acknowledge your kind invitation to participate in the upcoming debate."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('pulse','n.脉搏，脉冲；意向，动向；情绪','/pʊls/','/pʌls/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overthrow','vt.推翻，颠覆n.推翻，颠覆','/əʊvəˈθɹəʊ/','/ˈoʊvɚˌθɹoʊ/','noun',["I hate the current government, but not enough to want to overthrow them."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('heroine','n.女英雄；女主角','/ˈhɛɹoʊɪn/','/ˈhɛɹoʊɪn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inland','adv.在国内；在内地，在内陆adj.国内的；内地的，内陆的','/ˈɪnlənd/','/ˈɪnlənd/','noun',["an inland town","inland commerce"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('worthwhile','adj.值得的A','/wɜː(ɹ)θˈwaɪl/','/wɜː(ɹ)θˈwaɪl/','adjective',["Doing volunteer work to help others is truly worthwhile."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mould','n.模子，铸型vt.浇铸，造型；塑造，形成','/məʊld/','/moʊld/','noun',["the oval mold of her face","a leader in the mold of her predecessors","His method of scientific investigation broke the mold and led to a new discovery."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stumble','vi.跌，绊；结结巴巴地说话n.跌，绊','/ˈstʌmbəl/','/ˈstʌmbəl/','noun',["He stumbled over a rock.","I always stumble over verbs in Spanish."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cunning','adj.狡猾的，狡诈的；精巧的，巧妙的n.狡猾，狡诈','/ˈkʌnɪŋ/','/ˈkʌnɪŋ/','adjective',["cunning work","a cunning little boy"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stool','n.凳子','/stuːl/','/stuːl/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('specialty','n.特产；特色菜；专业；专长','/ˈspɛʃəlti/','/ˈspɛʃəlti/','noun',["They cook well overall, but their true specialty is pasta."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('elbow','v.用肘挤n.肘；弯头A','/ˈɛl.bəʊ/','/ˈɛl.boʊ/','noun',["the sides of windows, where the jamb makes an elbow with the window back","He elbowed his way through the crowd."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stoop','vi.弯腰，俯身n.弯腰，曲背A','/stuːp/','/stuːp/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vary','vi.改变，变化','/ˈvɛəɹi/','/ˈvæɹi/','noun',["He varies his magic tricks so as to minimize the possibility that any given audience member will see the same trick twice.","You should vary your diet. Eating just bread will do you harm in the end.","His mood varies by the hour."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coherent','adj.黏着的，黏附的；条理清楚的，连贯的','/kəʊˈhɪəɹənt/','/koʊˈhiɹənt/','adjective',[]);
