INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behalf','n.利益','','','',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ponder','v.思索，考虑，沉思','/ˈpɒn.də(ɹ)/','/ˈpɑn.dɚ/','noun',["I lit my pipe and had a ponder about it, but reached no definite conclusion.","I have spent days pondering the meaning of life."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('objective','adj.客观的，真实的n.目标，目的','/ɒbˈd͡ʒɛk.tɪv/','/əbˈd͡ʒɛk.tɪv/','noun',[]);
