INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exert','vt.尽；施加<','/ɪɡˈzɜːt/','/ɪɡˈzɝt/','verb',["I exerted myself in today''s training.","He considered exerting his influence on John to gain an advantage for himself."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scandal','n.丑闻；恶意诽谤；流言蜚语；反感，愤慨','/ˈskændəl/','/ˈskændəl/','noun',["Their affair was reported as a scandal by most tabloids.","The incident brought considerable scandal to his family.","When their behaviour was made public it caused a great scandal."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('composite','adj.合成的，复合的n.混合物，合成物','/ˈkɒmpəzɪt/','/kəmˈpɑzɪt/','noun',["I composited an image using computer software.","composite portraiture; a composite photograph"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hinder','vt.阻止，妨碍','/ˈhɪndə/','/ˈhɪndɚ/','verb',["A drought hinders the growth of plants.","She hindered a man from committing suicide."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horrible','adj.令人恐怖的，可怕的；极讨厌的，使人不愉快的','/ˈhɑɹɪbəl/','/ˈhɑɹɪbəl/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('freelance','adj.自由职业的','/ˈfɹiːlɑːns/','/ˈfɹiːlɑːns/','noun',["He was a freelance writer for several magazines."]);
