INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scent','n.气味；香味；香水','/sɛnt/','/sɛnt/','noun',["the scent of a skunk","The dogs lost the scent.","I believe the bloodhound has the best scent of all dogs."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('injury','n.损伤，损害，毁坏','/ˈɪn.dʒə.ɹi/','/ˈɪn.dʒə.ɹi/','noun',["The passenger sustained a severe injury in the car accident.","Slander is an injury to the character."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('exhibit','vt.展出，陈列','/ɛɡ-/','/ɛɡ-/','noun',["The museum''s new exhibit is drawing quite a crowd.","Exhibit A is this photograph of the corpse.","He wanted to exhibit his baseball cards."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mushroom','n.蘑菇','/ˈmʌʃˌɹuːm/','/ˈmʌʃˌɹuːm/','noun',["Some mushrooms are edible and taste good, while others are poisonous and taste foul.","The town’s population mushroomed from 10,000 to 110,000 in five years.","We used to go mushrooming in the forest every weekend."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alcohol','n.酒精，乙醇','/ˈæl.kə.hɒl/','/ˈæl.kə.hɑl/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('deny','vt.否认，否定；拒绝<','/dɪˈnaɪ/','/dɪˈnaɪ/','verb',["I wanted to go to the party, but I was denied.","Everyone knows he committed the crime, but he still denies it.","My father denied me a good education."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('trench','n.沟，沟渠','/tɹɛntʃ/','/tɹɛntʃ/','noun',["to trench land for the purpose of draining it","to trench a garden for certain crops"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('miserable','adj.痛苦的；悲惨的','/ˈmɪz(ə)ɹəbəl/','/ˈmɪz(ə)ɹəbəl/','noun',["He''s good at some sports, like tennis, but he''s just miserable at football.","a miserable sinner"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('subtract','vt.减','/səbˈtɹækt/','/səbˈtɹækt/','verb',["If you subtract the $100 for gas from the total cost, it was a fairly inexpensive trip."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hurricane','n.飓风','/ˈhʌɹɪkən/','/ˈhɝɪˌkeɪn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hike','vi.徒步旅行n.徒步旅行；增加，上升vt.提高','/haɪk/','/haɪk/','noun',["The tenants were not happy with the rent hike.","Don''t forget to bring the map when we go hiking tomorrow.","She hiked her skirt up."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glory','n.光荣，荣誉；荣耀的事','/ˈɡlo(ː)ɹi/','/ˈɡlo(ː)ɹi/','noun',[]);
