INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('secondary','adj.次要的，二级的；中级的；第二的A','/ˈsɛkənd(ə)ɹɪ/','/ˈsɛkənˌdɛɹi/','noun',["the secondary, or undersheriff, of the city of London","There are four secondaries in this district, each with several thousand pupils.","the work of secondary hands"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('badge','n.徽章','/bædʒ/','/bædʒ/','noun',["the badge of a society; the badge of a policeman","He has got his badge, and piked: He was burned in the hand, and is at liberty.","When you have checked in to the site from ten different cities, you unlock the Traveller badge."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mission','n.使命，任务；使团，代表团','/ˈmɪʃn̩/','/ˈmɪʃn̩/','noun',["Many cities across the Americas grew from Spanish missions."]);
