INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overcome','vt.战胜，克服','/ˌəʊvəˈkʌm/','/ˌoʊvəɹˈkʌm/','noun',["to overcome enemies in battle","We shall overcome.","I was overcome with anger."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sum','v.合计，总计n.总数，和；金额；算术题','/sʌm/','/sʌm/','noun',["The sum of 3 and 4 is 7.","We''re learning about division, and the sums are tricky.","a tidy sum"]);
