INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('audit','vt.审计，核对；旁听','/ɔː.dɪt/','/ɔː.dɪt/','noun',["National Assembly audit","to audit the accounts of a treasure, or of parties who have a suit depending in court"]);
