INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('civilian','adj.平民的；民用的<n.平民','/sɪˈvɪljən/','/sɪˈvɪljən/','noun',["Three civilians were apprehended by the soldiers and taken away in a military vehicle.","The bathroom was for employees only, so no civilians were allowed to use it.","He worked as a civilian journalist for ten years before being employed by the public broadcaster."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('audio','adj.听觉的；声音的','/ˈɔː.di.əʊ/','/ˈɔ.di.oʊ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('offensive','adj.冒犯的，攻击的；讨厌的<n.攻势，进攻','/əˈfɛnsɪv/','/əˈfɛnsɪv/','noun',["The Marines today launched a major offensive.","He took the offensive in the press, accusing his opponent of corruption.","An offensive smell."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('texture','n.质地，纹理，结构','/ˈtɛkstʃə(ɹ)/','/ˈtɛkstʃə(ɹ)/','noun',["The beans had a grainy, gritty texture in her mouth.","The piece of music had a mainly homophonic texture.","Drag the trowel through the plaster to texture the wall."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('slipper','n.便鞋，拖鞋','','','noun',["Get out of bed, put on your slippers, and come downstairs.","O! trustless state of earthly things, and slipper hope / Of mortal men. — Spenser."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('launch','vt.发射；使下水，发动；开展n.发射；下水；新产品的投产或投放','/lɔːnt͡ʃ/','/lɔnt͡ʃ/','noun',["book launch","The navy launched another ship.","NASA launched several unmanned rockets before launching any of the Mercury astronauts."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('amid','prep.在…中间，被…围绕','/əˈmɪd/','/əˈmɪd/','preposition',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('beloved','adj.受爱戴的，敬爱的n.爱人，所爱的人','','','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confirm','vt.证实；确认<；批准；确认；巩固，加强','/kənˈfɜːm/','/kənˈfɝm/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bud','vi.发芽，萌芽n.芽，花苞','/bʌd/','/bʌd/','noun',["After a long, cold winter, the trees finally began to produce buds.","breast buds","In this slide, you can see a yeast cell forming buds."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cloak','n.外套，斗篷vt.掩盖，蒙蔽','/ˈkloʊk/','/ˈkloʊk/','noun',["Night hid her movements with its cloak of darkness.","The ship cloaked before entering the enemy sector of space."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gallon','n.加仑','/ˈɡælən/','/ˈɡælən/','noun',["The pipe burst and gallons of water flooded into the kitchen."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('bug','n.臭虫A；小毛病A；窃听器vt.在…装窃听器','/bʌɡ/','/bʌɡ/','noun',["These flies are a bother. I’ll get some bug spray and kill them.","The software bug led the computer to calculate 2 plus 2 as 3.","He’s got the flu bug."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cricket','n.板球；蟋蟀','/ˈkɹɪk.ɪt/','/ˈkɹɪk.ɪt/','noun',[]);
