INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appoint','vt.任命，委任；约定，指定','/əˈpɔɪnt/','/əˈpɔɪnt/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vast','adj.巨大的；辽阔的；大量的；巨额的','/vɑːst/','/væst/','noun',["The Sahara desert is vast."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intervene','vi.插手，干预，调停；插入，介入','','','verb',["The police had to be called to intervene in the fight.","An instant intervened between the flash and the report.","Nothing intervened to prevent the undertaking."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ignite','v.点火，引燃','/ɪɡˈnaɪt/','/ɪɡˈnaɪt/','verb',["to ignite iron or platinum"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('symbol','n.符号；标志，象征','/ˈsɪmbəl/','/ˈsɪmbəl/','noun',["$ is the symbol for dollars in the US and some other countries.","The lion is the symbol of courage; the lamb is the symbol of meekness or patience.","The Apostles, Nicene Creed and the confessional books of Protestantism, such as the Augsburg Confession of Lutheranism are considered symbols."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('declare','v.宣布，宣称；断言；公布，发表，披露','/dɪˈkleə/','/dəˈklɛɚ/','verb',["He declared him innocent.","declare bankruptcy","Houghton and Sunderland South was the first constituency to declare in the 2015 general election."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('revelation','n.揭示，透露，显示；被揭示的真相；新发现','/ɹɛvəˈleɪʃən/','/ɹɛvəˈleɪʃən/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('available','adj.可用的，可得到的；可以见到的，随时可来的','/əˈveɪləb(ə)l/','/əˈveɪləb(ə)l/','adjective',["We have an available candidate.","The list shows the available products in the store.","This is an available plea."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advocate','n.提倡者，鼓吹者，支持者vt.提倡，鼓吹','/ˈæd.və.keɪt/','/ˈæd.və.keɪt/','noun',["Since she started working with her advocate, she has become much more confident.","I like trees, but I do not advocate living in them.","We have been advocating for changes in immigration law."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('confine','vt.限制，局限于；管制，禁闭','/ˈkɒnfaɪn/','/ˈkɒnfaɪn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('quest','vi.搜寻，探求n.搜寻，探求','/kwɛst/','/kwɛst/','noun',["to rove in quest of game, of a lost child, of property, etc."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frequency','n.频率；【物】周率','/ˈfɹiːkwənsi/','/ˈfɹiːkwənsi/','noun',["The frequency of bus service has been improved from one every 15 to one every 12 minutes.","The FAQ addresses questions that come up with some frequency.","Broadcasting live at a frequency of 98.3 megahertz, we’re your rock alternative!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('horizontal','adj.地平线的；水平的','/ˌhɒɹɪˈzɒntəl/','/ˌhɔːɹəˈzɑːntəl/','noun',["1667: As when the Sun new ris''n / Looks through the Horizontal misty Air — John Milton, Paradise Lost, Book 1, ll. 594-5"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('luggage','n.行李','/ˈlʌɡɪd͡ʒ/','/ˈlʌɡɪd͡ʒ/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drawback','n.欠缺，缺点','/ˈdɹɔːˌbæk/','/ˈdɹɔːˌbæk/','noun',["Poor fuel economy is a common drawback among larger vehicles."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('missile','n.导弹，发射物','/ˈmɪsaɪl/','/ˈmɪsaɪl/','noun',["The Rhodians, who used leaden bullets, were able to project their missiles twice as far as the Persian slingers, who used large stones.","That missile is explosive enough to kill hundreds."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dynamic','adj.动力的，电动的；有生气的','/daɪˈnæ.mɪk/','/daɪˈnæ.mɪk/','noun',["Watch the dynamic between the husband and wife when they disagree.","The study of fluid dynamics quantifies turbulent and laminar flows.","If you pay attention to the dynamics as you play, it''s a very moving piece."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sector','n.部分；部门；防御地段，防区；扇形','/ˈsɛk.təɹ/','/ˈsɛk.təɹ/','noun',["public sector;  private sector"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passion','n.热情，激情；酷爱；激怒，大怒','[ˈpʰæʃən]','[ˈpʰæʃən]','noun',["We share a passion for books.","It started as a hobby, but now my motorbike collection has become my passion.","We shared a night of passion."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('generate','vt.产生，发生','/ˈdʒɛn.əɹ.eɪt/','/ˈdʒɛn.ə.ɹeɪt/','verb',["The discussion generated an uproar.","Adding concentrated sulphuric acid to water generates heat.","They generated many offspring."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('extreme','adj.末端的，尽头的；极度的，极端的n.极端，极度','/ɛkˈstɹiːm/','/ɪkˈstɹim/','noun',["extremes of temperature","Some people go to extremes for attention on social media.","At the extreme edges, the coating is very thin."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tuck','vt.卷起；塞进','/tʌk/','/tʌk/','noun',["Tuck in your shirt.  I tucked in the sheet.  He tucked the $10 bill into his shirt pocket.","The sofa tucks nicely into that corner.  Kenwood House is tucked into a corner of Hampstead Heath.","The diver tucked, flipped, and opened up at the last moment."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coordinate','adj.同等的；并列的A；坐标的n.坐标','','','noun',["Give me your coordinates and we''ll come and rescue you.","I was playing tennis for the first time, and it was difficult to coordinate.","The outfit you''re wearing doesn''t coordinate."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('athlete','n.运动员','/ˈæθ.lit/','/ˈæθ.lit/','noun',["She''s the first athlete in her sport to obtain a corporate sponsor."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('astronomy','n.天文学','/æˈstɹɑnəˌmi/','/æˈstɹɑnəˌmi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tube','n.管，软管；电子管，显像管；电视；地铁','/tjuːb/','/tjuːb/','noun',["A tube of toothpaste.","I took the tube to Waterloo and walked the rest of the way.","Are you just going to sit around all day and watch the tube?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('naval','adj.海军的，军舰的','/ˈneɪvəl/','/ˈneɪvəl/','adjective',["naval architect"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dismay','n.惊恐，惊愕；失望，绝望vt.使惊恐，使惊愕；失望，绝望','/dɪsˈmeɪ/','/dɪsˈmeɪ/','noun',["He looked in dismay at the destruction of the town caused by the hurricane."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expend','vt.消费，花费','/ɛkˈspɛnd/','/ɛkˈspɛnd/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hint','v.暗示，示意n.暗示，提示；线索','/hɪnt/','/hɪnt/','noun',["I needed a hint to complete the crossword.","He gave me a hint that my breath smelt.","I could taste a hint of lemon in the wine."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('demonstrate','vt.论证，证实；展示，说明<','/ˈdɛmənstɹeɪt/','/ˈdɛmənstɹeɪt/','verb',["Can you demonstrate the new tools for us?","Those people outside are demonstrating against the election results."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kid','v.戏弄，取笑n.小孩，儿童','/kɪd/','/kɪd/','noun',["He treated the oxen like they didn''t exist, but he treated the goat kid like a puppy.","She''s a kid. It''s normal for her to have imaginary friends.","He''s been living in Los Angeles for years now, but he''s a Florida kid."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('throne','n.王位，君权','[θɹəʊn]','[θɹoʊn]','noun',["He approached the throne reverently."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('monument','n.纪念碑，纪念馆','/ˈmɒnjʊmənt/','/ˈmɑnjəmənt/','noun',["There is a monument on the town green to the soldiers who died in World War I."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inventory','n.详细目录；存货清单，物品清单，库存物品','/ɪnˈvɛn.tə.ɹi/','/ɪnˈvɛn.tə.ɹi/','noun',["Due to an undersized inventory at the Boston outlet, customers had to travel to Providence to find the item.","The inventory included several items that one wouldn''t normally think to find at a cheese shop.","This month''s inventory took nearly three days."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vivid','adj.鲜艳的；生动的，栩栩如生的','/ˈvɪvɪd/','/ˈvɪvɪd/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kin','n.家属；亲戚；血缘关系A；家族','/kɪn/','/kɪn/','noun',["It turns out my back-fence neighbor is kin to one of my co-workers."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flush','v.冲洗；使流<；脸红adj.齐平的，同高的n.脸红A<','/ˈflʌʃ/','/ˈflʌʃ/','noun',["The hunters flushed the tiger from the canebrake.","A covey of quail flushed from the undergrowth."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('manoeuvre','v.演习；谨慎地运用技巧移动，运动；熟练而巧妙地引导某人','/məˈnuːvə/','/məˈnuːvɚ/','noun',["Joint NATO maneuvers are as much an exercise in diplomacy as in tactics and logistics.","Parallel parking can be a difficult maneuver.","The patriarch maneuvered till his offspring occupied countless key posts"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('kit','v.装备An.成套工具；配套元件','/kɪt/','/kɪt/','noun',["1961 18 Jan, Guardian (cited after OED):","Always carry a good first-aid kit.","I built the entire car from a kit."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('virtue','n.美德，德行；优点，长处A<','/-tjuː/','/ˈvɝtʃu/','noun',["Without virtue, there is no freedom."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('turnover','n.翻倒，翻转；人员调整；周转；成交量，营业额','','','noun',["The company had an annual turnover of $500,000.","High staff-turnover can lead to low morale amongst employees","They only served me one apple turnover for breakfast."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('mortal','adj.致命的；终有一死的A；你死我活的，不共戴天的n.凡人','/ˈmɔːtəl/','','noun',["Her wisdom was beyond that of a mere mortal.","mortal enemy","mortal wit or knowledge; mortal power"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gradual','adj.逐渐的，逐步的','/ˈɡɹɛdʒɘl/','/ˈɡɹædʒuəl/','noun',["a gradual increase of knowledge; a gradual decline"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('brutal','adj.残忍的；严峻的，严酷的','/ˈbɹuːtəl/','/ˈbɹuːtəl/','adjective',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('preclude','vt.妨碍，阻止','/pɹiːˈkluːd/','/pɹiːˈkluːd/','verb',["It has been raining for days, but that doesn’t preclude the possibility that the skies will clear by this afternoon!"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corrupt','adj.腐败的，贪污的vt.使腐败，使败坏<','/kəˈɹʌpt/','/kəˈɹʌpt/','verb',["to corrupt a book","The government here is corrupt, so we''ll emigrate to escape them.","It turned out that the program was corrupt - that''s why it wouldn''t open."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('transmit','vt.传播，发射；传递；传导','/tɹænsˈmɪt/','/tɹænsˈmɪt/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('commemorate','vt.纪念，庆祝','/kəˈmɛməˌɹeɪt/','/kəˈmɛməˌɹeɪt/','verb',["On November 11th we commemorate the fallen with a march.","The cenotaph commemorates the fallen."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('consumption','n.消费，消耗<','/kənˈsʌmp.ʃən/','/kənˈsʌmp.ʃən/','noun',["The consumption of snails as food is more common in France than in England.","gross national consumption","The fire''s consumption of the forest caused ecological changes."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('technology','n.工艺，技术','/tɛkˈnɒlədʒi/','/tɛkˈnɒlədʒi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('voltage','n.电压','/voʊltɪdʒ/','/voʊltɪdʒ/','noun',["Be careful when opening high-voltage equipment."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('vaccine','n.疫苗','/vækˈsaɪn/','/vækˈsaɪn/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drought','n.旱灾，干旱A','/dɹaʊt/','[dɹʌʊt]','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('periodical','adj.周期的，定期的n.期刊，杂志','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leaflet','n.小叶，嫩叶；传单，活页','/ˈliːflɪt/','/ˈliːflɪt/','noun',["The new leaflets at the end of the branch were a lighter shade of green than the mature leaves.","A leaflet had been left under the car''s windshield wiper.","A sidewalk preacher gave an impassioned sermon while an assistant leafleted those who stayed to listen."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('punctual','adj.严守时刻的，准时的，正点的','/ˈpʌŋktjʊəl/','/ˈpʌŋktʃuəl/','adjective',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advertise','v.做广告','/ˈadvə(ɹ)taɪz/','/ˈadvə(ɹ)taɪz/','verb',["For personal needs, advertise on the internet or in a local newspaper.","Over the air, they advertise their product on drive-time radio talk shows and TV news shows."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('compromise','vi.妥协，折衷<n.妥协，折衷','/ˈkɒmpɹəˌmaɪz/','/ˈkɑmpɹəˌmaɪz/','noun',["a compromise of character or right","He tried to compromise the security in the computer by guessing the password."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('shampoo','n.洗发膏，香波；洗发，洗头vt.洗发，洗头','/ʃamˈpuː/','/ʃæmˈpuː/','noun',["I’m going to give the carpet a shampoo.","My neat-freak of a friend has been compulsively shampooing for every bath he has taken."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sack','n.袋，包，麻袋vt.解雇','/sæk/','/sæk/','noun',["The American sack of salt is 215 pounds; the sack of wheat, two bushels. — McElrath.","The sack of Rome.","He twisted his ankle sliding into the sack at second."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comparative','adj.比较的，相当的<','/kəmˈpæɹ.ə.tɪv/','/kəmˈpɛɹ.ə.tɪv/','noun',["comparative anatomy"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fringe','n.须边，边缘vt.成为…的边缘','/fɹɪndʒ/','/fɹɪndʒ/','noun',["the fringe of a picture","He lives in the fringe of London.","interference fringe"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('react','vi.作出反应，回应<；反对，起反作用','/ɹiːˈækt/','/ɹiːˈækt/','noun',["Sad reacts only","Every body reacts on the body that impels it from its natural state."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feedback','n.反馈','/ˈfiːdˌbæk/','/ˈfiːdˌbæk/','noun',["After you hand in your essays, I will give both grades and feedback.","The show ended with a riot of feedbacking guitars.","His employees feedbacked him a lot more than he wanted."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('justify','vt.证明…是正当的，认为有理','/ˈdʒʌstɪfaɪ/','/ˈdʒʌstɪfaɪ/','verb',["How can you justify spending so much money on clothes?","Nothing can justify your rude behaviour last night.","The text will look better justified."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('highjack','vt.劫持','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('roar','vi.吼叫，怒号A；轰鸣；咆哮','/ɹɔː/','/ɹɔɹ/','noun',["the roar of a motorbike","The audience roared at his jokes.","The lioness roared to scare off the hyenas."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('timber','n.木材，木料；树林','/ˈtɪmbə/','/ˈtɪmbə/','noun',["the timbers of a ship","timbering a roof"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('simulate','vt.模仿，模拟；假装，冒充','/-jə-/','/-jə-/','verb',["We will use a smoke machine to simulate the fog you will actually encounter."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inclusive','adj.包括的，包含的；范围广的','/ɪnˈkluːsɪv/','/ɪnˈkluːsɪv/','adjective',["an inclusive list of data formats","numbers 1 to 10 inclusive","The pronoun in \"If you want, we could go back to my place for coffee\" is an inclusive \"we\"."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spectacle','n.景象；奇观','/ˈspɛktəkl̩/','/ˈspɛktəkl̩/','noun',["The horse race was a thrilling spectacle.","He made a spectacle out of himself."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('efficiency','n.效率，功效','/ɪˈfɪʃn̩si/','/ɪˈfɪʃn̩si/','noun',["The efficiency of the planning department is deplorable.","The efficiency of this loudspeaker is 40%.","I have an efficiency available June through July."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ethnic','adj.种族的，民族的','/ˈɛθ.nɪk/','/ˈɛθ.nɪk/','noun',["There are many ethnic Indonesians in the Netherlands","I like to eat ethnic food"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overhead','adv.在头顶上，在空中adj.在头顶上的；架空的A','/ˈəʊvəˌhɛd/','/ˈoʊvɚˌhɛd/','noun',["Network overhead is the header data that is required to route and transport data over network, whereas fork overhead is the additional time and memory cost of creating and managing new processes within operating system.","Place your luggage in the overhead lockers.","birds flying overhead"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('comprehension','n.理解，领悟','/kɒmpɹɪˈhɛnʃn̩/','/kɒmpɹɪˈhɛnʃn̩/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('intact','adj.完整无缺的，未经触动的，未受损伤的','/ɪnˈtækt/','/ɪnˈtækt/','adjective',["I packed my belongings carefully so that they would survive the move intact.","The opposite of a circumcised penis is an intact penis."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('following','adj.接着的，下列的','/ˈfɒləʊɪŋ/','/ˈfɑloʊɪŋ/','verb',["Follow that car!","B follows A in the alphabet.","Follow these instructions to the letter."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('juvenile','adj.青少年的，少年特有的；幼稚的n.未成年人，少年','/ˈdʒuːvənaɪl/','/ˈdʒuːvənaɪl/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sympathetic','adj.同情的；共鸣的<','/ˌsɪmpəˈθɛtɪk/','/ˌsɪmpəˈθɛtɪk/','adjective',["John looked very upset. I gave him a sympathetic look.","Sympathetic magic is based on imitation or correspondence.","Sympathetic innervation involves epinephrine."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('freight','n.货物，客货；运费<','/fɹeɪt/','/fɹeɪt/','noun',["The freight was more expensive for cars than for coal.","The freight shifted and the trailer turned over on the highway.","They shipped it ordinary freight to spare the expense."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('botany','n.植物学','/-ɪ/','/-ɪ/','noun',["the botany of Greenland"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('range','n.范围；距离；领域<；排列；连续；脉vt.排列成行','/ɹeɪndʒ/','/ɹeɪndʒ/','noun',["We sell a wide range of cars.","One can use the speed of sound to estimate the range of a lightning flash.","This missile''s range is 500 kilometres."]);
