INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overseas','adv.在海外adj.外国的，海外的<','/ˌəʊvəˈsiːz/','/ˌəʊvəˈsiːz/','adjective',["Overseas branches of the company are doing well.","Overseas Chinese communities exist in North and South America.","Her overseas trip went well."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('overhear','vt.偶然听到，从旁听到','/oʊ.vɚˈhɪɚ/','/oʊ.vɚˈhɪɚ/','verb',["I was hanging clothes in the garden and I overheard the neighbours talking about Sheila''s pregnancy."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('impress','vt.印，盖印；留下印象，引人注目<n.印记','/ˈɪmpɹɛs/','/ˈɪmpɹɛs/','noun',["You impressed me with your command of Urdu.","Henderson impressed in his first game as captain.","That first view of the Eiger impressed itself on my mind."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leak','v.漏；泄漏n.漏洞，漏隙；泄漏，漏出','/liːk/','/liːk/','noun',["a leak in a boat","The babies'' diapers had big leaks.","The leaks by Chelsea Manning showed the secrets of the US military."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flaw','n.裂缝；缺陷','/ˈflɔː/','/ˈflɔ/','noun',["That vase has a flaw."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('feature','v.以…为特点n.特征，特色；特写','/ˈfiːtʃə/','/ˈfitʃɚ/','noun',["one of the features of the landscape"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lean','vi.倾斜；屈身；倚，靠；依赖adj.瘦的，无脂肪的','/liːn/','/liːn/','noun',["The trees had various leans toward gaps in the canopy.","She leaned out of the window.","I’m leaning towards voting Conservative in the next election.  The Hispanic vote leans Democratic."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assert','vt.断言，宣称<','/əˈsɜːt/','/əˈsɝt/','noun',["He would often assert that there was life on other planets.","Salman Rushdie has asserted his right to be identified as the author of this work.","to assert our rights and liberties"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('climax','n.顶点；高潮','/ˈklaɪmæks/','/ˈklaɪmæks/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('recall','vt.回忆，回想<；撤销，收回','','','noun',["He was recalled to service after his retirement."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flap','v.拍打，拍动n.垂下物；帽檐；袋盖；慌乱，紧张','','','',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('leap','vi.跳，跳跃<n.跳跃，飞跃','/liːp/','/liːp/','noun',["It''s quite a leap to claim that those cloud formations are evidence of UFOs.","to leap a wall or a ditch","to leap a horse across a ditch"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('objection','n.反对，异议','/əbˈdʒɛkʃən/','/əbˈdʒɛkʃən/','noun',["I have no objection to any person''s religion."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dispute','vi.争论，争执n.争论，辩论','/ˈdɪs.pjuːt/','/dɪsˈpjuːt/','noun',["Some residents disputed the proposal, saying it was based more on emotion than fact.","to dispute assertions or arguments"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blouse','n.女衬衫','/blaʊs/','/blaʊs/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('observation','n.观察；观测；监视；观察资料或报告；言论','/ˌɒbzəˈveɪʃ(ə)n/','/-ˈveɪʃn̩/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tremble','vi.发抖，颤抖；摇动，晃动','/ˈtɹɛmbl̩/','/ˈtɹɛmbl̩/','noun',["Her lip started to tremble as she burst into tears"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('inhabitant','n.居民，住户','/ɪnˈhæ.bɪ.tənt/','/ɪnˈhæ.bɪ.tənt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fraction','n.碎片；小部分，一点儿；分数','/ˈfɹæk.ʃən/','/ˈfɹæk.ʃən/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('token','adj.象征性的n.表示，象征；标志，记号；礼券，代金券；信物；纪念品；筹码','/ˈtəʊkən/','/ˈtoʊkən/','noun',["According to the Bible, the rainbow is a token of God''s covenant with Noah.","Please accept this bustier as a token of our time together.","A book token is the easiest option for a Christmas gift."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('filter','vi.滤过，渗透n.滤器；滤纸；滤嘴','/ˈfɪltə/','/ˈfɪltɚ/','noun',["He runs an email filter to catch the junk mail.","He''s got no filter, and he''s always offending people as a result.","If (1) the universal set (here, the set of natural numbers) were called a \"large\" set, (2) the superset of any \"large\" set were also a \"large\" set, and (3) the intersection of a pair of \"large\" sets were also a \"large\" set, then the set of all \"large\" sets would form a filter."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spaceship','n.宇宙飞船','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cease','n./','/siːs/','/siːs/','noun',["And with that, his twitching ceased.","And with that, he ceased twitching."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('emotion','n.情绪；情感','/iˈmoʊʃən/','/iˈmoʊʃən/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assess','vt.估价，评价','/əˈsɛs/','/əˈsɛs/','verb',["He assessed the situation.","A $10.00 late fee will be assessed on all overdue accounts.","Once you''ve submitted a tax return, the Tax Department will assess the amount of tax you still owe."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('robe','n.长袍，上衣','/ɹəʊb/','/ɹoʊb/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('prescription','n.药方，处方','/pɝˈskɹɪpʃən/','/pɝˈskɹɪpʃən/','noun',["\"Jurisdiction to prescribe\" is a state''s authority to make its laws applicable to certain persons or activities. -- Richard G. Alexander, Iran and Libya Sanctions Act of 1996: Congress exceeds its jurisdiction to prescribe law. Washington and Lee Law Review, 1997.","The surgeon wrote a prescription for a pain killer and physical therapy.","The pharmacist gave her a bottle containing her prescription."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('spectator','n.观众；旁观者','/spɛkˈteɪtə/','/ˈspɛkteɪtɚ/','noun',["The cheering spectators watched the fireworks."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('behaviour','n.行为，举止；特性；运转情况A','/bɪˈheɪvjə/','/bɪˈheɪvjə/','noun',["She can''t stop the strange behaviour because she has OCD (obsessive-compulsive disorder)."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('scarce','adj.缺乏的，不足的；稀少的，罕见的','/ˈskɛəs/','/ˈskɛɚs/','adjective',[]);
