INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('argument','n.争论，辩论；论据，论点','/ˈɑːɡjʊmənt/','/ˈɑɹɡjumənt/','noun',["Parameters are like labeled fillable blanks used to define a function whereas arguments are passed to a function when calling it, filling in those blanks.","The altitude is the argument of the refraction."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('utter','adj.彻底的，完全的vt.说，发出','/ˈʌtə/','/ˈʌtɚ/','adjective',["utter ruin; utter darkness"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('adequate','adj.足够的，充分的；恰当的','','','verb',["an adequate definition"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hopeful','adj.有希望的，给以人希望的；抱有希望的；充满希望的','/ˈhəʊpfəl/','/ˈhəʊpfəl/','noun',["Several presidential hopefuls are campaigning in New Hampshire this week.","I am hopeful that I will recover from the disease."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sausage','n.香肠，腊肠','/ˈsɑsɪd͡ʒ/','/ˈsɔsɪd͡ʒ/','noun',["my little sausage"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tremendous','adj.巨大的，极大的','/tɹəˈmɛndəs/','/tɹəˈmɛndəs/','adjective',["Van Beethoven''s ninth symphony is a tremendous piece of music.","There was a tremendous outpouring of support."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('escalate','v.逐步增长或发展，更紧张；逐步上升，逐步加强，扩大','/ˈɛs.kə.leɪt/','/ˈɛs.kə.leɪt/','verb',["The shooting escalated the existing hostility.","The tech 1 escalated the caller to a tech 2."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('condense','v.压缩，凝结；精简，压缩','/kənˈdɛns/','/kənˈdɛns/','verb',["An abridged dictionary can be further condensed to pocket size.","Water condenses on the window on cold days because of the warm air inside."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('divert','vt.使转向，使改道；转移，转移…的注意力<；使娱乐，使消遣','/daɪˈvɜːt/','/daɪˈvɝt/','verb',["The workers diverted the stream away from the road.","Don''t let him divert your attention; keep your eye on the ball."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hygiene','n.卫生','/ˈhaɪˌdʒiːn/','/ˈhaɪˌdʒiːn/','noun',["Hygiene is an important consideration in places where food is prepared.","They have poor personal hygiene."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('justice','n.正义；公平；审判，司法，法律制裁','/ˈdʒʌs.tɪs/','/ˈdʒʌs.tɪs/','noun',["the justice of a description","Justice was served.","to demand justice"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('conspicuous','adj.显眼的；明显的','/kənˈspɪk.ju.əs/','/kənˈspɪk.ju.əs/','adjective',["He was conspicuous by his absence.","He had a conspicuous lump on his forehead."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tag','n.标签，货签vt.贴标签于','/teɪɡ/','/teɪɡ/','noun',["The subwoofer in the trunk was so loud, it vibrated the tag like an aluminum can.","The tag was applied at second for the final out.","The  tag conveys sarcasm in Internet slang."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('verse','n.韵文，诗；诗节，诗句','/ˈvɜːs/','/ˈvɝs/','noun',["Restoration literature is well known for its carefully constructed verse.","The restrictions of verse have been steadily relaxed over time.","Note the shift in tone between the first verse and the second."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('furious','adj.狂怒的；狂暴的，猛烈的','/ˈfjʊə.ɹɪəs/','/ˈfjɝ.i.əs/','adjective',["a furious animal; parent furious at their child''s behaviour","a furious stream; a furious wind or storm"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('obesity','n.肥大，肥胖','','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tan','vi.晒黑adj.棕褐色的n.黝黑','/tæn/','/tæn/','noun',["She still has a tan from her vacation in Mexico.","Mine is the white car parked next to the tan pickup truck.","You’re looking very tan this week."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tar','n.柏油，焦油','/tɑː/','/tɑɹ/','noun',["The allegations tarred his name, even though he was found innocent."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('individual','adj.个人的；单独的；独特的<n.个人，个体','/ˌɘndɘˈvɘd͡ʒɘl/','/ˌɪndəˈ-/','noun',["He is an unusual individual.","As we can''t print them all together, the individual pages will have to be printed one by one.","individual personal pension; individual cream cakes"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('briefcase','n.公文包，公事包','/ˈbɹiːfˌkeɪs/','/ˈbɹiːfˌkeɪs/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('snowstorm','n.暴风雪A','/ˈsnəʊstɔːm/','/ˈsnəʊstɔːm/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tax','n.税；负担vt.对…征税；使负重担；使受压力','/tæks/','/tæks/','noun',["a heavy tax on time or health"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('constrain','vt.束缚，限制；强迫，强制','/kənˈstɹeɪn/','/kənˈstɹeɪn/','verb',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('excitement','n.刺激；激动，兴奋','/ɪkˈsaɪtmənt/','/ɪkˈsaɪtmənt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('blueprint','n.蓝图；方案','/ˈbluːˌpɹɪnt/','/ˈbluːˌpɹɪnt/','noun',["The architect blueprinted the renovation plan once the client had signed off.","They blueprinted every aspect of the first phase of the operation."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('interim','adj.暂时的，临时的n.间歇；过渡期间','/ˈɪntəɹɪm/','/ˈɪntəɹɪm/','noun',["His car is in the shop, but they gave him a rental to drive in the interim.","Iraq''s government is interim.","You are interim manager until he returns from hospital."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('testimony','n.证据；证词；表明，说明','/ˈtɛstɪməni/','/ˈtɛstɪmoʊni/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('enforce','vt.实施，执行<；强制<','/ɪnˈfɔːs/','/ɪnˈfɔːs/','verb',["The police are there to enforce the law.","The victim was able to enforce his evidence against the alleged perpetrator.","to enforce a passage"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glitter','vi.闪耀n.光辉，灿烂','/ˈɡlɪtə(ɹ)/','/ˈɡlɪtɚ/','noun',["a glittering sword","the glittering scenes of a court"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('departure','n.离开，起程','/dɪˈpɑː(ɹ)tjə(ɹ)/','','noun',["The departure was scheduled for noon.","There are several significant departures, however, from current practice.","The area is computed by latitudes and departures."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fragile','adj.易碎的，易损的；脆弱的，易受伤害的','/ˈfɹædʒaɪl/','/ˈfɹædʒəl/','adjective',["He is a very fragile person and gets easily depressed."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('reflexion','n.映像，倒影；反省，沉思','/ɹɪˈflɛkʃ(ə)n/','','noun',["The dog barked at his own reflection in the mirror.","After careful reflection, I have decided not to vote for that proposition.","It is a reflection on his character that he never came back to see them."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('cab','n.出租汽车；轻便马车；司机室，驾驶室A','/kæb/','/kæb/','noun',["a cab ride"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sociology','n.社会学','/ˌsəʊsiːˈɒlədʒiː/','/ˌsəʊsiːˈɒlədʒiː/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('gigantic','adj.巨大的，庞大的','/dʒaɪˈɡæntɪk/','/dʒaɪˈɡæntɪk/','adjective',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('flee','vi.逃走；逃避；消失','/fliː/','/fliː/','verb',["The prisoner tried to flee, but was caught by the guards.","Many people fled the country as war loomed.","Ethereal products flee once freely exposed to air."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('distinct','adj.清楚的，明显的；截然不同的','/dɪsˈtɪŋkt/','/dɪsˈtɪŋkt/','adjective',["Her voice was distinct despite the heavy traffic.","Horses are distinct from zebras.","Olga''s voice is quite distinct because of her accent."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('geology','n.地质','/dʒɪˈɒlədʒɪ/','/dʒiˈɑlədʒi/','noun',["The geology of the Alps."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hedge','n.篱笆，树篱；障碍物vt.保护…以免；预防','/hɛdʒ/','/hɛdʒ/','noun',["He trims the hedge once a week.","A hedge is an investment position intended to offset potential losses/gains that may be incurred by a companion investment. In simple language, a hedge is used to reduce any substantial losses/gains suffered by an individual or an organization."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weep','v.哭泣；流泪n.悲叹，哀悼，为…伤心','/wiːp/','/wiːp/','noun',["Sometimes you just have to have a good weep.","a weeping spring, which discharges water slowly"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('tune','v.调音；调频；调整；调节n.调子，曲调','/tjuːn/','/t(j)un/','noun',["Your engine needs a good tune.","This piano is not in tune.","to tune a piano or a violin"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hoist','vt.举起，升起，吊起','/hɔɪst/','/hɔɪst/','noun',["Give me a hoist over that wall."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('aware','adj.知道的，意识到的','/əˈweːɹ/','/əˈwɛɚ/','adjective',["Stay aware! Don''t let your guard down.","Are you aware of what is being said about you?"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('numerical','adj.数字的，用数字表示的','/n(j)uˈmɛɹɪkəl/','/n(j)uˈmɛɹɪkəl/','adjective',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('drama','n.戏剧；剧本；戏剧性事件或场面','/ˈdɹæmə/','/ˈdɹɑmə/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('award','n.奖vt.授予，奖给','/əˈwɔːd/','/əˈwɔɹd/','noun',["the arbitrators awarded damages to the complainant","Four or five of these medals are awarded every year.","He was awarded the Nobel Prize for Literature."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('eligible','adj.有条件被选中的，有资格当选的；合格的','/ˈɛlɪdʒəb(ə)l/','/ˈɛlɪdʒəb(ə)l/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('stove','n.炉子，火炉','/stəʊv/','/stoʊv/','noun',["to stove feathers","to stove orange trees"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('alarm','n.警报；惊恐，惊慌vt.使惊恐，惊动，惊吓A；向…报警；警告','/əˈlɑːm/','/əˈlɑɹm/','noun',["The clock radio is a friendlier version of the cold alarm by the bedside.","You should set the alarm on your watch to go off at seven o''clock."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('appraisal','n.估计，估量；评价','/əˈpɹeɪzəl/','/əˈpɹeɪzəl/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('weed','v.锄草n.杂草，野草','/wiːd/','/wiːd/','noun',["If it isn''t in a straight line or marked with a label, it''s a weed."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glacier','n.冰河，冰川','/ˈɡleɪ.ʃɚ/','/ˈɡleɪ.ʃɚ/','noun',["They warned that the effects of glacier melting on water resources are becoming “increasingly serious” for China."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('balloon','n.气球','/bəˈluːn/','/bəˈlun/','noun',["the balloon of St. Paul''s Cathedral in London","His stomach ballooned from eating such a large meal."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('orientation','n.方向，方位，定位；熟悉，适应；〈主美〉情况介绍','/ˌɔɹiɛnˈteɪʃən/','/ˌɔɹiɛnˈteɪʃən/','noun',["The homing instinct in pigeons is an example of orientation."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('motion','n.运动，动；提议，动议vt.向…示意A','/ˈməʊʃən/','/ˈmoʊʃən/','noun',["The motion to amend is now open for discussion.","He motioned for me to come closer."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('idle','adj.空闲的，闲置的；无用的，无效的；懒散的vt.浪费，虚度','/ˈaɪd(ə)l/','/ˈaɪd(ə)l/','noun',["My computer hibernates after it has been idle for 30 minutes.","idle workmen","an idle fellow"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('limited','adj.有限的，被限制的','/ˈlɪmɪtɪd/','/ˈlɪmɪtɪd/','verb',["I''m limiting myself to two drinks tonight.","The sequence limits on the point a.","a limiting friar"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plight','n.困境，苦境','/plaɪt/','/plaɪt/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('hail','vi.下雹vt.向…欢呼，欢迎An.冰雹','/heɪl/','/heɪl/','noun',["They say it''s going to hail tomorrow.","The cloud would hail down furiously within a few minutes."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fearful','adj.可怕的','/ˈfɪəfəl/','/ˈfɪɹfəl/','adjective',["a fearful boy"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('accent','n.腔调；口音A；重音','/ˈak.sənt/','/ˈak.sənt/','noun',["In the word \"careful\", the accent is placed on the first syllable.","At this hotel, the accent is on luxury.","The name Cézanne is written with an acute accent."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('passive','adj.被动的，消极的<','/ˈpæs.ɪv/','/ˈpæs.ɪv/','noun',["He remained passive during the protest.","a passive balloon; a passive aeroplane; passive flight, such as gliding and soaring"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lorry','n.卡车，运货汽车','/ˈlɒɹi/','/ˈlɒɹi/','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fragment','n.碎片；小部分，片断<','/ˈfɹæɡmənt/','/ˈfɹæɡmənt/','noun',["I heard a small fragment of the conversation."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('carrier','n.运送者，载体；携带者','/ˈkæ.ɹɪ.ə/','/ˈkæ.ɹɪ.ə/','noun',["aircraft carrier","inert carrier gas, which transports a chemical reactant"]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('response','n.回答，回音；反应，响应','/ɹɪˈspɒns/','','noun',[]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('category','n.种类','/ˈkætəˌɡɔɹi/','/ˈkætəˌɡɔɹi/','noun',["I wouldn''t put this book in the same category as the author''s first novel.","Just as a monoid consists of an underlying set with a binary operation \"on top of it\" which is closed, associative and with an identity, a category consists of an underlying digraph with an arrow composition operation \"on top of it\" which is transitively closed, associative, and with an identity at each object. In fact, a category''s composition operation, when restricted to a single one of its objects, turns that object''s set of arrows (which would all be loops) into a monoid."]);
INSERT INTO graduate (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('rival','adj.竞争的，对手的n.竞争者，对手vt.竞争，对抗','/ˈɹaɪvəl/','/ˈɹaɪvəl/','noun',["Chris is my biggest rival in the 400-metre race.","As a social historian, he has no rival.","to rival somebody in love"]);
